import type { ClientAdapter, NormalizableTypes, SnowflakeId } from "@/adapters/types";
import { DisTubeError } from "@/errors/DisTubeError";

export type AdapterCapabilityName = "identity" | "lifecycle" | "voiceAdapterCreator" | "voiceGateway";

export interface IdentityAdapterPort {
  resolveGuildId(value: unknown): SnowflakeId | null;
  normalize<Type extends keyof NormalizableTypes>(type: Type, value: unknown): NormalizableTypes[Type] | null;
}

export interface LifecycleAdapterPort {
  ready(): Promise<void>;
  validateIntents(): Promise<void>;
  destroy(): Promise<void>;
}

export interface VoiceGatewayAdapterPort {
  getVoiceAdapterCreator?(guildId: SnowflakeId): Promise<unknown>;
  sendVoiceStateUpdate?(
    guildId: SnowflakeId,
    channelId: SnowflakeId | null,
    selfMute: boolean,
    selfDeaf: boolean,
  ): Promise<void>;
}

export interface CompiledAdapterPorts {
  readonly identity: IdentityAdapterPort;
  readonly lifecycle: LifecycleAdapterPort;
  readonly voiceGateway: VoiceGatewayAdapterPort;
  readonly capabilities: ReadonlySet<AdapterCapabilityName>;
  require(capabilities: readonly AdapterCapabilityName[]): void;
}

/** Compile one public ClientAdapter into focused immutable internal ports. */
export function compileAdapterPorts(adapter: ClientAdapter): CompiledAdapterPorts {
  const capabilities = new Set<AdapterCapabilityName>(["identity", "lifecycle"]);
  if (adapter.getVoiceAdapterCreator) capabilities.add("voiceAdapterCreator");
  if (adapter.sendVoiceStateUpdate) capabilities.add("voiceGateway");
  const identity: IdentityAdapterPort = Object.freeze({
    resolveGuildId: (value: unknown) => adapter.resolveGuildId(value),
    normalize: <Type extends keyof NormalizableTypes>(type: Type, value: unknown) => adapter.normalize(type, value),
  });
  const lifecycle: LifecycleAdapterPort = Object.freeze({
    ready: async () => void (await adapter.ready?.()),
    validateIntents: async () => void (await adapter.validateIntents?.()),
    destroy: async () => void (await adapter.destroy?.()),
  });
  const voiceGateway: VoiceGatewayAdapterPort = Object.freeze({
    getVoiceAdapterCreator: adapter.getVoiceAdapterCreator
      ? async (guildId: SnowflakeId) => adapter.getVoiceAdapterCreator?.(guildId)
      : undefined,
    sendVoiceStateUpdate: adapter.sendVoiceStateUpdate
      ? async (guildId: SnowflakeId, channelId: SnowflakeId | null, selfMute: boolean, selfDeaf: boolean) =>
          void (await adapter.sendVoiceStateUpdate?.(guildId, channelId, selfMute, selfDeaf))
      : undefined,
  });
  return Object.freeze({
    identity,
    lifecycle,
    voiceGateway,
    capabilities: Object.freeze(capabilities),
    require: (requirements: readonly AdapterCapabilityName[]): void => {
      for (const capability of requirements) {
        if (!capabilities.has(capability)) throw new DisTubeError("ADAPTER_INCOMPATIBLE", { context: { capability } });
      }
    },
  });
}

