import type { SnowflakeId } from "@/adapters/types";
import type { DisTubeEventMap } from "@/api/events";
import type { FilterCatalog } from "@/filters/contracts";
import type { Scheduler } from "@/runtime/Scheduler";

export type EventCorrelationCategory = "command" | "connection" | "playback" | "lifecycle" | "diagnostic";

export interface EventJournalRecord<
  Metadata,
  Filters extends FilterCatalog,
  Event extends keyof DisTubeEventMap<Metadata, Filters> = keyof DisTubeEventMap<Metadata, Filters>,
> {
  readonly sequence: number;
  readonly guildId: SnowflakeId;
  readonly event: Event;
  readonly aggregateRevision: number;
  readonly correlation: EventCorrelationCategory;
  readonly generation?: number;
  readonly args: DisTubeEventMap<Metadata, Filters>[Event];
}

export interface EventJournalAppend<
  Metadata,
  Filters extends FilterCatalog,
  Event extends keyof DisTubeEventMap<Metadata, Filters>,
> {
  readonly guildId: SnowflakeId;
  readonly event: Event;
  readonly aggregateRevision: number;
  readonly correlation: EventCorrelationCategory;
  readonly generation?: number;
  readonly args: DisTubeEventMap<Metadata, Filters>[Event];
}

export type EventJournalPublisher<Metadata, Filters extends FilterCatalog> = <
  Event extends keyof DisTubeEventMap<Metadata, Filters>,
>(
  event: Event,
  ...args: DisTubeEventMap<Metadata, Filters>[Event]
) => void;

/** Runtime-owned committed event data with detached FIFO publication per guild. */
export class EventJournal<Metadata, Filters extends FilterCatalog> {
  readonly #scheduler: Scheduler;
  readonly #publish: EventJournalPublisher<Metadata, Filters>;
  readonly #records = new Map<SnowflakeId, EventJournalRecord<Metadata, Filters>[]>();
  readonly #scheduled = new Set<SnowflakeId>();
  #sequence = 0;

  constructor(scheduler: Scheduler, publish: EventJournalPublisher<Metadata, Filters>) {
    this.#scheduler = scheduler;
    this.#publish = publish;
  }

  append<Event extends keyof DisTubeEventMap<Metadata, Filters>>(
    append: EventJournalAppend<Metadata, Filters, Event>,
  ): EventJournalRecord<Metadata, Filters, Event> {
    const record = Object.freeze({
      ...append,
      sequence: ++this.#sequence,
      args: Object.freeze([...append.args]) as unknown as DisTubeEventMap<Metadata, Filters>[Event],
    });
    const records = this.#records.get(append.guildId) ?? [];
    records.push(record as EventJournalRecord<Metadata, Filters>);
    this.#records.set(append.guildId, records);
    this.#schedule(append.guildId);
    return record;
  }

  pending(guildId: SnowflakeId): readonly EventJournalRecord<Metadata, Filters>[] {
    return Object.freeze([...(this.#records.get(guildId) ?? [])]);
  }

  #schedule(guildId: SnowflakeId): void {
    if (this.#scheduled.has(guildId)) return;
    this.#scheduled.add(guildId);
    this.#scheduler.schedule("publication", () => this.#publishOne(guildId));
  }

  #publishOne(guildId: SnowflakeId): void {
    const records = this.#records.get(guildId);
    const record = records?.shift();
    if (records && records.length > 0) this.#scheduler.schedule("publication", () => this.#publishOne(guildId));
    else {
      this.#scheduled.delete(guildId);
      this.#records.delete(guildId);
    }
    if (record) this.#publish(record.event, ...record.args);
  }
}

