import { DisTubeError } from "@/errors/DisTubeError";
import type { FilterCatalog, FilterDefinition, FilterState } from "@/filters/contracts";

export type FilterMutation<Catalog extends FilterCatalog> =
  | { readonly kind: "add"; readonly filters: Readonly<Record<string, unknown>> }
  | { readonly kind: "remove"; readonly names: readonly (keyof Catalog & string)[] }
  | { readonly kind: "set"; readonly filters: Readonly<Record<string, unknown>> }
  | { readonly kind: "clear" };

export interface FilterRevisionState<Catalog extends FilterCatalog> {
  readonly revision: number;
  readonly filters: FilterState<Catalog>;
}

export interface FilterEnginePort<Catalog extends FilterCatalog> {
  current(): FilterRevisionState<Catalog>;
  applyBackend(candidate: FilterState<Catalog>, signal: AbortSignal): Promise<void>;
  commit(candidate: FilterState<Catalog>, expectedRevision: number): Promise<void>;
}

function equal(left: unknown, right: unknown): boolean {
  if (Object.is(left, right)) return true;
  if (Array.isArray(left) && Array.isArray(right)) {
    return left.length === right.length && left.every((value, index) => equal(value, right[index]));
  }
  if (typeof left !== "object" || left === null || typeof right !== "object" || right === null) return false;
  const leftEntries = Object.entries(left);
  const rightRecord = right as Record<string, unknown>;
  return (
    leftEntries.length === Object.keys(rightRecord).length &&
    leftEntries.every(([key, value]) => equal(value, rightRecord[key]))
  );
}

/** Serializes filter mutation policy, validates candidates, awaits backend acknowledgement, and commits by revision. */
export class FilterEngine<Catalog extends FilterCatalog> {
  readonly #catalog: Catalog;
  readonly #port: FilterEnginePort<Catalog>;
  #tail: Promise<void> = Promise.resolve();

  constructor(catalog: Catalog, port: FilterEnginePort<Catalog>) {
    this.#catalog = catalog;
    this.#port = port;
  }

  execute(mutation: FilterMutation<Catalog>, callerSignal?: AbortSignal): Promise<void> {
    const previous = this.#tail;
    let release: () => void = () => {};
    this.#tail = new Promise<void>(resolve => {
      release = resolve;
    });
    return previous.then(() => this.#execute(mutation, callerSignal)).finally(release);
  }

  async #execute(mutation: FilterMutation<Catalog>, callerSignal?: AbortSignal): Promise<void> {
    callerSignal?.throwIfAborted();
    const controller = new AbortController();
    const abort = (): void => controller.abort(callerSignal?.reason);
    if (callerSignal) callerSignal.addEventListener("abort", abort, { once: true });
    try {
      const base = this.#port.current();
      const candidate = await this.#candidate(base.filters, mutation, controller.signal);
      controller.signal.throwIfAborted();
      if (equal(base.filters, candidate)) return;
      await this.#port.applyBackend(candidate, controller.signal);
      controller.signal.throwIfAborted();
      const current = this.#port.current();
      if (current.revision !== base.revision) {
        if (!equal(current.filters, base.filters)) {
          throw new DisTubeError("FILTER_STALE", {
            context: { expectedRevision: base.revision, actualRevision: current.revision },
          });
        }
        await this.#port.commit(candidate, current.revision);
        return;
      }
      await this.#port.commit(candidate, base.revision);
    } finally {
      callerSignal?.removeEventListener("abort", abort);
    }
  }

  async #candidate(
    current: FilterState<Catalog>,
    mutation: FilterMutation<Catalog>,
    signal: AbortSignal,
  ): Promise<FilterState<Catalog>> {
    if (mutation.kind === "clear") return Object.freeze({}) as FilterState<Catalog>;
    const next: Record<string, unknown> = mutation.kind === "set" ? {} : { ...current };
    if (mutation.kind === "remove") {
      for (const name of mutation.names) {
        if (!Object.hasOwn(this.#catalog, name)) throw new DisTubeError("FILTER_UNKNOWN", { context: { name } });
        if (Object.hasOwn(next, name)) delete next[name];
      }
    } else {
      for (const [name, value] of Object.entries(mutation.filters)) {
        next[name] = await this.#validate(name, value, signal);
      }
    }
    return Object.freeze({ ...next }) as FilterState<Catalog>;
  }

  async #validate(name: string, value: unknown, signal: AbortSignal): Promise<object> {
    const definition = this.#catalog[name] as FilterDefinition<object> | undefined;
    if (!definition) throw new DisTubeError("FILTER_UNKNOWN", { context: { name } });
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
      throw new DisTubeError("FILTER_INVALID", { context: { name, reason: "parameters" } });
    }
    const knownParameters = new Set(Object.keys(definition.parameters ?? {}));
    for (const parameter of Object.keys(value)) {
      if (!knownParameters.has(parameter)) {
        throw new DisTubeError("FILTER_INVALID", { context: { name, parameter } });
      }
    }
    const resolved: Record<string, unknown> = { ...(definition.defaults ?? {}), ...value };
    for (const [parameter, metadata] of Object.entries(definition.parameters ?? {})) {
      signal.throwIfAborted();
      const parameterValue = resolved[parameter];
      if (typeof parameterValue === "number") {
        if (metadata.min !== undefined && parameterValue < metadata.min) {
          throw new DisTubeError("FILTER_INVALID", { context: { name, parameter, min: metadata.min } });
        }
        if (metadata.max !== undefined && parameterValue > metadata.max) {
          throw new DisTubeError("FILTER_INVALID", { context: { name, parameter, max: metadata.max } });
        }
      }
      if (metadata.validate && (await metadata.validate(parameterValue, resolved)) === false) {
        throw new DisTubeError("FILTER_INVALID", { context: { name, parameter } });
      }
    }
    signal.throwIfAborted();
    if (definition.validate && (await definition.validate(resolved)) === false) {
      throw new DisTubeError("FILTER_INVALID", { context: { name } });
    }
    return Object.freeze(resolved);
  }
}

