import { DisTubeError } from "@/errors/DisTubeError";
import { classifyIntegrationCall, type IntegrationOutcome } from "@/errors/IntegrationOutcome";
import { Playlist } from "@/media/Playlist";
import { Song } from "@/media/Song";
import type { SourceEntry } from "@/plugins/PluginGraph";
import type { StreamLease } from "@/resources/StreamLease";
import type { DisTubePolicies } from "@/types/options";
import type { CustomPlayable, MediaInput } from "@/types/playback";

export interface MediaProvenance {
  readonly mediaOrigin: string;
  readonly discoverySource?: SourceEntry;
  readonly visitedSources: readonly SourceEntry[];
  readonly fallbackSurrogates: readonly Song<unknown>[];
  readonly resourceOwner?: SourceEntry;
}

function isCustomPlayable<Metadata>(value: MediaInput<Metadata>): value is CustomPlayable<Metadata> {
  return typeof value === "object" && value !== null && "toPlayable" in value && typeof value.toPlayable === "function";
}

export class MediaResolver<Metadata = unknown> {
  readonly #sources: readonly SourceEntry[];
  readonly #policies: DisTubePolicies<Metadata>;
  readonly #provenance = new WeakMap<Song<unknown>, MediaProvenance>();

  constructor(sources: readonly SourceEntry[], policies: DisTubePolicies<Metadata> = {}) {
    this.#sources = sources;
    this.#policies = policies;
  }

  async resolve(
    input: MediaInput<Metadata>,
    metadata: Metadata | undefined,
    signal: AbortSignal,
  ): Promise<Song<Metadata> | Playlist<Metadata>> {
    try {
      await this.#policies.validateInput?.(input, { metadata, signal });
    } catch (cause: unknown) {
      throw new DisTubeError("POLICY_REJECTED", { cause, context: { stage: "input" } });
    }
    signal.throwIfAborted();
    let media: Song<unknown> | Playlist<unknown> | undefined;
    let owner: SourceEntry | undefined;
    const visited: SourceEntry[] = [];
    if (input instanceof Song || input instanceof Playlist) media = input;
    else if (typeof input === "string") {
      const resolved = await this.#route(
        this.#sources,
        signal,
        entry => entry.source.resolve?.(input, { metadata, signal }),
        visited,
      );
      media = resolved?.value;
      owner = resolved?.source;
      if (!media) {
        const searched = await this.#route(
          this.#sources,
          signal,
          entry => entry.source.searchSong?.(input, { metadata, signal }),
          visited,
        );
        media = searched?.value;
        owner = searched?.source;
      }
    } else if (isCustomPlayable(input)) {
      const outcome = await classifyIntegrationCall(() => input.toPlayable({ signal }), { signal });
      media = this.#handledOrThrow(outcome, "custom playable");
    }
    if (!media) throw new DisTubeError("MEDIA_RESOLUTION_FAILED", { context: { input } });
    const normalized = this.#withMetadata(media, metadata);
    this.#rememberProvenance(normalized, owner, visited, media);
    try {
      await this.#policies.validateMedia?.(normalized, { metadata, signal });
    } catch (cause: unknown) {
      throw new DisTubeError("POLICY_REJECTED", { cause, context: { stage: "media" } });
    }
    signal.throwIfAborted();
    return normalized;
  }

  async searchFallback(
    query: string,
    signal: AbortSignal,
    excluded: ReadonlySet<SourceEntry>,
    original?: Song<unknown>,
  ): Promise<{ readonly song: Song<unknown>; readonly source: SourceEntry } | undefined> {
    const existing = original ? this.#provenanceOf(original) : undefined;
    const visited = new Set<SourceEntry>([...excluded, ...(existing?.visitedSources ?? [])]);
    for (const entry of this.#sources) {
      if (visited.has(entry) || !entry.source.searchSong) continue;
      visited.add(entry);
      const outcome = await classifyIntegrationCall(() => entry.source.searchSong?.(query, { signal }), {
        signal,
        isPass: value => value === undefined,
      });
      if (outcome.kind === "pass" || outcome.kind === "unsupported") continue;
      if (outcome.kind === "aborted") throw outcome.reason;
      if (outcome.kind === "failed") {
        throw new DisTubeError("MEDIA_RESOLUTION_FAILED", { cause: outcome.error });
      }
      if (outcome.kind !== "handled") continue;
      const song = outcome.value;
      if (!song) continue;
      const provenance = this.#createProvenance(song, entry, [...visited]);
      this.#provenance.set(song, provenance);
      if (original) {
        this.#provenance.set(
          original,
          Object.freeze({
            ...(existing ?? this.#createProvenance(original)),
            visitedSources: Object.freeze([...visited]),
            fallbackSurrogates: Object.freeze([...(existing?.fallbackSurrogates ?? []), song]),
          }),
        );
      }
      return { song, source: entry };
    }
    if (original) {
      this.#provenance.set(
        original,
        Object.freeze({
          ...(existing ?? this.#createProvenance(original)),
          visitedSources: Object.freeze([...visited]),
        }),
      );
    }
    return undefined;
  }

  async getRelated(
    song: Song<Metadata>,
    signal: AbortSignal,
    onError: (error: Error) => void,
  ): Promise<{ readonly song?: Song<Metadata>; readonly hadError: boolean }> {
    const provenance = this.#provenanceOf(song);
    const owner = provenance?.discoverySource;
    const visited = new Set(provenance?.visitedSources ?? []);
    const ordered = owner ? [owner, ...this.#sources.filter(entry => entry !== owner)] : [...this.#sources];
    let hadError = false;
    for (const entry of ordered) {
      if (visited.has(entry) && entry !== owner) continue;
      visited.add(entry);
      if (!entry.source.getRelatedSong) continue;
      const outcome = await classifyIntegrationCall(
        () => entry.source.getRelatedSong?.(song as Song<unknown>, { signal }),
        {
          signal,
          isPass: value => value === undefined,
        },
      );
      if (outcome.kind === "aborted") throw outcome.reason;
      if (outcome.kind === "failed") {
        hadError = true;
        onError(outcome.error);
        continue;
      }
      if (outcome.kind !== "handled" || !outcome.value) continue;
      const normalized = this.#withMetadata(outcome.value, song.metadata) as Song<Metadata>;
      this.#provenance.set(normalized, this.#createProvenance(normalized, entry, [...visited]));
      return { song: normalized, hadError };
    }
    return { hadError };
  }

  ownerOf(song: Song<unknown>): SourceEntry | undefined {
    return this.#provenanceOf(song)?.discoverySource;
  }

  provenanceOf(song: Song<unknown>): MediaProvenance {
    return this.#provenanceOf(song) ?? this.#createProvenance(song);
  }

  associatePlayback(original: Song<unknown>, surrogate: Song<unknown>): void {
    const originalProvenance = this.#provenanceOf(original) ?? this.#createProvenance(original);
    const surrogateProvenance = this.#provenanceOf(surrogate) ?? this.#createProvenance(surrogate);
    this.#provenance.set(
      original,
      Object.freeze({
        ...originalProvenance,
        visitedSources: Object.freeze([
          ...new Set([...originalProvenance.visitedSources, ...surrogateProvenance.visitedSources]),
        ]),
        fallbackSurrogates: Object.freeze(
          originalProvenance.fallbackSurrogates.includes(surrogate)
            ? originalProvenance.fallbackSurrogates
            : [...originalProvenance.fallbackSurrogates, surrogate],
        ),
        resourceOwner: surrogateProvenance.resourceOwner ?? surrogateProvenance.discoverySource,
      }),
    );
  }

  async getFallbackQuery(song: Song<unknown>, signal: AbortSignal): Promise<string | undefined> {
    const owner = this.ownerOf(song);
    if (!owner?.source.getFallbackQuery) return undefined;
    const outcome = await classifyIntegrationCall(() => owner.source.getFallbackQuery?.(song, { signal }), {
      signal,
      isPass: value => value === undefined,
    });
    if (outcome.kind === "aborted") throw outcome.reason;
    if (outcome.kind === "failed") throw new DisTubeError("MEDIA_RESOLUTION_FAILED", { cause: outcome.error });
    return outcome.kind === "handled" ? outcome.value : undefined;
  }

  async getStream(song: Song<unknown>, signal: AbortSignal): Promise<StreamLease<unknown> | undefined> {
    const provenance = this.#provenanceOf(song);
    const owner = provenance?.resourceOwner ?? provenance?.discoverySource;
    if (!owner?.source.getStream) return undefined;
    const outcome = await classifyIntegrationCall(() => owner.source.getStream?.(song, { signal }), {
      signal,
      isPass: value => value === undefined,
    });
    if (outcome.kind === "aborted") throw outcome.reason;
    if (outcome.kind === "failed") throw new DisTubeError("MEDIA_RESOLUTION_FAILED", { cause: outcome.error });
    if (outcome.kind !== "handled" || !outcome.value) return undefined;
    this.#provenance.set(
      song,
      Object.freeze({ ...(provenance ?? this.#createProvenance(song)), resourceOwner: owner }),
    );
    return outcome.value;
  }

  async #route<Value extends Song<unknown> | Playlist<unknown>>(
    entries: readonly SourceEntry[],
    signal: AbortSignal,
    call: (entry: SourceEntry) => Value | PromiseLike<Value | undefined> | undefined,
    visited: SourceEntry[],
  ): Promise<{ readonly value: Value; readonly source: SourceEntry } | undefined> {
    for (const entry of entries) {
      visited.push(entry);
      const outcome = await classifyIntegrationCall(() => call(entry), {
        signal,
        isPass: value => value === undefined,
      });
      if (outcome.kind === "pass" || outcome.kind === "unsupported") continue;
      if (outcome.kind === "aborted") throw outcome.reason;
      if (outcome.kind === "failed") throw new DisTubeError("MEDIA_RESOLUTION_FAILED", { cause: outcome.error });
      if (outcome.kind === "handled" && outcome.value) return { value: outcome.value, source: entry };
    }
    return undefined;
  }

  #handledOrThrow<Value>(outcome: IntegrationOutcome<Value>, operation: string): Value | undefined {
    if (outcome.kind === "aborted") throw outcome.reason;
    if (outcome.kind === "failed") throw new DisTubeError("MEDIA_RESOLUTION_FAILED", { cause: outcome.error });
    if (outcome.kind === "handled") return outcome.value;
    if (outcome.kind === "resource") return outcome.resource.value;
    if (outcome.kind === "unsupported") {
      throw new DisTubeError("MEDIA_RESOLUTION_FAILED", { context: { input: operation } });
    }
    return undefined;
  }

  #provenanceOf(song: Song<unknown>): MediaProvenance | undefined {
    return this.#provenance.get(song);
  }

  #createProvenance(
    song: Song<unknown>,
    source?: SourceEntry,
    visitedSources: readonly SourceEntry[] = source ? [source] : [],
  ): MediaProvenance {
    return Object.freeze({
      mediaOrigin: song.source,
      discoverySource: source,
      visitedSources: Object.freeze([...new Set(visitedSources)]),
      fallbackSurrogates: Object.freeze([]),
      resourceOwner: source,
    });
  }

  #rememberProvenance(
    normalized: Song<unknown> | Playlist<unknown>,
    owner: SourceEntry | undefined,
    visited: readonly SourceEntry[],
    original: Song<unknown> | Playlist<unknown>,
  ): void {
    const normalizedSongs = normalized instanceof Playlist ? normalized.songs : [normalized];
    const originalSongs = original instanceof Playlist ? original.songs : [original];
    for (let index = 0; index < normalizedSongs.length; index += 1) {
      const normalizedSong = normalizedSongs[index];
      if (!normalizedSong) continue;
      const originalSong = originalSongs[index];
      const existing = originalSong ? this.#provenanceOf(originalSong) : undefined;
      this.#provenance.set(
        normalizedSong,
        Object.freeze({
          ...(existing ?? this.#createProvenance(normalizedSong, owner, visited)),
          visitedSources: Object.freeze([...new Set([...visited, ...(existing?.visitedSources ?? [])])]),
          discoverySource: existing?.discoverySource ?? owner,
          resourceOwner: existing?.resourceOwner ?? owner,
        }),
      );
    }
  }

  #withMetadata(
    media: Song<unknown> | Playlist<unknown>,
    metadata: Metadata | undefined,
  ): Song<Metadata> | Playlist<Metadata> {
    if (metadata === undefined) return media as Song<Metadata> | Playlist<Metadata>;
    if (media instanceof Song) return media.withMetadata(metadata);
    return media.withMetadata(metadata);
  }
}

