import type { MonotonicClock } from "@/runtime/Scheduler";

export type PlaybackClockState = "idle" | "playing" | "paused" | "finished" | "destroyed";

/** Monotonic playback position derived from explicit lifecycle anchors. */
export class PlaybackClock {
  readonly #clock: MonotonicClock;
  #state: PlaybackClockState = "idle";
  #positionMs = 0;
  #anchorMs = 0;

  constructor(clock: MonotonicClock) {
    this.#clock = clock;
  }

  get state(): PlaybackClockState {
    return this.#state;
  }

  position(): number {
    if (this.#state !== "playing") return this.#positionMs / 1000;
    return (this.#positionMs + Math.max(0, this.#clock.now() - this.#anchorMs)) / 1000;
  }

  start(positionSeconds = 0): void {
    this.#assertUsable();
    this.#positionMs = this.#secondsToMs(positionSeconds);
    this.#anchorMs = this.#clock.now();
    this.#state = "playing";
  }

  replace(positionSeconds = 0): void {
    this.start(positionSeconds);
  }

  seek(positionSeconds: number): void {
    this.#assertUsable();
    this.#positionMs = this.#secondsToMs(positionSeconds);
    if (this.#state === "playing") this.#anchorMs = this.#clock.now();
  }

  pause(): void {
    this.#assertUsable();
    if (this.#state !== "playing") return;
    this.#positionMs += Math.max(0, this.#clock.now() - this.#anchorMs);
    this.#state = "paused";
  }

  resume(): void {
    this.#assertUsable();
    if (this.#state !== "paused") return;
    this.#anchorMs = this.#clock.now();
    this.#state = "playing";
  }

  finish(): void {
    if (this.#state === "destroyed") return;
    if (this.#state === "playing") this.#positionMs += Math.max(0, this.#clock.now() - this.#anchorMs);
    this.#state = "finished";
  }

  destroy(): void {
    if (this.#state === "destroyed") return;
    this.finish();
    this.#state = "destroyed";
  }

  #secondsToMs(seconds: number): number {
    if (!Number.isFinite(seconds) || seconds < 0) throw new RangeError("positionSeconds must be finite and >= 0");
    return seconds * 1000;
  }

  #assertUsable(): void {
    if (this.#state === "destroyed") throw new Error("PlaybackClock is destroyed");
  }
}

