import { DisTubeError, normalizeError } from "@/errors/DisTubeError";
import type { FilterCatalog } from "@/filters/contracts";
import type { MediaResolver } from "@/media/MediaResolver";
import type { Song } from "@/media/Song";
import type { PlaybackClock } from "@/playback/PlaybackClock";
import type { PreparedPlayback, VoiceLifecycleNotification, VoiceRuntimeCapability } from "@/plugin";
import type { SourceEntry } from "@/plugins/PluginGraph";
import { ResourceScope } from "@/resources/ResourceScope";
import type { CommandOperation, SessionCoordinator } from "@/session/SessionCoordinator";

export interface PreparedCandidate<Metadata, Prepared extends PreparedPlayback = PreparedPlayback> {
  readonly song: Song<Metadata>;
  readonly playbackSong: Song<unknown>;
  readonly prepared: Prepared;
  readonly scope: ResourceScope;
}

export interface PlaybackSubscription<Metadata> {
  readonly generation: number;
  readonly song: Song<Metadata>;
  readonly playbackSong: Song<unknown>;
  readonly signal: AbortSignal;
}

export interface ActivePlayback<Metadata, Prepared extends PreparedPlayback = PreparedPlayback>
  extends PlaybackSubscription<Metadata> {
  readonly prepared: Prepared;
  readonly scope: ResourceScope;
}

interface OwnedActivePlayback<Metadata, Prepared extends PreparedPlayback = PreparedPlayback>
  extends ActivePlayback<Metadata, Prepared> {
  readonly controller: AbortController;
}

export type PlaybackActivationOutcome<Metadata, Prepared extends PreparedPlayback = PreparedPlayback> =
  | {
      readonly kind: "activated";
      readonly active: ActivePlayback<Metadata, Prepared>;
      readonly replaced?: Song<Metadata>;
    }
  | { readonly kind: "stale" };

export type PlaybackReplacementPolicy = "backend-atomic-replace";

export type PlaybackExhaustionReason = "finished" | "no-related" | "error";

export interface PlaybackFailureProgressionPort<Metadata> {
  isQueueActive(): boolean;
  discardFailed(song: Song<Metadata>): Promise<Song<Metadata> | undefined>;
  reportFailure(error: Error, song: Song<Metadata>): void;
  commitActivation(song: Song<Metadata>, autoplay: boolean): Promise<void>;
  exhaust(reason: PlaybackExhaustionReason): Promise<void>;
}

export interface PlaybackFinishProgressionPort<Metadata> extends PlaybackFailureProgressionPort<Metadata> {
  finishCurrent(song: Song<Metadata>): Promise<{ readonly next?: Song<Metadata>; readonly findRelated: boolean }>;
}

export interface PlaybackEngineOptions<
  Metadata,
  Filters extends FilterCatalog,
  Connection,
  Prepared extends PreparedPlayback,
> {
  readonly voice: VoiceRuntimeCapability<Filters, Connection, Prepared>;
  readonly resolver: MediaResolver<Metadata>;
  readonly operations: Pick<SessionCoordinator, "begin" | "invalidate">;
  readonly clock: PlaybackClock;
  readonly replacementPolicy?: PlaybackReplacementPolicy;
  readonly onNotification: (
    subscription: PlaybackSubscription<Metadata>,
    notification: Extract<VoiceLifecycleNotification, { type: "finish" | "error" }>,
  ) => void;
}

/** Owns two-phase playback preparation, atomic backend replacement, generations, and candidate resources. */
export class PlaybackEngine<Metadata, Filters extends FilterCatalog, Connection, Prepared extends PreparedPlayback> {
  readonly replacementPolicy: PlaybackReplacementPolicy;
  readonly #voice: VoiceRuntimeCapability<Filters, Connection, Prepared>;
  readonly #resolver: MediaResolver<Metadata>;
  readonly #operations: Pick<SessionCoordinator, "begin" | "invalidate">;
  readonly #clock: PlaybackClock;
  readonly #onNotification: PlaybackEngineOptions<Metadata, Filters, Connection, Prepared>["onNotification"];
  #active?: OwnedActivePlayback<Metadata, Prepared>;
  #generation = 0;

  constructor(options: PlaybackEngineOptions<Metadata, Filters, Connection, Prepared>) {
    this.#voice = options.voice;
    this.#resolver = options.resolver;
    this.#operations = options.operations;
    this.#clock = options.clock;
    this.#onNotification = options.onNotification;
    this.replacementPolicy = options.replacementPolicy ?? "backend-atomic-replace";
  }

  get activeSong(): Song<Metadata> | undefined {
    return this.#active?.song;
  }

  isCurrent(subscription: PlaybackSubscription<Metadata>): boolean {
    return this.#active?.generation === subscription.generation && !subscription.signal.aborted;
  }

  async activate(
    song: Song<Metadata>,
    connection: Connection,
    callerSignal?: AbortSignal,
  ): Promise<PlaybackActivationOutcome<Metadata, Prepared>> {
    const operation = this.#operations.begin("playback", callerSignal);
    let candidate: PreparedCandidate<Metadata, Prepared> | undefined;
    const subscriptionController = new AbortController();
    try {
      candidate = await this.#prepare(song, operation);
      if (!candidate) throw new DisTubeError("PLAYBACK_FAILED", { context: { song } });
      if (!operation.isCurrent()) {
        subscriptionController.abort(operation.signal.reason);
        await candidate.scope.dispose();
        return { kind: "stale" };
      }
      const generation = ++this.#generation;
      const pending: Array<Extract<VoiceLifecycleNotification, { type: "finish" | "error" }>> = [];
      let accepting = false;
      const active: OwnedActivePlayback<Metadata, Prepared> = Object.freeze({
        generation,
        song,
        playbackSong: candidate.playbackSong,
        prepared: candidate.prepared,
        scope: candidate.scope,
        controller: subscriptionController,
        signal: subscriptionController.signal,
      });
      await this.#voice.play({
        connection,
        song: song as Song<unknown>,
        prepared: candidate.prepared,
        signal: operation.signal,
        notify: notification => {
          if (accepting) this.#acceptNotification(active, notification);
          else pending.push(notification);
        },
      });
      if (!operation.isCurrent()) {
        subscriptionController.abort(operation.signal.reason);
        await candidate.scope.dispose();
        return { kind: "stale" };
      }
      const replaced = this.#active;
      this.#active = active;
      this.#clock.replace();
      accepting = true;
      for (const notification of pending) this.#acceptNotification(active, notification);
      if (replaced) {
        if (!replaced.controller.signal.aborted) replaced.controller.abort();
        await replaced.scope.dispose();
      }
      return { kind: "activated", active, replaced: replaced?.song };
    } catch (cause: unknown) {
      if (!subscriptionController.signal.aborted) subscriptionController.abort(cause);
      if (candidate) await candidate.scope.dispose();
      throw cause instanceof DisTubeError ? cause : new DisTubeError("PLAYBACK_FAILED", { cause, context: { song } });
    } finally {
      operation.complete();
    }
  }

  async finish(subscription: PlaybackSubscription<Metadata>): Promise<boolean> {
    const active = await this.#finish(subscription, true);
    return active !== undefined;
  }

  async progressNaturalFinish(
    subscription: PlaybackSubscription<Metadata>,
    connection: Connection,
    port: PlaybackFinishProgressionPort<Metadata>,
  ): Promise<void> {
    const active = await this.#finish(subscription, false);
    if (!active) return;
    try {
      const finished = await port.finishCurrent(subscription.song);
      let next = finished.next;
      let autoplay = false;
      if (!next && finished.findRelated) {
        const related = await this.#resolver.getRelated(subscription.song, subscription.signal, error =>
          port.reportFailure(error, subscription.song),
        );
        next = related.song;
        autoplay = next !== undefined;
        if (!next) {
          await port.exhaust(related.hadError ? "error" : "no-related");
          return;
        }
      } else if (!next) {
        await port.exhaust("finished");
        return;
      }
      try {
        const outcome = await this.activate(next, connection);
        if (outcome.kind !== "activated") return;
        await port.commitActivation(next, autoplay);
      } catch (error: unknown) {
        await this.progressFailure(next, normalizeError(error), connection, port);
      }
    } finally {
      if (!active.controller.signal.aborted) active.controller.abort();
    }
  }

  async progressFailure(
    song: Song<Metadata>,
    error: Error,
    connection: Connection,
    port: PlaybackFailureProgressionPort<Metadata>,
  ): Promise<void> {
    await this.disposeActive();
    let failedSong = song;
    let failure = error;
    while (port.isQueueActive()) {
      const next = await port.discardFailed(failedSong);
      port.reportFailure(failure, failedSong);
      if (!next) {
        await port.exhaust("error");
        return;
      }
      try {
        const outcome = await this.activate(next, connection);
        if (outcome.kind !== "activated") return;
      } catch (nextError: unknown) {
        failedSong = next;
        failure = normalizeError(nextError);
        continue;
      }
      await port.commitActivation(next, false);
      return;
    }
  }

  async stop(connection: Connection): Promise<void> {
    const errors: Error[] = [];
    try {
      await this.stopBackend(connection);
    } catch (error: unknown) {
      errors.push(normalizeError(error));
    }
    const result = await this.disposeActive();
    errors.push(...result);
    if (errors.length > 0) throw new AggregateError(errors, "Playback cleanup failed");
  }

  async stopBackend(connection: Connection): Promise<void> {
    if (!this.#active) return;
    this.#operations.invalidate("playback");
    if (!this.#active.controller.signal.aborted) this.#active.controller.abort();
    const controller = new AbortController();
    await this.#voice.stop(connection, controller.signal);
  }

  async disposeActive(): Promise<readonly Error[]> {
    if (!this.#active) return [];
    const active = this.#active;
    this.#active = undefined;
    if (!active.controller.signal.aborted) active.controller.abort();
    this.#clock.finish();
    const result = await active.scope.dispose();
    return result.errors;
  }

  async #prepare(
    song: Song<Metadata>,
    operation: CommandOperation,
  ): Promise<PreparedCandidate<Metadata, Prepared> | undefined> {
    const prepare = async (target: Song<unknown>): Promise<PreparedCandidate<Metadata, Prepared> | undefined> => {
      const scope = new ResourceScope(`playback-candidate:${song.id ?? song.name ?? "unknown"}`);
      try {
        const prepared = await this.#voice.prepare({
          song: target,
          signal: operation.signal,
          getStream: async requested => {
            const lease = await this.#resolver.getStream(requested ?? target, operation.signal);
            if (lease && !this.#voice.isStreamSupported(lease.value)) {
              await lease.dispose();
              return undefined;
            }
            return lease;
          },
        });
        if (!prepared) {
          await scope.dispose();
          return undefined;
        }
        if (prepared.lease) scope.register("lease", () => prepared.lease?.dispose());
        return Object.freeze({ song, playbackSong: target, prepared, scope });
      } catch (error: unknown) {
        await scope.dispose();
        throw error;
      }
    };
    const direct = await prepare(song as Song<unknown>);
    if (direct) return direct;
    const query = await this.#resolver.getFallbackQuery(song as Song<unknown>, operation.signal);
    if (!query) return undefined;
    const owner = this.#resolver.ownerOf(song as Song<unknown>);
    const excluded = new Set<SourceEntry>(owner ? [owner] : []);
    const fallback = await this.#resolver.searchFallback(query, operation.signal, excluded, song);
    if (!fallback) return undefined;
    const prepared = await prepare(fallback.song);
    if (prepared) this.#resolver.associatePlayback(song, fallback.song);
    return prepared;
  }

  async #finish(
    subscription: PlaybackSubscription<Metadata>,
    abort: boolean,
  ): Promise<OwnedActivePlayback<Metadata, Prepared> | undefined> {
    if (!this.isCurrent(subscription)) return undefined;
    const active = this.#active;
    if (!active) return undefined;
    this.#active = undefined;
    if (abort && !active.controller.signal.aborted) active.controller.abort();
    this.#clock.finish();
    const result = await active.scope.dispose();
    if (result.errors.length > 0) throw new AggregateError(result.errors, "Playback resource cleanup failed");
    return active;
  }

  #acceptNotification(
    subscription: PlaybackSubscription<Metadata>,
    notification: Extract<VoiceLifecycleNotification, { type: "finish" | "error" }>,
  ): void {
    if (this.isCurrent(subscription)) this.#onNotification(subscription, notification);
  }
}

