import { type CompiledAdapterPorts, compileAdapterPorts } from "@/adapters/AdapterPorts";
import type { ClientAdapter } from "@/adapters/types";
import { DisTubeError, normalizeError } from "@/errors/DisTubeError";
import type { FilterCatalog } from "@/filters/contracts";
import type {
  DisTubePlugin,
  PluginClass,
  PluginContext,
  PreparedPlayback,
  SourceCapability,
  VoiceCapability,
} from "@/plugin";
import { DisTubePlugin as PluginBase } from "@/plugin";
import { ResourceScope } from "@/resources/ResourceScope";
import type { DisTubeOptions, VoicePlugin } from "@/types/options";

export interface SourceEntry {
  readonly plugin: DisTubePlugin;
  readonly source: SourceCapability;
}

type ConstructorIdentity = { readonly name: string };

export class PluginCollection {
  readonly #byClass: ReadonlyMap<ConstructorIdentity, DisTubePlugin>;
  readonly #byId: ReadonlyMap<string, DisTubePlugin>;

  constructor(byClass: ReadonlyMap<ConstructorIdentity, DisTubePlugin>, byId: ReadonlyMap<string, DisTubePlugin>) {
    this.#byClass = byClass;
    this.#byId = byId;
  }

  get<Plugin extends DisTubePlugin>(pluginClass: PluginClass<Plugin>): Plugin | undefined {
    return this.#byClass.get(pluginClass) as Plugin | undefined;
  }

  getById(id: string): DisTubePlugin | undefined {
    return this.#byId.get(id);
  }
}

/** Immutable compiled plugin identity, role, source, lookup, adapter requirement, and lifecycle graph. */
export class PluginGraph<
  Adapter extends ClientAdapter,
  Filters extends FilterCatalog,
  Connection,
  Prepared extends PreparedPlayback,
  SelectedVoice extends VoicePlugin,
> {
  readonly adapter: Adapter;
  readonly adapterPorts: CompiledAdapterPorts;
  readonly selectedVoice: SelectedVoice;
  readonly selectedVoiceCapability: VoiceCapability<Filters, Connection, Prepared>;
  readonly plugins: readonly DisTubePlugin[];
  readonly sources: readonly SourceEntry[];
  readonly collection: PluginCollection;
  readonly #context: PluginContext<Adapter>;
  readonly #initializationOrder: readonly DisTubePlugin[];
  readonly #pluginScopes: Array<{ readonly plugin: DisTubePlugin; readonly scope: ResourceScope }> = [];
  #adapterScope?: ResourceScope;
  #adapterInitialized = false;

  constructor(
    options: Pick<DisTubeOptions<Adapter, SelectedVoice, unknown>, "adapter" | "voice" | "plugins"> & {
      readonly voice: SelectedVoice & VoicePlugin<Filters, Connection, Prepared>;
    },
    context: PluginContext<Adapter>,
  ) {
    this.adapter = options.adapter;
    this.adapterPorts = compileAdapterPorts(options.adapter);
    this.selectedVoice = options.voice;
    this.selectedVoiceCapability = options.voice.voice;
    this.#context = Object.freeze({ ...context });
    const configured = [...(options.plugins ?? [])];
    const distinct = [this.selectedVoice, ...configured.filter(plugin => plugin !== this.selectedVoice)];
    const indexes = this.#validateAndIndex(distinct);
    this.selectedVoiceCapability.requiredAdapterCapabilities &&
      this.adapterPorts.require(this.selectedVoiceCapability.requiredAdapterCapabilities);
    this.#initializationOrder = Object.freeze(distinct);
    this.plugins = this.#initializationOrder;
    const sourceOrder = configured.includes(this.selectedVoice) ? configured : [...configured, this.selectedVoice];
    this.sources = Object.freeze(
      sourceOrder.flatMap(plugin => (plugin.source ? [{ plugin, source: plugin.source }] : [])),
    );
    this.collection = new PluginCollection(indexes.byClass, indexes.byId);
    Object.freeze(this);
  }

  async initialize(signal?: AbortSignal): Promise<void> {
    try {
      signal?.throwIfAborted();
      await this.adapterPorts.lifecycle.validateIntents();
      signal?.throwIfAborted();
      await this.adapterPorts.lifecycle.ready();
      this.#adapterInitialized = true;
      this.#adapterScope = new ResourceScope("adapter");
      this.#adapterScope.register("destroy", () => this.adapterPorts.lifecycle.destroy());
      signal?.throwIfAborted();
      for (const plugin of this.#initializationOrder) {
        signal?.throwIfAborted();
        await plugin.initialize?.(this.#context);
        const scope = new ResourceScope(`plugin:${plugin.id}`);
        if (plugin.destroy) scope.register("destroy", () => plugin.destroy?.());
        this.#pluginScopes.push({ plugin, scope });
        signal?.throwIfAborted();
      }
    } catch (cause: unknown) {
      const rollbackErrors = await this.#rollback();
      throw new DisTubeError("PLUGIN_INITIALIZATION", {
        cause,
        context: rollbackErrors.length > 0 ? { rollbackErrors } : undefined,
      });
    }
  }

  cleanupUnits(): readonly { readonly name: string; readonly run: () => Promise<void> }[] {
    const plugins = [...this.#pluginScopes].reverse().map(({ plugin, scope }) => ({
      name: `plugin:${plugin.id}`,
      run: async (): Promise<void> => {
        const result = await scope.dispose();
        if (result.errors.length > 0) throw new AggregateError(result.errors, `Plugin ${plugin.id} cleanup failed`);
      },
    }));
    const adapter =
      this.#adapterInitialized && this.#adapterScope
        ? [
            {
              name: "adapter",
              run: async (): Promise<void> => {
                const result = await this.#adapterScope?.dispose();
                if (result && result.errors.length > 0) {
                  throw new AggregateError(result.errors, "Adapter cleanup failed");
                }
              },
            },
          ]
        : [];
    return Object.freeze([...plugins, ...adapter]);
  }

  #validateAndIndex(plugins: readonly DisTubePlugin[]): {
    readonly byClass: ReadonlyMap<ConstructorIdentity, DisTubePlugin>;
    readonly byId: ReadonlyMap<string, DisTubePlugin>;
  } {
    const byClass = new Map<ConstructorIdentity, DisTubePlugin>();
    const byId = new Map<string, DisTubePlugin>();
    for (const plugin of plugins) {
      if (!(plugin instanceof PluginBase) || typeof plugin.id !== "string" || plugin.id.trim() === "") {
        throw new DisTubeError("PLUGIN_CONFIGURATION", { context: { plugin } });
      }
      const duplicate = byId.get(plugin.id);
      if (duplicate && duplicate !== plugin) {
        throw new DisTubeError("PLUGIN_CONFIGURATION", { context: { id: plugin.id, reason: "duplicate" } });
      }
      byId.set(plugin.id, plugin);
      if (!byClass.has(plugin.constructor)) byClass.set(plugin.constructor, plugin);
    }
    return { byClass, byId };
  }

  async #rollback(): Promise<Error[]> {
    const errors: Error[] = [];
    for (const unit of this.cleanupUnits()) {
      try {
        await unit.run();
      } catch (error: unknown) {
        errors.push(normalizeError(error));
      }
    }
    return errors;
  }
}

