import type { SnowflakeId } from "@/adapters/types";
import type { QueueSnapshot } from "@/api/snapshots";
import type { RepeatMode } from "@/enums";
import type { EmptyFilterCatalog, FilterCatalog, FilterState } from "@/filters/contracts";
import type { FilterMutation } from "@/filters/FilterEngine";
import type { Playlist } from "@/media/Playlist";
import type { Song } from "@/media/Song";
import type { MediaInput, PlayOptions, QueueEditCallback } from "@/types/playback";
import { QueueFilters } from "./QueueFilters";

interface QueueController<Metadata, Filters extends FilterCatalog> {
  getQueueSnapshot(): QueueSnapshot<Metadata, Filters>;
  getFilterState(): FilterState<Filters>;
  mutateFilters(mutation: FilterMutation<Filters>, signal?: AbortSignal): Promise<void>;
  add(input: MediaInput<Metadata>, options?: PlayOptions<Metadata>): Promise<void>;
  addRelated(song?: Song<Metadata>, signal?: AbortSignal): Promise<Song<Metadata>>;
  setPaused(paused: boolean, signal?: AbortSignal): Promise<void>;
  skip(signal?: AbortSignal): Promise<Song<Metadata>>;
  previous(signal?: AbortSignal): Promise<Song<Metadata>>;
  jumpTo(position: number, signal?: AbortSignal): Promise<Song<Metadata>>;
  seek(time: number, signal?: AbortSignal): Promise<void>;
  setVolume(volume: number, signal?: AbortSignal): Promise<void>;
  setAutoplay(autoplay: boolean, signal?: AbortSignal): Promise<void>;
  setRepeatMode(mode: RepeatMode, signal?: AbortSignal): Promise<void>;
  move(fromIndex: number, toIndex: number, signal?: AbortSignal): Promise<void>;
  remove(index: number, signal?: AbortSignal): Promise<Song<Metadata>>;
  clearUpcoming(signal?: AbortSignal): Promise<void>;
  shuffle(signal?: AbortSignal): Promise<void>;
  edit(callback: QueueEditCallback<Metadata>, signal?: AbortSignal): Promise<void>;
  stop(): Promise<void>;
}

/** Stable command/query handle backed by the latest committed GuildSession state. */
export class Queue<Metadata = unknown, Filters extends FilterCatalog = EmptyFilterCatalog> {
  readonly guildId: SnowflakeId;
  readonly filters: QueueFilters<Filters>;
  readonly #controller: QueueController<Metadata, Filters>;

  /** @internal */
  constructor(guildId: SnowflakeId, filters: Filters, controller: unknown) {
    this.guildId = guildId;
    this.#controller = controller as QueueController<Metadata, Filters>;
    this.filters = new QueueFilters(filters, controller);
  }

  get revision(): number {
    return this.snapshot().revision;
  }

  get current(): Song<Metadata> | undefined {
    return this.snapshot().current;
  }

  get upcoming(): readonly Song<Metadata>[] {
    return this.snapshot().upcoming;
  }

  get history(): readonly Song<Metadata>[] {
    return this.snapshot().history;
  }

  get repeatMode(): RepeatMode {
    return this.snapshot().repeatMode;
  }

  get autoplay(): boolean {
    return this.snapshot().autoplay;
  }

  get paused(): boolean {
    return this.snapshot().paused;
  }

  get volume(): number {
    return this.snapshot().volume;
  }

  get currentTime(): number {
    return this.snapshot().currentTime;
  }

  get voice(): QueueSnapshot<Metadata, Filters>["voice"] {
    return this.snapshot().voice;
  }

  get destroyed(): boolean {
    return this.snapshot().destroyed;
  }

  snapshot(): QueueSnapshot<Metadata, Filters> {
    return this.#controller.getQueueSnapshot();
  }

  async add(input: MediaInput<Metadata>, options?: PlayOptions<Metadata>): Promise<this> {
    await this.#controller.add(input, options);
    return this;
  }

  addRelated(song?: Song<Metadata>, signal?: AbortSignal): Promise<Song<Metadata>> {
    return this.#controller.addRelated(song, signal);
  }

  /**
   * Sets paused state; requesting the committed value is an idempotent no-op.
   * @param paused Whether playback should be paused.
   * @param signal Optional cancellation signal for an effective backend operation.
   * @returns This Queue after the state commit or no-op.
   */
  async setPaused(paused: boolean, signal?: AbortSignal): Promise<this> {
    await this.#controller.setPaused(paused, signal);
    return this;
  }

  skip(signal?: AbortSignal): Promise<Song<Metadata>> {
    return this.#controller.skip(signal);
  }

  previous(signal?: AbortSignal): Promise<Song<Metadata>> {
    return this.#controller.previous(signal);
  }

  jumpTo(position: number, signal?: AbortSignal): Promise<Song<Metadata>> {
    return this.#controller.jumpTo(position, signal);
  }

  async seek(time: number, signal?: AbortSignal): Promise<this> {
    await this.#controller.seek(time, signal);
    return this;
  }

  async setVolume(volume: number, signal?: AbortSignal): Promise<this> {
    await this.#controller.setVolume(volume, signal);
    return this;
  }

  async setAutoplay(autoplay: boolean, signal?: AbortSignal): Promise<this> {
    await this.#controller.setAutoplay(autoplay, signal);
    return this;
  }

  async setRepeatMode(mode: RepeatMode, signal?: AbortSignal): Promise<this> {
    await this.#controller.setRepeatMode(mode, signal);
    return this;
  }

  /**
   * Moves one Song within the zero-based {@link upcoming} array.
   * Unlike one-based numeric add placement and `jumpTo()`, both arguments are array indices.
   * @param fromIndex Current zero-based upcoming index.
   * @param toIndex Destination zero-based index in the final upcoming array.
   * @param signal Optional cancellation signal.
   * @returns This Queue after the atomic order commit or no-op.
   */
  async move(fromIndex: number, toIndex: number, signal?: AbortSignal): Promise<this> {
    await this.#controller.move(fromIndex, toIndex, signal);
    return this;
  }

  /**
   * Removes and returns one Song from the zero-based {@link upcoming} array.
   * @param index Zero-based upcoming index.
   * @param signal Optional cancellation signal.
   * @returns The immutable Song removed after the atomic commit.
   */
  remove(index: number, signal?: AbortSignal): Promise<Song<Metadata>> {
    return this.#controller.remove(index, signal);
  }

  /**
   * Atomically removes every upcoming Song without changing current playback or history.
   * @param signal Optional cancellation signal.
   * @returns This Queue after the commit; an already-empty list is a no-op.
   */
  async clearUpcoming(signal?: AbortSignal): Promise<this> {
    await this.#controller.clearUpcoming(signal);
    return this;
  }

  /**
   * Randomizes only the upcoming Song order; an unchanged permutation is a no-op.
   * @param signal Optional cancellation signal.
   * @returns This Queue after the atomic order commit or no-op.
   */
  async shuffle(signal?: AbortSignal): Promise<this> {
    await this.#controller.shuffle(signal);
    return this;
  }

  async edit(callback: QueueEditCallback<Metadata>, signal?: AbortSignal): Promise<this> {
    await this.#controller.edit(callback, signal);
    return this;
  }

  stop(): Promise<void> {
    return this.#controller.stop();
  }
}

export type QueueMedia<Metadata = unknown> = Song<Metadata> | Playlist<Metadata>;
export type QueueFilterState<Filters extends FilterCatalog> = FilterState<Filters>;

