import type { SnowflakeId } from "@/adapters/types";
import type { QueueSnapshot, VoiceSnapshot } from "@/api/snapshots";
import {
  QueueAddReason,
  QueueChangeReason,
  type QueueDeleteReason,
  QueuePlacement,
  QueueSkipBehavior,
  RepeatMode,
} from "@/enums";
import { DisTubeError } from "@/errors/DisTubeError";
import type { FilterCatalog, FilterState } from "@/filters/contracts";
import { Playlist } from "@/media/Playlist";
import { Song } from "@/media/Song";

interface QueueState<Metadata, Filters extends FilterCatalog> {
  readonly revision: number;
  readonly current?: Song<Metadata>;
  readonly upcoming: readonly Song<Metadata>[];
  readonly history: readonly Song<Metadata>[];
  readonly repeatMode: RepeatMode;
  readonly autoplay: boolean;
  readonly paused: boolean;
  readonly volume: number;
  readonly currentTime: number;
  readonly filters: FilterState<Filters>;
  readonly destroyed: boolean;
}

export type QueueField = Exclude<keyof QueueState<unknown, FilterCatalog>, "revision">;

export interface QueueAggregateOptions<Filters extends FilterCatalog> {
  readonly guildId: SnowflakeId;
  readonly historyLimit: number;
  readonly repeatMode: RepeatMode;
  readonly autoplay: boolean;
  readonly volume: number;
  readonly filters: FilterState<Filters>;
}

export type QueueCommand<Metadata, Filters extends FilterCatalog> =
  | {
      readonly type: "add";
      readonly media: Song<Metadata> | Playlist<Metadata>;
      readonly reason: QueueAddReason;
      readonly placement: QueuePlacement | number;
      readonly replace: boolean;
      readonly skipBehavior: QueueSkipBehavior;
    }
  | { readonly type: "skip" }
  | { readonly type: "previous" }
  | { readonly type: "jump"; readonly position: number }
  | { readonly type: "setPaused"; readonly paused: boolean }
  | { readonly type: "seek"; readonly time: number }
  | { readonly type: "setVolume"; readonly volume: number }
  | { readonly type: "setAutoplay"; readonly autoplay: boolean }
  | { readonly type: "setRepeatMode"; readonly repeatMode: RepeatMode }
  | { readonly type: "moveUpcoming"; readonly fromIndex: number; readonly toIndex: number }
  | { readonly type: "removeUpcoming"; readonly index: number }
  | { readonly type: "clearUpcoming" }
  | { readonly type: "shuffleUpcoming"; readonly upcoming: readonly Song<Metadata>[] }
  | { readonly type: "edit"; readonly upcoming: readonly Song<Metadata>[] }
  | { readonly type: "setFilters"; readonly filters: FilterState<Filters> }
  | { readonly type: "finish"; readonly song: Song<Metadata> }
  | {
      readonly type: "activateSuccessor";
      readonly song: Song<Metadata>;
      readonly autoplay: boolean;
    }
  | { readonly type: "playbackFailed"; readonly song: Song<Metadata> }
  | { readonly type: "destroy"; readonly reason: QueueDeleteReason };

export type PlaybackIntent<Metadata> =
  | { readonly kind: "activate"; readonly song: Song<Metadata> }
  | { readonly kind: "restart"; readonly song: Song<Metadata> }
  | { readonly kind: "stop" }
  | { readonly kind: "pause" }
  | { readonly kind: "resume" }
  | { readonly kind: "seek"; readonly time: number }
  | { readonly kind: "volume"; readonly volume: number }
  | { readonly kind: "filters" }
  | { readonly kind: "findRelated"; readonly song: Song<Metadata> };

export type QueueEventIntent<Metadata> =
  | { readonly kind: "init" }
  | { readonly kind: "addSong"; readonly song: Song<Metadata>; readonly reason: QueueAddReason }
  | { readonly kind: "addPlaylist"; readonly playlist: Playlist<Metadata>; readonly reason: QueueAddReason }
  | { readonly kind: "playSong"; readonly song: Song<Metadata> }
  | { readonly kind: "finishSong"; readonly song: Song<Metadata> }
  | { readonly kind: "change"; readonly reason: QueueChangeReason }
  | { readonly kind: "delete"; readonly reason: QueueDeleteReason };

export interface QueueConflictMetadata {
  readonly owns: ReadonlySet<QueueField>;
  readonly conflicts: ReadonlySet<QueueField>;
  readonly rebase: "independent" | "reject";
}

export interface QueueTransition<Metadata, Filters extends FilterCatalog, Result = unknown> {
  readonly baseRevision: number;
  readonly command: QueueCommand<Metadata, Filters>;
  readonly result: Result;
  readonly events: readonly QueueEventIntent<Metadata>[];
  readonly playback?: PlaybackIntent<Metadata>;
  readonly conflict: QueueConflictMetadata;
}

export interface QueueCommit<Metadata, Filters extends FilterCatalog, Result = unknown> {
  readonly revision: number;
  readonly result: Result;
  readonly oldSnapshot: QueueSnapshot<Metadata, Filters>;
  readonly newSnapshot: QueueSnapshot<Metadata, Filters>;
  readonly events: readonly QueueEventIntent<Metadata>[];
  readonly playback?: PlaybackIntent<Metadata>;
  readonly rebased: boolean;
}

interface Reduced<Metadata, Filters extends FilterCatalog, Result> {
  readonly next: QueueState<Metadata, Filters>;
  readonly result: Result;
  readonly events: readonly QueueEventIntent<Metadata>[];
  readonly playback?: PlaybackIntent<Metadata>;
  readonly conflict: QueueConflictMetadata;
}

const STRUCTURAL_FIELDS = new Set<QueueField>(["current", "upcoming", "history", "destroyed"]);

function fields(
  owns: readonly QueueField[],
  conflicts: readonly QueueField[] = owns,
  rebase: QueueConflictMetadata["rebase"] = "independent",
): QueueConflictMetadata {
  return Object.freeze({ owns: new Set(owns), conflicts: new Set(conflicts), rebase });
}

function freezeState<Metadata, Filters extends FilterCatalog>(
  state: QueueState<Metadata, Filters>,
): QueueState<Metadata, Filters> {
  return Object.freeze({
    ...state,
    upcoming: Object.freeze([...state.upcoming]),
    history: Object.freeze([...state.history]),
  });
}

/** Pure Queue state-transition authority with optimistic conflict-aware commits. */
export class QueueAggregate<Metadata, Filters extends FilterCatalog> {
  readonly guildId: SnowflakeId;
  readonly #historyLimit: number;
  #state: QueueState<Metadata, Filters>;
  readonly #changedByRevision = new Map<number, ReadonlySet<QueueField>>();

  constructor(options: QueueAggregateOptions<Filters>) {
    this.guildId = options.guildId;
    this.#historyLimit = options.historyLimit;
    this.#state = freezeState({
      revision: 0,
      current: undefined,
      upcoming: [],
      history: [],
      repeatMode: options.repeatMode,
      autoplay: options.autoplay,
      paused: false,
      volume: options.volume,
      currentTime: 0,
      filters: options.filters,
      destroyed: false,
    });
  }

  get revision(): number {
    return this.#state.revision;
  }

  plan<Result = unknown>(command: QueueCommand<Metadata, Filters>): QueueTransition<Metadata, Filters, Result> {
    const reduced = this.#reduce<Result>(this.#state, command);
    return Object.freeze({
      baseRevision: this.#state.revision,
      command,
      result: reduced.result,
      events: Object.freeze([...reduced.events]),
      playback: reduced.playback,
      conflict: reduced.conflict,
    });
  }

  commit<Result>(
    transition: QueueTransition<Metadata, Filters, Result>,
    voice?: VoiceSnapshot,
  ): QueueCommit<Metadata, Filters, Result> {
    this.#assertUsable();
    const changed = this.#fieldsChangedSince(transition.baseRevision);
    const stale = transition.baseRevision !== this.#state.revision;
    if (
      stale &&
      (transition.conflict.rebase === "reject" || this.#intersects(changed, transition.conflict.conflicts))
    ) {
      throw new DisTubeError("INVALID_INPUT", { context: { operation: "queueRevisionConflict" } });
    }
    const oldSnapshot = this.snapshot(voice);
    const reduced = this.#reduce<Result>(this.#state, transition.command);
    if (reduced.next === this.#state) {
      return Object.freeze({
        revision: this.#state.revision,
        result: reduced.result,
        oldSnapshot,
        newSnapshot: oldSnapshot,
        events: Object.freeze([...reduced.events]),
        playback: reduced.playback,
        rebased: stale,
      });
    }
    const revision = this.#state.revision + 1;
    this.#state = freezeState({ ...reduced.next, revision });
    this.#changedByRevision.set(revision, reduced.conflict.owns);
    return Object.freeze({
      revision,
      result: reduced.result,
      oldSnapshot,
      newSnapshot: this.snapshot(voice),
      events: Object.freeze([...reduced.events]),
      playback: reduced.playback,
      rebased: stale,
    });
  }

  execute<Result = unknown>(
    command: QueueCommand<Metadata, Filters>,
    voice?: VoiceSnapshot,
  ): QueueCommit<Metadata, Filters, Result> {
    return this.commit(this.plan<Result>(command), voice);
  }

  snapshot(voice?: VoiceSnapshot): QueueSnapshot<Metadata, Filters> {
    const state = this.#state;
    return Object.freeze({
      guildId: this.guildId,
      revision: state.revision,
      current: state.current,
      upcoming: state.upcoming,
      history: state.history,
      repeatMode: state.repeatMode,
      autoplay: state.autoplay,
      paused: state.paused,
      volume: state.volume,
      currentTime: state.currentTime,
      filters: state.filters,
      voice,
      destroyed: state.destroyed,
    });
  }

  #reduce<Result>(
    state: QueueState<Metadata, Filters>,
    command: QueueCommand<Metadata, Filters>,
  ): Reduced<Metadata, Filters, Result> {
    if (state.destroyed && command.type !== "destroy") throw new DisTubeError("QUEUE_DESTROYED");
    switch (command.type) {
      case "add":
        return this.#add(state, command) as Reduced<Metadata, Filters, Result>;
      case "skip":
        return this.#navigate(state, "skip") as Reduced<Metadata, Filters, Result>;
      case "previous":
        return this.#navigate(state, "previous") as Reduced<Metadata, Filters, Result>;
      case "jump":
        return this.#jump(state, command.position) as Reduced<Metadata, Filters, Result>;
      case "setPaused":
        return this.#change(
          state,
          { paused: command.paused },
          command.paused ? QueueChangeReason.PAUSE : QueueChangeReason.RESUME,
          { kind: command.paused ? "pause" : "resume" },
        ) as Reduced<Metadata, Filters, Result>;
      case "moveUpcoming":
        return this.#moveUpcoming(state, command.fromIndex, command.toIndex) as Reduced<Metadata, Filters, Result>;
      case "removeUpcoming":
        return this.#removeUpcoming(state, command.index) as Reduced<Metadata, Filters, Result>;
      case "clearUpcoming":
        return this.#replaceUpcoming(state, [], "clearUpcoming") as Reduced<Metadata, Filters, Result>;
      case "shuffleUpcoming":
        if (!this.#isSameSongMultiset(state.upcoming, command.upcoming)) {
          throw new DisTubeError("INVALID_INPUT", { context: { operation: "shuffle" } });
        }
        return this.#replaceUpcoming(state, command.upcoming, "shuffle") as Reduced<Metadata, Filters, Result>;
      case "seek":
        if (!Number.isFinite(command.time) || command.time < 0) {
          throw new DisTubeError("INVALID_INPUT", { context: { time: command.time } });
        }
        return this.#change(state, { currentTime: command.time }, QueueChangeReason.SEEK, {
          kind: "seek",
          time: command.time,
        }) as Reduced<Metadata, Filters, Result>;
      case "setVolume":
        if (!Number.isInteger(command.volume) || command.volume < 0 || command.volume > 1000) {
          throw new DisTubeError("INVALID_INPUT", { context: { volume: command.volume, min: 0, max: 1000 } });
        }
        return this.#change(state, { volume: command.volume }, QueueChangeReason.VOLUME, {
          kind: "volume",
          volume: command.volume,
        }) as Reduced<Metadata, Filters, Result>;
      case "setAutoplay":
        return this.#change(state, { autoplay: command.autoplay }, QueueChangeReason.AUTOPLAY) as Reduced<
          Metadata,
          Filters,
          Result
        >;
      case "setRepeatMode":
        if (!Object.values(RepeatMode).includes(command.repeatMode)) {
          throw new DisTubeError("INVALID_INPUT", { context: { mode: command.repeatMode } });
        }
        return this.#change(state, { repeatMode: command.repeatMode }, QueueChangeReason.REPEAT_MODE) as Reduced<
          Metadata,
          Filters,
          Result
        >;
      case "edit":
        return this.#replaceUpcoming(state, command.upcoming, "edit") as Reduced<Metadata, Filters, Result>;
      case "setFilters":
        return this.#change(state, { filters: command.filters }, QueueChangeReason.FILTERS, {
          kind: "filters",
        }) as Reduced<Metadata, Filters, Result>;
      case "finish":
        return this.#finish(state, command.song) as Reduced<Metadata, Filters, Result>;
      case "activateSuccessor":
        return this.#activateSuccessor(state, command.song, command.autoplay) as Reduced<Metadata, Filters, Result>;
      case "playbackFailed":
        return this.#playbackFailed(state, command.song) as Reduced<Metadata, Filters, Result>;
      case "destroy":
        return {
          next: freezeState({
            ...state,
            paused: false,
            destroyed: true,
          }),
          result: undefined as Result,
          events: [{ kind: "delete", reason: command.reason }],
          playback: { kind: "stop" },
          conflict: fields([...STRUCTURAL_FIELDS, "paused", "currentTime"], [...STRUCTURAL_FIELDS], "reject"),
        };
    }
  }

  #add(
    state: QueueState<Metadata, Filters>,
    command: Extract<QueueCommand<Metadata, Filters>, { type: "add" }>,
  ): Reduced<Metadata, Filters, Song<Metadata> | undefined> {
    const songs = command.media instanceof Playlist ? [...command.media.songs] : [command.media];
    const events: QueueEventIntent<Metadata>[] = [];
    if (state.revision === 0) events.push({ kind: "init" });
    events.push(
      command.media instanceof Playlist
        ? { kind: "addPlaylist", playlist: command.media, reason: command.reason }
        : { kind: "addSong", song: command.media, reason: command.reason },
    );
    if (!command.replace && state.current) {
      return {
        next: freezeState({ ...state, upcoming: this.#insert(state.upcoming, songs, command.placement) }),
        result: undefined,
        events,
        conflict: fields(["upcoming"], ["upcoming", "destroyed"]),
      };
    }
    const target = songs.shift();
    if (!target) throw new DisTubeError("INVALID_INPUT", { context: { input: "media" } });
    const history = [...state.history];
    if (state.current && command.skipBehavior !== QueueSkipBehavior.DISCARD)
      this.#appendHistory(history, state.current);
    events.push({ kind: "playSong", song: target });
    return {
      next: freezeState({
        ...state,
        current: target,
        upcoming: this.#insert(state.upcoming, songs, QueuePlacement.NEXT),
        history,
        paused: false,
        currentTime: 0,
        destroyed: false,
      }),
      result: target,
      events,
      playback: { kind: "activate", song: target },
      conflict: fields([...STRUCTURAL_FIELDS, "paused", "currentTime"], [...STRUCTURAL_FIELDS]),
    };
  }

  #navigate(
    state: QueueState<Metadata, Filters>,
    direction: "skip" | "previous",
  ): Reduced<Metadata, Filters, Song<Metadata>> {
    const upcoming = [...state.upcoming];
    const history = [...state.history];
    const target = direction === "skip" ? upcoming.shift() : history.pop();
    if (!target) throw new DisTubeError(direction === "skip" ? "NO_UP_NEXT" : "NO_PREVIOUS");
    if (direction === "skip" && state.current) this.#appendHistory(history, state.current);
    if (direction === "previous" && state.current) upcoming.unshift(state.current);
    return {
      next: freezeState({ ...state, current: target, upcoming, history, paused: false, currentTime: 0 }),
      result: target,
      events: [
        { kind: "change", reason: direction === "skip" ? QueueChangeReason.SKIP : QueueChangeReason.PREVIOUS },
        { kind: "playSong", song: target },
      ],
      playback: { kind: "activate", song: target },
      conflict: fields([...STRUCTURAL_FIELDS, "paused", "currentTime"], [...STRUCTURAL_FIELDS]),
    };
  }

  #jump(state: QueueState<Metadata, Filters>, position: number): Reduced<Metadata, Filters, Song<Metadata>> {
    if (!Number.isInteger(position) || position < 1) {
      throw new DisTubeError("NO_SONG_POSITION", { context: { position } });
    }
    if (position === 1 && state.current) {
      return {
        next: state,
        result: state.current,
        events: [],
        conflict: fields([], []),
      };
    }
    const index = position - 2;
    const target = state.upcoming[index];
    if (!target) throw new DisTubeError("NO_SONG_POSITION", { context: { position } });
    const history = [...state.history];
    if (state.current) this.#appendHistory(history, state.current);
    for (const skipped of state.upcoming.slice(0, index)) this.#appendHistory(history, skipped);
    return {
      next: freezeState({
        ...state,
        current: target,
        upcoming: state.upcoming.slice(index + 1),
        history,
        paused: false,
        currentTime: 0,
      }),
      result: target,
      events: [
        { kind: "change", reason: QueueChangeReason.JUMP },
        { kind: "playSong", song: target },
      ],
      playback: { kind: "activate", song: target },
      conflict: fields([...STRUCTURAL_FIELDS, "paused", "currentTime"], [...STRUCTURAL_FIELDS]),
    };
  }

  #moveUpcoming(
    state: QueueState<Metadata, Filters>,
    fromIndex: number,
    toIndex: number,
  ): Reduced<Metadata, Filters, undefined> {
    this.#assertUpcomingIndex(state, fromIndex);
    this.#assertUpcomingIndex(state, toIndex);
    if (fromIndex === toIndex) return this.#replaceUpcoming(state, state.upcoming, "move");
    const upcoming = [...state.upcoming];
    const [moved] = upcoming.splice(fromIndex, 1);
    if (!moved) throw new DisTubeError("NO_SONG_POSITION", { context: { position: fromIndex } });
    upcoming.splice(toIndex, 0, moved);
    return this.#replaceUpcoming(state, upcoming, "move");
  }

  #removeUpcoming(state: QueueState<Metadata, Filters>, index: number): Reduced<Metadata, Filters, Song<Metadata>> {
    this.#assertUpcomingIndex(state, index);
    const upcoming = [...state.upcoming];
    const [removed] = upcoming.splice(index, 1);
    if (!removed) throw new DisTubeError("NO_SONG_POSITION", { context: { position: index } });
    return {
      next: freezeState({ ...state, upcoming }),
      result: removed,
      events: [{ kind: "change", reason: QueueChangeReason.EDIT }],
      conflict: fields(["upcoming"], ["upcoming", "destroyed"]),
    };
  }

  #replaceUpcoming(
    state: QueueState<Metadata, Filters>,
    upcoming: readonly Song<Metadata>[],
    operation: string,
  ): Reduced<Metadata, Filters, undefined> {
    if (upcoming.some(song => !(song instanceof Song))) {
      throw new DisTubeError("INVALID_INPUT", { context: { operation } });
    }
    const unchanged =
      state.upcoming.length === upcoming.length && state.upcoming.every((song, index) => song === upcoming[index]);
    return {
      next: unchanged ? state : freezeState({ ...state, upcoming }),
      result: undefined,
      events: unchanged ? [] : [{ kind: "change", reason: QueueChangeReason.EDIT }],
      conflict: fields(["upcoming"], ["upcoming", "destroyed"]),
    };
  }

  #assertUpcomingIndex(state: QueueState<Metadata, Filters>, index: number): void {
    if (!Number.isInteger(index) || index < 0 || index >= state.upcoming.length) {
      throw new DisTubeError("NO_SONG_POSITION", { context: { position: index } });
    }
  }

  #isSameSongMultiset(left: readonly Song<Metadata>[], right: readonly Song<Metadata>[]): boolean {
    if (left.length !== right.length) return false;
    const counts = new Map<Song<Metadata>, number>();
    for (const song of left) counts.set(song, (counts.get(song) ?? 0) + 1);
    for (const song of right) {
      const count = counts.get(song);
      if (!count) return false;
      if (count === 1) counts.delete(song);
      else counts.set(song, count - 1);
    }
    return counts.size === 0;
  }

  #change(
    state: QueueState<Metadata, Filters>,
    patch: Partial<QueueState<Metadata, Filters>>,
    reason: QueueChangeReason,
    playback?: PlaybackIntent<Metadata>,
  ): Reduced<Metadata, Filters, undefined> {
    const owns = Object.keys(patch) as QueueField[];
    const unchanged = owns.every(field => state[field] === patch[field]);
    return {
      next: unchanged ? state : freezeState({ ...state, ...patch }),
      result: undefined,
      events: unchanged ? [] : [{ kind: "change", reason }],
      playback: unchanged ? undefined : playback,
      conflict: fields(owns, [...owns, "destroyed"]),
    };
  }

  #finish(
    state: QueueState<Metadata, Filters>,
    song: Song<Metadata>,
  ): Reduced<Metadata, Filters, Song<Metadata> | undefined> {
    if (state.current !== song) throw new DisTubeError("INVALID_INPUT", { context: { operation: "staleFinish" } });
    if (state.repeatMode === RepeatMode.SONG) {
      return {
        next: freezeState({ ...state, current: undefined, paused: false, currentTime: 0 }),
        result: song,
        events: [{ kind: "finishSong", song }],
        playback: { kind: "restart", song },
        conflict: fields(["paused", "currentTime"], [...STRUCTURAL_FIELDS]),
      };
    }
    const upcoming = [...state.upcoming];
    const history = [...state.history];
    if (state.repeatMode === RepeatMode.QUEUE) upcoming.push(song);
    else this.#appendHistory(history, song);
    const next = upcoming.shift();
    return {
      next: freezeState({ ...state, current: undefined, upcoming, history, paused: false, currentTime: 0 }),
      result: next,
      events: [{ kind: "finishSong", song }],
      playback: next ? { kind: "activate", song: next } : state.autoplay ? { kind: "findRelated", song } : undefined,
      conflict: fields([...STRUCTURAL_FIELDS, "paused", "currentTime"], [...STRUCTURAL_FIELDS]),
    };
  }

  #activateSuccessor(
    state: QueueState<Metadata, Filters>,
    song: Song<Metadata>,
    autoplay: boolean,
  ): Reduced<Metadata, Filters, Song<Metadata>> {
    const events: QueueEventIntent<Metadata>[] = [];
    if (autoplay) events.push({ kind: "addSong", song, reason: QueueAddReason.AUTOPLAY });
    events.push({ kind: "playSong", song });
    return {
      next: freezeState({ ...state, current: song, paused: false, currentTime: 0 }),
      result: song,
      events,
      conflict: fields(["current", "paused", "currentTime"], [...STRUCTURAL_FIELDS]),
    };
  }

  #playbackFailed(
    state: QueueState<Metadata, Filters>,
    song: Song<Metadata>,
  ): Reduced<Metadata, Filters, Song<Metadata> | undefined> {
    if (state.current && state.current !== song) {
      throw new DisTubeError("INVALID_INPUT", { context: { operation: "stalePlaybackFailure" } });
    }
    const upcoming = [...state.upcoming];
    const next = upcoming.shift();
    return {
      next: freezeState({ ...state, current: undefined, upcoming, paused: false, currentTime: 0 }),
      result: next,
      events: [],
      playback: next ? { kind: "activate", song: next } : undefined,
      conflict: fields(["current", "upcoming", "paused", "currentTime"], [...STRUCTURAL_FIELDS]),
    };
  }

  #insert(
    current: readonly Song<Metadata>[],
    songs: readonly Song<Metadata>[],
    placement: QueuePlacement | number,
  ): readonly Song<Metadata>[] {
    if (songs.length === 0) return current;
    if (placement === QueuePlacement.APPEND) return [...current, ...songs];
    if (placement === QueuePlacement.NEXT) return [...songs, ...current];
    if (!Number.isInteger(placement) || placement < 1 || placement > current.length + 1) {
      throw new DisTubeError("NO_SONG_POSITION", { context: { placement } });
    }
    return [...current.slice(0, placement - 1), ...songs, ...current.slice(placement - 1)];
  }

  #appendHistory(history: Song<Metadata>[], song: Song<Metadata>): void {
    if (this.#historyLimit === 0) return;
    history.push(song);
    while (history.length > this.#historyLimit) history.shift();
  }

  #fieldsChangedSince(revision: number): ReadonlySet<QueueField> {
    const changed = new Set<QueueField>();
    for (let current = revision + 1; current <= this.#state.revision; current += 1) {
      for (const field of this.#changedByRevision.get(current) ?? []) changed.add(field);
    }
    return changed;
  }

  #intersects(left: ReadonlySet<QueueField>, right: ReadonlySet<QueueField>): boolean {
    for (const field of left) if (right.has(field)) return true;
    return false;
  }

  #assertUsable(): void {
    if (this.#state.destroyed) throw new DisTubeError("QUEUE_DESTROYED");
  }
}

