import type { EmptyFilterCatalog, FilterCatalog, FilterParamsOf, FilterState } from "@/filters/contracts";
import type { FilterMutation } from "@/filters/FilterEngine";

export type FilterInput<Catalog extends FilterCatalog> = Partial<{
  [Name in keyof Catalog]: FilterParamsOf<Catalog[Name]>;
}>;

interface QueueFilterController<Catalog extends FilterCatalog> {
  getFilterState(): FilterState<Catalog>;
  mutateFilters(mutation: FilterMutation<Catalog>, signal?: AbortSignal): Promise<void>;
}

/** Stable public filter handle backed by the deep serialized Filter Engine port. */
export class QueueFilters<Catalog extends FilterCatalog = EmptyFilterCatalog> {
  readonly #definitions: Catalog;
  readonly #controller: QueueFilterController<Catalog>;

  /** @internal */
  constructor(definitions: Catalog, controller: unknown) {
    this.#definitions = definitions;
    this.#controller = controller as QueueFilterController<Catalog>;
  }

  get available(): Catalog {
    return this.#definitions;
  }

  get active(): FilterState<Catalog> {
    return this.#controller.getFilterState();
  }

  has<Name extends keyof Catalog>(name: Name): boolean {
    return Object.hasOwn(this.active, name);
  }

  add<Name extends keyof Catalog & string>(
    name: Name,
    params: FilterParamsOf<Catalog[Name]>,
    signal?: AbortSignal,
  ): Promise<this>;
  add(filters: FilterInput<Catalog>, signal?: AbortSignal): Promise<this>;
  async add(
    nameOrFilters: keyof Catalog | FilterInput<Catalog>,
    paramsOrSignal?: FilterParamsOf<Catalog[keyof Catalog]> | AbortSignal,
    signal?: AbortSignal,
  ): Promise<this> {
    const name = typeof nameOrFilters === "string" ? nameOrFilters : undefined;
    const callerSignal = paramsOrSignal instanceof AbortSignal ? paramsOrSignal : signal;
    const input = name ? { [name]: paramsOrSignal } : nameOrFilters;
    if (Object.keys(input).length === 0) return this;
    await this.#controller.mutateFilters(
      { kind: "add", filters: input as Readonly<Record<string, unknown>> },
      callerSignal,
    );
    return this;
  }

  remove<Name extends keyof Catalog & string>(name: Name, signal?: AbortSignal): Promise<this>;
  remove(names: readonly (keyof Catalog & string)[], signal?: AbortSignal): Promise<this>;
  async remove(nameOrNames: keyof Catalog | readonly (keyof Catalog)[], signal?: AbortSignal): Promise<this> {
    const names = (Array.isArray(nameOrNames) ? nameOrNames : [nameOrNames]) as readonly (keyof Catalog & string)[];
    if (names.length === 0) return this;
    await this.#controller.mutateFilters({ kind: "remove", names }, signal);
    return this;
  }

  async set(filters: FilterInput<Catalog>, signal?: AbortSignal): Promise<this> {
    await this.#controller.mutateFilters(
      { kind: "set", filters: filters as Readonly<Record<string, unknown>> },
      signal,
    );
    return this;
  }

  async clear(signal?: AbortSignal): Promise<this> {
    if (Object.keys(this.active).length === 0) return this;
    await this.#controller.mutateFilters({ kind: "clear" }, signal);
    return this;
  }
}

