import type { SnowflakeId } from "@/adapters/types";
import type { QueueSnapshot, VoiceSnapshot } from "@/api/snapshots";
import {
  QueueAddReason,
  QueueDeleteReason,
  QueuePlacement,
  QueueSkipBehavior,
  type RepeatMode,
  VoiceFeature,
} from "@/enums";
import { DisTubeError, normalizeError } from "@/errors/DisTubeError";
import type { FilterCatalog, FilterState } from "@/filters/contracts";
import { FilterEngine, type FilterMutation } from "@/filters/FilterEngine";
import type { MediaResolver } from "@/media/MediaResolver";
import type { Playlist } from "@/media/Playlist";
import type { Song } from "@/media/Song";
import type { PlaybackClock } from "@/playback/PlaybackClock";
import { PlaybackEngine, type PlaybackExhaustionReason, type PlaybackSubscription } from "@/playback/PlaybackEngine";
import type { PreparedPlayback, VoiceLifecycleNotification, VoiceRuntimeCapability } from "@/plugin";
import { Queue } from "@/queue/Queue";
import { QueueAggregate, type QueueCommand, type QueueCommit, type QueueTransition } from "@/queue/QueueAggregate";
import { shuffleArray } from "@/queue/shuffle";
import type { CommandOperation, SessionCoordinator } from "@/session/SessionCoordinator";
import type { SessionEvents } from "@/session/SessionEvents";
import type { QueueDefaults } from "@/types/options";
import type { MediaInput, PlayOptions, QueueEditCallback } from "@/types/playback";

export type QueueRuntimeLifecycleState = "reserved" | "active" | "terminal";

export interface QueueVoiceAccess<Connection> {
  snapshot(): VoiceSnapshot | undefined;
  connection(): Connection | undefined;
  requireConnection(): Connection;
}

export interface QueueRuntimeObserver<Metadata> {
  terminal(runtimeGeneration: number, reason: QueueDeleteReason): void;
  error(runtimeGeneration: number, error: Error, song?: Song<Metadata>): void;
}

export interface QueueRuntimeOptions<
  Metadata,
  Filters extends FilterCatalog,
  Connection,
  Prepared extends PreparedPlayback,
> {
  readonly guildId: SnowflakeId;
  readonly runtimeGeneration: number;
  readonly voice: VoiceRuntimeCapability<Filters, Connection, Prepared>;
  readonly voiceAccess: QueueVoiceAccess<Connection>;
  readonly resolver: MediaResolver<Metadata>;
  readonly defaults: Required<QueueDefaults>;
  readonly filters: Filters;
  readonly coordinator: SessionCoordinator;
  readonly events: SessionEvents<Metadata, Filters>;
  readonly playbackClock: PlaybackClock;
  readonly observer: QueueRuntimeObserver<Metadata>;
}

export interface QueueCleanupUnit {
  readonly name: string;
  readonly run: () => void | Promise<void>;
}

/** Owns one Queue handle generation, aggregate, playback, filters, clock, and terminal snapshot. */
export class QueueRuntime<Metadata, Filters extends FilterCatalog, Connection, Prepared extends PreparedPlayback> {
  readonly runtimeGeneration: number;
  readonly queue: Queue<Metadata, Filters>;
  readonly #voiceCapability: VoiceRuntimeCapability<Filters, Connection, Prepared>;
  readonly #voiceAccess: QueueVoiceAccess<Connection>;
  readonly #resolver: MediaResolver<Metadata>;
  readonly #coordinator: SessionCoordinator;
  readonly #events: SessionEvents<Metadata, Filters>;
  readonly #clock: PlaybackClock;
  readonly #observer: QueueRuntimeObserver<Metadata>;
  readonly #aggregate: QueueAggregate<Metadata, Filters>;
  readonly #filterEngine: FilterEngine<Filters>;
  readonly #playback: PlaybackEngine<Metadata, Filters, Connection, Prepared>;
  #state: QueueRuntimeLifecycleState = "reserved";
  #snapshot: QueueSnapshot<Metadata, Filters>;
  #pendingReservations = 0;
  #acceptingCommands = true;
  #terminalNotified = false;

  constructor(options: QueueRuntimeOptions<Metadata, Filters, Connection, Prepared>) {
    this.runtimeGeneration = options.runtimeGeneration;
    this.#voiceCapability = options.voice;
    this.#voiceAccess = options.voiceAccess;
    this.#resolver = options.resolver;
    this.#coordinator = options.coordinator;
    this.#events = options.events;
    this.#clock = options.playbackClock;
    this.#observer = options.observer;
    this.#aggregate = new QueueAggregate({
      guildId: options.guildId,
      historyLimit: options.defaults.historyLimit,
      repeatMode: options.defaults.repeatMode,
      autoplay: options.defaults.autoplay,
      volume: options.defaults.volume,
      filters: Object.freeze({}) as FilterState<Filters>,
    });
    this.#snapshot = this.#projectSnapshot();
    this.queue = new Queue(options.guildId, options.filters, this);
    this.#filterEngine = new FilterEngine(options.filters, {
      current: () => {
        const current = this.#aggregate.snapshot();
        return { revision: current.revision, filters: current.filters };
      },
      applyBackend: async (candidate, signal) => {
        const method = this.#requireVoiceFeature(this.#voiceCapability.applyFilters, VoiceFeature.FILTERS);
        await method.call(this.#voiceCapability, this.#voiceAccess.requireConnection(), candidate, signal);
      },
      commit: async (candidate, expectedRevision) => {
        const current = this.#aggregate.snapshot();
        if (current.revision !== expectedRevision) {
          throw new DisTubeError("FILTER_STALE", {
            context: { expectedRevision, actualRevision: current.revision },
          });
        }
        const transition = this.#aggregate.plan({ type: "setFilters", filters: candidate });
        if (transition.events.length > 0) await this.#commit(transition);
      },
    });
    this.#playback = new PlaybackEngine({
      voice: options.voice,
      resolver: options.resolver,
      operations: options.coordinator,
      clock: options.playbackClock,
      onNotification: (subscription, notification) => this.#handlePlaybackNotification(subscription, notification),
    });
  }

  get state(): QueueRuntimeLifecycleState {
    return this.#state;
  }

  get active(): boolean {
    return this.#state === "active";
  }

  getQueueSnapshot(): QueueSnapshot<Metadata, Filters> {
    return this.#state === "active" ? this.#projectSnapshot() : this.#snapshot;
  }

  getFilterState(): FilterState<Filters> {
    return this.getQueueSnapshot().filters;
  }

  play(
    input: MediaInput<Metadata>,
    options: PlayOptions<Metadata> = {},
    ready: Promise<unknown> = Promise.resolve(),
  ): Promise<Queue<Metadata, Filters>> {
    return this.#addMedia(input, options, QueueAddReason.PLAY, true, ready);
  }

  async add(input: MediaInput<Metadata>, options: PlayOptions<Metadata> = {}): Promise<void> {
    this.#assertActive();
    await this.#addMedia(input, options, QueueAddReason.PLAY, false, Promise.resolve());
  }

  async addRelated(song?: Song<Metadata>, callerSignal?: AbortSignal): Promise<Song<Metadata>> {
    this.#assertActive();
    const operation = this.#coordinator.begin("queue", callerSignal);
    const slot = this.#coordinator.reserveStructural(operation.signal);
    try {
      const sourceSong = song ?? this.#aggregate.snapshot().current;
      if (!sourceSong) throw new DisTubeError("NO_RELATED");
      const result = await this.#resolver.getRelated(sourceSong, operation.signal, error =>
        this.#observer.error(this.runtimeGeneration, error, sourceSong),
      );
      if (!result.song) throw new DisTubeError("NO_RELATED");
      await slot.run(() => this.#commitMedia(result.song as Song<Metadata>, {}, operation, QueueAddReason.RELATED));
      return result.song;
    } catch (error: unknown) {
      slot.cancel(error);
      throw this.#commandError(error, "addRelated");
    } finally {
      operation.complete();
    }
  }

  async setPaused(paused: boolean, callerSignal?: AbortSignal): Promise<void> {
    this.#assertActive();
    const transition = this.#aggregate.plan({ type: "setPaused", paused });
    if (transition.events.length === 0) return;
    const method = paused
      ? this.#requireVoiceFeature(this.#voiceCapability.pause, VoiceFeature.PAUSE)
      : this.#requireVoiceFeature(this.#voiceCapability.resume, VoiceFeature.RESUME);
    const operation = this.#coordinator.begin("playback", callerSignal);
    try {
      await method.call(this.#voiceCapability, this.#voiceAccess.requireConnection(), operation.signal);
      if (paused) this.#clock.pause();
      else this.#clock.resume();
      await this.#commit(transition);
    } finally {
      operation.complete();
    }
  }

  skip(signal?: AbortSignal): Promise<Song<Metadata>> {
    return this.#navigate({ type: "skip" }, signal);
  }

  previous(signal?: AbortSignal): Promise<Song<Metadata>> {
    return this.#navigate({ type: "previous" }, signal);
  }

  jumpTo(position: number, signal?: AbortSignal): Promise<Song<Metadata>> {
    return this.#navigate({ type: "jump", position }, signal);
  }

  async seek(time: number, callerSignal?: AbortSignal): Promise<void> {
    this.#assertActive();
    const transition = this.#aggregate.plan({ type: "seek", time });
    const method = this.#requireVoiceFeature(this.#voiceCapability.seek, VoiceFeature.SEEK);
    const operation = this.#coordinator.begin("playback", callerSignal);
    try {
      await method.call(this.#voiceCapability, this.#voiceAccess.requireConnection(), time, operation.signal);
      this.#clock.seek(time);
      await this.#commit(transition);
    } finally {
      operation.complete();
    }
  }

  async setVolume(volume: number, callerSignal?: AbortSignal): Promise<void> {
    this.#assertActive();
    const transition = this.#aggregate.plan({ type: "setVolume", volume });
    if (transition.events.length === 0) return;
    const method = this.#requireVoiceFeature(this.#voiceCapability.setVolume, VoiceFeature.VOLUME);
    const operation = this.#coordinator.begin("playback", callerSignal);
    try {
      await method.call(this.#voiceCapability, this.#voiceAccess.requireConnection(), volume, operation.signal);
      await this.#commit(transition);
    } finally {
      operation.complete();
    }
  }

  async setAutoplay(autoplay: boolean, signal?: AbortSignal): Promise<void> {
    this.#assertActive();
    signal?.throwIfAborted();
    const transition = this.#aggregate.plan({ type: "setAutoplay", autoplay });
    if (transition.events.length > 0) await this.#commit(transition);
  }

  async setRepeatMode(mode: RepeatMode, signal?: AbortSignal): Promise<void> {
    this.#assertActive();
    signal?.throwIfAborted();
    const transition = this.#aggregate.plan({ type: "setRepeatMode", repeatMode: mode });
    if (transition.events.length > 0) await this.#commit(transition);
  }

  move(fromIndex: number, toIndex: number, signal?: AbortSignal): Promise<void> {
    return this.#commitUpcoming({ type: "moveUpcoming", fromIndex, toIndex }, signal);
  }

  remove(index: number, signal?: AbortSignal): Promise<Song<Metadata>> {
    return this.#commitUpcoming<Song<Metadata>>({ type: "removeUpcoming", index }, signal);
  }

  clearUpcoming(signal?: AbortSignal): Promise<void> {
    return this.#commitUpcoming({ type: "clearUpcoming" }, signal);
  }

  async shuffle(signal?: AbortSignal): Promise<void> {
    this.#assertActive();
    signal?.throwIfAborted();
    const slot = this.#coordinator.reserveStructural(signal);
    await slot.run(async () => {
      signal?.throwIfAborted();
      const transition = this.#aggregate.plan({
        type: "shuffleUpcoming",
        upcoming: shuffleArray(this.#aggregate.snapshot().upcoming),
      });
      if (transition.events.length > 0) await this.#commit(transition);
    });
  }

  async edit(callback: QueueEditCallback<Metadata>, signal?: AbortSignal): Promise<void> {
    this.#assertActive();
    signal?.throwIfAborted();
    const slot = this.#coordinator.reserveStructural(signal);
    await slot.run(async () => {
      signal?.throwIfAborted();
      const next = [...this.#aggregate.snapshot().upcoming];
      callback(next);
      const transition = this.#aggregate.plan({ type: "edit", upcoming: next });
      if (transition.events.length > 0) await this.#commit(transition);
    });
  }

  async stop(): Promise<void> {
    this.#assertActive();
    this.#coordinator.invalidate("queue", "playback");
    const slot = this.#coordinator.reserveStructural();
    await slot.run(() => this.terminate(QueueDeleteReason.STOPPED, true));
  }

  mutateFilters(mutation: FilterMutation<Filters>, callerSignal?: AbortSignal): Promise<void> {
    this.#assertActive();
    return this.#filterEngine.execute(mutation, callerSignal);
  }

  async terminate(reason: QueueDeleteReason, publish: boolean, bestEffort = false): Promise<void> {
    if (this.#state === "terminal") return;
    try {
      await this.#stopActivePlayback();
    } catch (error: unknown) {
      if (!bestEffort) throw error;
      this.#observer.error(this.runtimeGeneration, normalizeError(error), this.#aggregate.snapshot().current);
    }
    const record = await this.#coordinator.commit({
      name: "deleteQueue",
      validate: () => {
        if (this.#state === "terminal") throw new DisTubeError("QUEUE_DESTROYED");
      },
      commit: () => {
        const commit = this.#aggregate.execute({ type: "destroy", reason });
        this.#state = "terminal";
        this.#acceptingCommands = false;
        this.#snapshot = this.#projectCommit(commit);
        if (publish) this.#events.queue(this.queue, { ...commit, newSnapshot: this.#snapshot }, this.runtimeGeneration);
        return commit;
      },
    });
    this.#notifyTerminal(reason);
    void record;
  }

  beginDestroy(): void {
    if (!this.#acceptingCommands) return;
    this.#acceptingCommands = false;
    this.#clock.destroy();
    if (this.#state !== "terminal") {
      this.#coordinator.commitTerminal({
        name: "destroyQueueRuntime",
        commit: () => {
          const commit = this.#aggregate.execute({ type: "destroy", reason: QueueDeleteReason.STOPPED });
          this.#state = "terminal";
          this.#snapshot = this.#projectCommit(commit);
        },
      });
    }
  }

  cleanupUnits(prefix = `queue:${this.queue.guildId}:${this.runtimeGeneration}`): readonly QueueCleanupUnit[] {
    this.beginDestroy();
    return Object.freeze([
      { name: `${prefix}:playback`, run: () => this.#stopPlaybackBackend() },
      { name: `${prefix}:resources`, run: () => this.#disposePlaybackResources() },
      { name: `${prefix}:state`, run: () => this.#cleanupState() },
    ]);
  }

  async #addMedia(
    input: MediaInput<Metadata>,
    options: PlayOptions<Metadata>,
    reason: QueueAddReason,
    reserve: boolean,
    ready: Promise<unknown>,
  ): Promise<Queue<Metadata, Filters>> {
    this.#assertUsable();
    if (!reserve) this.#assertActive();
    if (reserve) this.#pendingReservations += 1;
    const operation = this.#coordinator.begin("queue", options.signal);
    const slot = this.#coordinator.reserveStructural(operation.signal);
    try {
      const mediaPromise = this.#resolve(input, options.metadata, operation);
      const [media] = await Promise.all([mediaPromise, ready]);
      return await slot.run(() => this.#commitMedia(media, options, operation, reason));
    } catch (error: unknown) {
      slot.cancel(error);
      throw this.#commandError(error, reserve ? "play" : "add");
    } finally {
      operation.complete();
      if (reserve) this.#releaseReservation();
    }
  }

  async #resolve(
    input: MediaInput<Metadata>,
    metadata: Metadata | undefined,
    operation: CommandOperation,
  ): Promise<Song<Metadata> | Playlist<Metadata>> {
    try {
      const media = await this.#resolver.resolve(input, metadata, operation.signal);
      this.#assertCurrent(operation);
      return media;
    } catch (cause: unknown) {
      if (cause instanceof DisTubeError) throw cause;
      throw new DisTubeError("MEDIA_RESOLUTION_FAILED", { cause });
    }
  }

  async #commitMedia(
    media: Song<Metadata> | Playlist<Metadata>,
    options: PlayOptions<Metadata>,
    operation: CommandOperation,
    reason: QueueAddReason,
  ): Promise<Queue<Metadata, Filters>> {
    this.#assertCurrent(operation);
    const transition = this.#aggregate.plan<Song<Metadata> | undefined>({
      type: "add",
      media,
      reason,
      placement: options.placement ?? QueuePlacement.APPEND,
      replace: options.skip === true,
      skipBehavior: options.skipBehavior ?? QueueSkipBehavior.HISTORY,
    });
    const started = transition.playback?.kind === "activate" ? transition.playback.song : undefined;
    try {
      if (started) await this.#startPlayback(started, operation.signal);
      await this.#coordinator.commit({
        name: "commitMedia",
        validate: () => {
          this.#assertCurrent(operation);
          if (this.#state === "terminal") throw new DisTubeError("QUEUE_DESTROYED");
        },
        commit: () => {
          this.#state = "active";
          const commit = this.#aggregate.commit(transition, this.#voiceAccess.snapshot());
          this.#snapshot = this.#projectCommit(commit);
          this.#events.queue(this.queue, { ...commit, newSnapshot: this.#snapshot }, this.runtimeGeneration);
        },
      });
    } catch (error: unknown) {
      if (started && this.#playback.activeSong === started) await this.#stopActivePlayback().catch(() => {});
      throw error;
    }
    return this.queue;
  }

  async #navigate(
    command: Extract<QueueCommand<Metadata, Filters>, { type: "skip" | "previous" | "jump" }>,
    callerSignal?: AbortSignal,
  ): Promise<Song<Metadata>> {
    this.#assertActive();
    const operation = this.#coordinator.begin("queue", callerSignal);
    const slot = this.#coordinator.reserveStructural(operation.signal);
    try {
      return await slot.run(async () => {
        this.#assertActive();
        const transition = this.#aggregate.plan<Song<Metadata>>(command);
        const target = transition.result;
        try {
          if (transition.playback?.kind === "activate") await this.#startPlayback(target, operation.signal);
          await this.#commit(transition);
          return target;
        } catch (error: unknown) {
          if (this.#playback.activeSong === target) await this.#stopActivePlayback().catch(() => {});
          throw error;
        }
      });
    } finally {
      operation.complete();
    }
  }

  async #commit<Result>(
    transition: QueueTransition<Metadata, Filters, Result>,
  ): Promise<QueueCommit<Metadata, Filters, Result>> {
    const record = await this.#coordinator.commit({
      name: "commitQueue",
      validate: () => this.#assertActive(),
      commit: () => {
        const commit = this.#aggregate.commit(transition, this.#voiceAccess.snapshot());
        this.#snapshot = this.#projectCommit(commit);
        this.#events.queue(this.queue, { ...commit, newSnapshot: this.#snapshot }, this.runtimeGeneration);
        return commit;
      },
    });
    return record.result;
  }

  async #commitUpcoming<Result = void>(
    command: Extract<QueueCommand<Metadata, Filters>, { type: "moveUpcoming" | "removeUpcoming" | "clearUpcoming" }>,
    signal?: AbortSignal,
  ): Promise<Result> {
    this.#assertActive();
    signal?.throwIfAborted();
    const slot = this.#coordinator.reserveStructural(signal);
    return slot.run(async () => {
      signal?.throwIfAborted();
      const transition = this.#aggregate.plan<Result>(command);
      if (transition.events.length === 0) return transition.result;
      return (await this.#commit(transition)).result;
    });
  }

  async #startPlayback(song: Song<Metadata>, callerSignal?: AbortSignal): Promise<void> {
    const outcome = await this.#playback.activate(song, this.#voiceAccess.requireConnection(), callerSignal);
    if (outcome.kind !== "activated") throw new DisTubeError("PLAYBACK_FAILED", { context: { song } });
  }

  async #stopActivePlayback(): Promise<void> {
    const connection = this.#voiceAccess.connection();
    if (connection === undefined) return;
    await this.#playback.stop(connection);
  }

  async #stopPlaybackBackend(): Promise<void> {
    const connection = this.#voiceAccess.connection();
    if (connection === undefined) return;
    await this.#playback.stopBackend(connection);
  }

  async #disposePlaybackResources(): Promise<void> {
    const errors = await this.#playback.disposeActive();
    if (errors.length > 0) throw new AggregateError(errors, "Playback resource cleanup failed");
  }

  #cleanupState(): void {
    if (this.#state !== "terminal") {
      const commit = this.#aggregate.execute({ type: "destroy", reason: QueueDeleteReason.STOPPED });
      this.#snapshot = this.#projectCommit(commit);
      this.#state = "terminal";
    }
  }

  #handlePlaybackNotification(
    subscription: PlaybackSubscription<Metadata>,
    notification: Extract<VoiceLifecycleNotification, { type: "finish" | "error" }>,
  ): void {
    if (!this.#playback.isCurrent(subscription)) return;
    if (notification.type === "finish") {
      this.#runBackground(this.#handleNaturalFinish(subscription), subscription.song);
    } else {
      this.#runBackground(
        this.#handlePlaybackFailure(subscription, subscription.song, notification.error),
        subscription.song,
      );
    }
  }

  async #handleNaturalFinish(subscription: PlaybackSubscription<Metadata>): Promise<void> {
    const slot = this.#coordinator.reserveStructural(subscription.signal);
    await slot.run(async () => {
      if (this.#state !== "active") return;
      await this.#playback.progressNaturalFinish(
        subscription,
        this.#voiceAccess.requireConnection(),
        this.#playbackProgression(),
      );
    });
  }

  async #handlePlaybackFailure(
    subscription: PlaybackSubscription<Metadata> | undefined,
    song: Song<Metadata>,
    error: Error,
  ): Promise<void> {
    if (subscription && !this.#playback.isCurrent(subscription)) return;
    const slot = this.#coordinator.reserveStructural(subscription?.signal);
    await slot.run(async () => {
      if (this.#state !== "active") return;
      if (subscription && !this.#playback.isCurrent(subscription)) return;
      await this.#playback.progressFailure(
        song,
        error,
        this.#voiceAccess.requireConnection(),
        this.#playbackProgression(),
      );
    });
  }

  #playbackProgression() {
    return {
      isQueueActive: (): boolean => this.#state === "active",
      discardFailed: async (song: Song<Metadata>): Promise<Song<Metadata> | undefined> => {
        const transition = this.#aggregate.plan<Song<Metadata> | undefined>({ type: "playbackFailed", song });
        return (await this.#commit(transition)).result;
      },
      reportFailure: (error: Error, song: Song<Metadata>): void =>
        this.#observer.error(this.runtimeGeneration, error, song),
      finishCurrent: async (
        song: Song<Metadata>,
      ): Promise<{ readonly next?: Song<Metadata>; readonly findRelated: boolean }> => {
        const transition = this.#aggregate.plan<Song<Metadata> | undefined>({ type: "finish", song });
        const commit = await this.#commit(transition);
        return { next: commit.result, findRelated: commit.playback?.kind === "findRelated" };
      },
      commitActivation: async (song: Song<Metadata>, autoplay: boolean): Promise<void> => {
        const transition = this.#aggregate.plan<Song<Metadata>>({ type: "activateSuccessor", song, autoplay });
        await this.#commit(transition);
      },
      exhaust: async (reason: PlaybackExhaustionReason): Promise<void> => {
        const queueReason =
          reason === "finished"
            ? QueueDeleteReason.FINISHED
            : reason === "no-related"
              ? QueueDeleteReason.NO_RELATED
              : QueueDeleteReason.ERROR;
        await this.terminate(queueReason, true, true);
      },
    };
  }

  #projectSnapshot(): QueueSnapshot<Metadata, Filters> {
    const snapshot = this.#aggregate.snapshot(this.#voiceAccess.snapshot());
    return Object.freeze({ ...snapshot, currentTime: this.#clock.position() });
  }

  #projectCommit<Result>(commit: QueueCommit<Metadata, Filters, Result>): QueueSnapshot<Metadata, Filters> {
    return Object.freeze({ ...commit.newSnapshot, currentTime: this.#clock.position() });
  }

  #releaseReservation(): void {
    this.#pendingReservations = Math.max(0, this.#pendingReservations - 1);
    if (this.#state !== "reserved" || this.#pendingReservations > 0) return;
    const commit = this.#aggregate.execute({ type: "destroy", reason: QueueDeleteReason.STOPPED });
    this.#state = "terminal";
    this.#acceptingCommands = false;
    this.#snapshot = this.#projectCommit(commit);
    this.#notifyTerminal(QueueDeleteReason.STOPPED);
  }

  #notifyTerminal(reason: QueueDeleteReason): void {
    if (this.#terminalNotified) return;
    this.#terminalNotified = true;
    this.#observer.terminal(this.runtimeGeneration, reason);
  }

  #runBackground(task: Promise<void>, song?: Song<Metadata>): void {
    void task.catch((error: unknown) => {
      if (!this.#acceptingCommands || (error instanceof DOMException && error.name === "AbortError")) return;
      this.#observer.error(this.runtimeGeneration, normalizeError(error), song);
    });
  }

  #assertCurrent(operation: CommandOperation): void {
    if (operation.isCurrent()) return;
    throw operation.signal.reason ?? new DOMException("Operation superseded", "AbortError");
  }

  #assertActive(): void {
    this.#assertUsable();
    if (this.#state !== "active") throw new DisTubeError("QUEUE_DESTROYED");
  }

  #assertUsable(): void {
    if (!this.#acceptingCommands || this.#state === "terminal") throw new DisTubeError("QUEUE_DESTROYED");
  }

  #requireVoiceFeature<Method>(method: Method | undefined, feature: VoiceFeature): Method {
    if (!method) throw new DisTubeError("VOICE_FEATURE_UNSUPPORTED", { context: { feature } });
    return method;
  }

  #commandError(error: unknown, operation: string): Error {
    if (error instanceof Error) return error;
    return new DisTubeError("INVALID_INPUT", { cause: error, context: { operation } });
  }
}

