/** Returns an unbiased Fisher-Yates permutation without mutating the input. */
export function shuffleArray<Value>(values: readonly Value[], random: () => number = Math.random): Value[] {
  const shuffled = [...values];
  for (let index = shuffled.length - 1; index > 0; index -= 1) {
    const target = Math.floor(random() * (index + 1));
    [shuffled[index], shuffled[target]] = [shuffled[target] as Value, shuffled[index] as Value];
  }
  return shuffled;
}

