import { DisTubeError, normalizeError } from "@/errors/DisTubeError";
import type { Scheduler } from "@/runtime/Scheduler";

export interface CleanupUnit {
  readonly name: string;
  readonly deadlineMs?: number;
  readonly run: () => void | PromiseLike<void>;
}

export type CleanupRecord =
  | { readonly name: string; readonly status: "success" }
  | { readonly name: string; readonly status: "failure"; readonly error: Error }
  | { readonly name: string; readonly status: "timeout"; readonly deadlineMs: number };

export interface CleanupPlanResult {
  readonly records: readonly CleanupRecord[];
  readonly error?: DisTubeError<"CLEANUP_FAILED">;
}

/** Flat ordered, memoized, best-effort cleanup with one deadline per unit. */
export class CleanupPlan {
  readonly #scheduler: Scheduler;
  readonly #defaultDeadlineMs: number;
  readonly #units: CleanupUnit[] = [];
  #runPromise?: Promise<CleanupPlanResult>;

  constructor(scheduler: Scheduler, defaultDeadlineMs: number) {
    if (!Number.isFinite(defaultDeadlineMs) || defaultDeadlineMs <= 0) {
      throw new RangeError("defaultDeadlineMs must be positive and finite");
    }
    this.#scheduler = scheduler;
    this.#defaultDeadlineMs = defaultDeadlineMs;
  }

  add(unit: CleanupUnit): void {
    if (this.#runPromise) throw new Error("CleanupPlan has already started");
    if (!unit.name) throw new TypeError("Cleanup unit name is required");
    if (this.#units.some(current => current.name === unit.name))
      throw new Error(`Duplicate cleanup unit: ${unit.name}`);
    this.#units.push(Object.freeze({ ...unit }));
  }

  run(): Promise<CleanupPlanResult> {
    this.#runPromise ??= this.#execute();
    return this.#runPromise;
  }

  async #execute(): Promise<CleanupPlanResult> {
    const records: CleanupRecord[] = [];
    for (const unit of this.#units) records.push(await this.#runUnit(unit));
    const failed = records.filter(record => record.status !== "success");
    if (failed.length === 0) return Object.freeze({ records: Object.freeze(records) });
    const causes = failed.map(record =>
      record.status === "failure"
        ? record.error
        : new Error(`Cleanup unit ${record.name} timed out after ${record.deadlineMs}ms`),
    );
    const error = new DisTubeError("CLEANUP_FAILED", {
      cause: new AggregateError(causes, "Cleanup plan failed"),
      context: { units: Object.freeze(failed) },
    });
    return Object.freeze({ records: Object.freeze(records), error });
  }

  async #runUnit(unit: CleanupUnit): Promise<CleanupRecord> {
    const deadlineMs = unit.deadlineMs ?? this.#defaultDeadlineMs;
    let timeout = false;
    let resolveTimeout!: () => void;
    const deadline = new Promise<void>(resolve => {
      resolveTimeout = resolve;
    });
    const scheduled = this.#scheduler.schedule(
      "timeout",
      () => {
        timeout = true;
        resolveTimeout();
      },
      deadlineMs,
    );
    const running = Promise.resolve().then(unit.run);
    running.catch(() => {});
    try {
      await Promise.race([running, deadline]);
      if (timeout) return Object.freeze({ name: unit.name, status: "timeout", deadlineMs });
      await running;
      return Object.freeze({ name: unit.name, status: "success" });
    } catch (error: unknown) {
      return Object.freeze({ name: unit.name, status: "failure", error: normalizeError(error) });
    } finally {
      scheduled.cancel();
    }
  }
}

