import { normalizeError } from "@/errors/DisTubeError";

export interface ResourceDisposalRecord {
  readonly name: string;
  readonly status: "disposed" | "failed";
  readonly error?: Error;
}

export interface ResourceScopeResult {
  readonly scope: string;
  readonly records: readonly ResourceDisposalRecord[];
  readonly errors: readonly Error[];
}

interface ResourceRegistration {
  readonly name: string;
  readonly dispose: () => void | PromiseLike<void>;
}

/** Named resource owner with memoized exactly-once disposal and explicit transfer. */
export class ResourceScope {
  readonly name: string;
  #resources: ResourceRegistration[] = [];
  #disposePromise?: Promise<ResourceScopeResult>;
  #transferred = false;

  constructor(name: string) {
    if (!name) throw new TypeError("ResourceScope name is required");
    this.name = name;
  }

  register(name: string, dispose: () => void | PromiseLike<void>): void {
    this.#assertOwnable();
    if (!name) throw new TypeError("Resource name is required");
    if (this.#resources.some(resource => resource.name === name)) throw new Error(`Duplicate resource: ${name}`);
    this.#resources.push({ name, dispose });
  }

  child(name: string): ResourceScope {
    const child = new ResourceScope(`${this.name}/${name}`);
    this.register(`scope:${name}`, () =>
      child.dispose().then(result => {
        if (result.errors.length > 0) throw new AggregateError(result.errors, `Child scope ${child.name} failed`);
      }),
    );
    return child;
  }

  transferTo(target: ResourceScope): void {
    this.#assertOwnable();
    target.#assertOwnable();
    const targetNames = new Set(target.#resources.map(resource => resource.name));
    const duplicate = this.#resources.find(resource => targetNames.has(resource.name));
    if (duplicate) throw new Error(`Duplicate resource: ${duplicate.name}`);
    for (const resource of this.#resources) target.register(resource.name, resource.dispose);
    this.#resources = [];
    this.#transferred = true;
  }

  dispose(): Promise<ResourceScopeResult> {
    if (this.#disposePromise) return this.#disposePromise;
    let resolveResult!: (result: ResourceScopeResult) => void;
    this.#disposePromise = new Promise(resolve => {
      resolveResult = resolve;
    });
    void this.#disposeAll().then(resolveResult);
    return this.#disposePromise;
  }

  async #disposeAll(): Promise<ResourceScopeResult> {
    const records: ResourceDisposalRecord[] = [];
    const errors: Error[] = [];
    for (const resource of [...this.#resources].reverse()) {
      try {
        await resource.dispose();
        records.push(Object.freeze({ name: resource.name, status: "disposed" }));
      } catch (error: unknown) {
        const normalized = normalizeError(error);
        errors.push(normalized);
        records.push(Object.freeze({ name: resource.name, status: "failed", error: normalized }));
      }
    }
    this.#resources = [];
    return Object.freeze({ scope: this.name, records: Object.freeze(records), errors: Object.freeze(errors) });
  }

  #assertOwnable(): void {
    if (this.#disposePromise) throw new Error(`ResourceScope ${this.name} is disposing or disposed`);
    if (this.#transferred) throw new Error(`ResourceScope ${this.name} transferred ownership`);
  }
}

