import { ResourceScope } from "@/resources/ResourceScope";
import type { Awaitable } from "@/types/awaitable";

/** Core-owned lifetime for an opaque source playback resource. */
export class StreamLease<Value = unknown> {
  readonly value: Value;
  readonly #scope: ResourceScope;
  #disposePromise?: Promise<void>;

  constructor(value: Value, cleanup?: () => Awaitable<void>) {
    this.value = value;
    this.#scope = new ResourceScope("stream-lease");
    if (cleanup) this.#scope.register("source-resource", cleanup);
  }

  get isDisposed(): boolean {
    return this.#disposePromise !== undefined;
  }

  dispose(): Promise<void> {
    this.#disposePromise ??= this.#scope.dispose().then(result => {
      if (result.errors.length > 0) throw new AggregateError(result.errors, "StreamLease cleanup failed");
    });
    return this.#disposePromise;
  }
}

