import type { ClientAdapter, NormalizedVoiceChannel, SnowflakeId } from "@/adapters/types";
import type { DisTubeEventMap } from "@/api/events";
import { version } from "@/constant";
import { DisTubeError } from "@/errors/DisTubeError";
import { EventJournal } from "@/events/EventJournal";
import type { FilterCatalog } from "@/filters/contracts";
import { MediaResolver } from "@/media/MediaResolver";
import { PlaybackClock } from "@/playback/PlaybackClock";
import type { PreparedPlayback } from "@/plugin";
import { type PluginCollection, PluginGraph } from "@/plugins/PluginGraph";
import type { Queue } from "@/queue/Queue";
import { CleanupPlan } from "@/resources/CleanupPlan";
import {
  compileRuntimeConfiguration,
  type ResolvedRuntimeOptions,
  type RuntimeConfiguration,
} from "@/runtime/RuntimeConfiguration";
import { RuntimeLifecycle } from "@/runtime/RuntimeLifecycle";
import type { MonotonicClock, Scheduler } from "@/runtime/Scheduler";
import { SystemMonotonicClock, SystemScheduler } from "@/runtime/Scheduler";
import { SessionRegistry } from "@/session/SessionRegistry";
import type { GuildIdResolvable } from "@/types/guild";
import type { DisTubeOptions, VoicePlugin } from "@/types/options";
import type { MediaInput, PlayOptions, VoiceJoinOptions } from "@/types/playback";
import type { VoiceSession } from "@/voice/VoiceSession";

interface RuntimeEvents<Metadata, Filters extends FilterCatalog> {
  emit<Event extends keyof DisTubeEventMap<Metadata, Filters>>(
    event: Event,
    ...args: DisTubeEventMap<Metadata, Filters>[Event]
  ): void;
  debug(message: string): void;
}

export interface RuntimeDependencies {
  readonly scheduler?: Scheduler;
  readonly clock?: MonotonicClock;
}

export type { ResolvedRuntimeOptions } from "@/runtime/RuntimeConfiguration";

export class PrivateRuntime<
  Adapter extends ClientAdapter,
  Filters extends FilterCatalog,
  Connection,
  Prepared extends PreparedPlayback,
  SelectedVoice extends VoicePlugin,
  Metadata,
> {
  readonly adapter: Adapter;
  readonly plugins: PluginCollection;
  readonly configuration: RuntimeConfiguration<Adapter, SelectedVoice, Metadata, Filters>;
  readonly options: ResolvedRuntimeOptions<Metadata, Filters>;
  readonly #events: RuntimeEvents<Metadata, Filters>;
  readonly #pluginGraph: PluginGraph<Adapter, Filters, Connection, Prepared, SelectedVoice>;
  readonly #resolver: MediaResolver<Metadata>;
  readonly #sessions: SessionRegistry<Adapter, Metadata, Filters, Connection, Prepared>;
  readonly #journal: EventJournal<Metadata, Filters>;
  readonly #scheduler: Scheduler;
  readonly #lifecycle = new RuntimeLifecycle();
  #destroyPromise?: Promise<void>;

  constructor(
    rawOptions: DisTubeOptions<Adapter, SelectedVoice, Metadata> & {
      readonly voice: SelectedVoice & VoicePlugin<Filters, Connection, Prepared>;
    },
    events: RuntimeEvents<Metadata, Filters>,
    dependencies: RuntimeDependencies = {},
  ) {
    this.#events = events;
    this.configuration = compileRuntimeConfiguration<Adapter, SelectedVoice, Metadata, Filters>(rawOptions);
    this.adapter = this.configuration.adapter;
    this.options = this.configuration;
    this.#pluginGraph = new PluginGraph(
      { ...this.configuration, voice: rawOptions.voice },
      {
        version,
        adapter: this.adapter,
        debug: message => events.debug(message),
      },
    );
    this.plugins = this.#pluginGraph.collection;
    this.#resolver = new MediaResolver(this.#pluginGraph.sources, this.configuration.policies);
    this.#scheduler = dependencies.scheduler ?? new SystemScheduler();
    this.#journal = new EventJournal(this.#scheduler, (event, ...args) => this.#events.emit(event, ...args));
    const clock = dependencies.clock ?? new SystemMonotonicClock();
    this.#sessions = new SessionRegistry((guildId, onIdle) => ({
      guildId,
      adapter: this.adapter,
      voice: this.#pluginGraph.selectedVoiceCapability,
      resolver: this.#resolver,
      queueDefaults: this.options.queueDefaults,
      voiceDefaults: this.options.voiceDefaults,
      filters: this.options.filters,
      journal: this.#journal,
      createPlaybackClock: () => new PlaybackClock(clock),
      onIdle,
    }));
    this.#lifecycle.start(signal => this.#pluginGraph.initialize(signal));
  }

  async ready(): Promise<void> {
    this.#assertUsable();
    await this.#lifecycle.ready();
    this.#assertUsable();
  }

  async play(
    channelValue: unknown,
    input: MediaInput<Metadata>,
    options: PlayOptions<Metadata> = {},
  ): Promise<Queue<Metadata, Filters>> {
    await this.ready();
    const channel = this.#normalizeVoiceChannel(channelValue);
    return this.#sessions.getOrCreate(channel.guildId).play(channel, input, options);
  }

  async join(channelValue: unknown, options: VoiceJoinOptions = {}): Promise<VoiceSession> {
    await this.ready();
    const channel = this.#normalizeVoiceChannel(channelValue);
    return this.#sessions.getOrCreate(channel.guildId).join(channel, options);
  }

  async leave(guild: GuildIdResolvable): Promise<void> {
    await this.ready();
    const id = this.#resolveGuildId(guild);
    const session = this.#sessions.get(id);
    if (!session?.voice) return;
    await session.leave();
  }

  getVoice(guild: GuildIdResolvable): VoiceSession | undefined {
    this.#assertUsable();
    const id = this.adapter.resolveGuildId(guild);
    return id ? this.#sessions.get(id)?.voice : undefined;
  }

  getQueue(guild: GuildIdResolvable): Queue<Metadata, Filters> | undefined {
    this.#assertUsable();
    const id = this.adapter.resolveGuildId(guild);
    return id ? this.#sessions.get(id)?.queue : undefined;
  }

  getQueues(): readonly Queue<Metadata, Filters>[] {
    this.#assertUsable();
    return this.#sessions.queues();
  }

  destroy(): Promise<void> {
    this.#destroyPromise ??= this.#destroy();
    return this.#destroyPromise;
  }

  async #destroy(): Promise<void> {
    this.#lifecycle.beginDestroy();
    const sessions = this.#sessions.sessions();
    for (const session of sessions) session.beginDestroy();
    await this.#awaitInitializationForDestroy();
    const plan = new CleanupPlan(this.#scheduler, this.options.cleanupTimeoutMs);
    for (const session of sessions) for (const unit of session.cleanupUnits()) plan.add(unit);
    for (const unit of this.#pluginGraph.cleanupUnits()) plan.add(unit);
    const result = await plan.run();
    this.#sessions.clear();
    this.#lifecycle.completeDestroy(result.error);
    if (result.error) throw result.error;
  }

  async #awaitInitializationForDestroy(): Promise<void> {
    let timedOut = false;
    let resolveTimeout: () => void = () => {};
    const timeout = new Promise<void>(resolve => {
      resolveTimeout = resolve;
    });
    const scheduled = this.#scheduler.schedule(
      "timeout",
      () => {
        timedOut = true;
        resolveTimeout();
      },
      this.options.cleanupTimeoutMs,
    );
    await Promise.race([this.#lifecycle.settled(), timeout]);
    scheduled.cancel();
    if (timedOut) this.#lifecycle.cancelInitialization();
  }

  #normalizeVoiceChannel(value: unknown): NormalizedVoiceChannel {
    const channel = this.adapter.normalize("voiceChannel", value);
    if (!channel) throw new DisTubeError("INVALID_INPUT", { context: { input: "voiceChannel" } });
    return Object.freeze({ ...channel });
  }

  #resolveGuildId(value: GuildIdResolvable): SnowflakeId {
    const id = this.adapter.resolveGuildId(value);
    if (!id) throw new DisTubeError("INVALID_INPUT", { context: { input: "guild" } });
    return id;
  }

  #assertUsable(): void {
    if (this.#lifecycle.state.kind === "failed") throw this.#lifecycle.state.error;
    if (this.#lifecycle.state.kind === "destroying" || this.#lifecycle.state.kind === "destroyed") {
      throw new DisTubeError("DESTROYED");
    }
  }
}

