import type { ClientAdapter } from "@/adapters/types";
import { DEFAULT_CLEANUP_TIMEOUT_MS, DEFAULT_HISTORY_LIMIT, DEFAULT_VOLUME } from "@/constant";
import { RepeatMode } from "@/enums";
import { DisTubeError } from "@/errors/DisTubeError";
import type { FilterCatalog, FilterDefinition, FilterParameterDefinition } from "@/filters/contracts";
import type { PluginFilters } from "@/plugin";
import type { DisTubeOptions, DisTubePolicies, VoicePlugin } from "@/types/options";

const ROOT_KEYS = [
  "adapter",
  "voice",
  "plugins",
  "queueDefaults",
  "voiceDefaults",
  "policies",
  "cleanupTimeoutMs",
] as const;
const QUEUE_KEYS = ["volume", "autoplay", "repeatMode", "historyLimit"] as const;
const VOICE_KEYS = ["selfDeaf", "selfMute"] as const;
const POLICY_KEYS = ["validateInput", "validateMedia"] as const;
const FILTER_KEYS = ["description", "defaults", "parameters", "validate"] as const;
const PARAMETER_KEYS = ["default", "description", "unit", "min", "max", "validate"] as const;

export interface ResolvedRuntimeOptions<Metadata, Filters extends FilterCatalog> {
  readonly queueDefaults: {
    readonly volume: number;
    readonly autoplay: boolean;
    readonly repeatMode: RepeatMode;
    readonly historyLimit: number;
  };
  readonly voiceDefaults: {
    readonly selfDeaf: boolean;
    readonly selfMute: boolean;
  };
  readonly cleanupTimeoutMs: number;
  readonly policies?: DisTubePolicies<Metadata>;
  readonly filters: Filters;
}

export interface RuntimeConfiguration<
  Adapter extends ClientAdapter,
  SelectedVoice extends VoicePlugin,
  Metadata,
  Filters extends FilterCatalog = PluginFilters<SelectedVoice>,
> extends ResolvedRuntimeOptions<Metadata, Filters> {
  readonly adapter: Adapter;
  readonly voice: SelectedVoice;
  readonly plugins: readonly import("@/plugin").DisTubePlugin[];
}

function configurationError(path: string, reason: string, value?: unknown): DisTubeError<"INVALID_OPTIONS"> {
  return new DisTubeError("INVALID_OPTIONS", { context: { path, reason, value } });
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function assertRecord(value: unknown, path: string): asserts value is Record<string, unknown> {
  if (!isRecord(value)) throw configurationError(path, "expectedObject", value);
}

function rejectUnknownKeys(value: Record<string, unknown>, allowed: readonly string[], path: string): void {
  const key = Object.keys(value).find(candidate => !allowed.includes(candidate));
  if (key) throw configurationError(path ? `${path}.${key}` : key, "unknownKey", value[key]);
}

function optionalBoolean(value: unknown, path: string, fallback: boolean): boolean {
  if (value === undefined) return fallback;
  if (typeof value !== "boolean") throw configurationError(path, "expectedBoolean", value);
  return value;
}

function cloneFrozen<Value>(value: Value, path: string): Value {
  if (Array.isArray(value))
    return Object.freeze(value.map((item, index) => cloneFrozen(item, `${path}[${index}]`))) as Value;
  if (!isRecord(value)) return value;
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) throw configurationError(path, "expectedPlainValue", value);
  return Object.freeze(
    Object.fromEntries(Object.entries(value).map(([key, item]) => [key, cloneFrozen(item, `${path}.${key}`)])),
  ) as Value;
}

function compilePolicies<Metadata>(raw: unknown): DisTubePolicies<Metadata> | undefined {
  if (raw === undefined) return undefined;
  assertRecord(raw, "policies");
  rejectUnknownKeys(raw, POLICY_KEYS, "policies");
  for (const name of POLICY_KEYS) {
    if (raw[name] !== undefined && typeof raw[name] !== "function") {
      throw configurationError(`policies.${name}`, "expectedFunction", raw[name]);
    }
  }
  return Object.freeze({
    validateInput: raw.validateInput as DisTubePolicies<Metadata>["validateInput"],
    validateMedia: raw.validateMedia as DisTubePolicies<Metadata>["validateMedia"],
  });
}

interface CompiledFilterParameter {
  readonly default?: unknown;
  readonly description?: string;
  readonly unit?: string;
  readonly min?: number;
  readonly max?: number;
  readonly validate?: FilterParameterDefinition["validate"];
}

function compileParameter(raw: unknown, path: string): CompiledFilterParameter {
  assertRecord(raw, path);
  rejectUnknownKeys(raw, PARAMETER_KEYS, path);
  if (raw.validate !== undefined && typeof raw.validate !== "function") {
    throw configurationError(`${path}.validate`, "expectedFunction", raw.validate);
  }
  if (raw.min !== undefined && typeof raw.min !== "number")
    throw configurationError(`${path}.min`, "expectedNumber", raw.min);
  if (raw.max !== undefined && typeof raw.max !== "number")
    throw configurationError(`${path}.max`, "expectedNumber", raw.max);
  if (typeof raw.min === "number" && typeof raw.max === "number" && raw.min > raw.max) {
    throw configurationError(path, "minExceedsMax", raw);
  }
  if (typeof raw.default === "number") {
    if (typeof raw.min === "number" && raw.default < raw.min)
      throw configurationError(`${path}.default`, "belowMin", raw.default);
    if (typeof raw.max === "number" && raw.default > raw.max)
      throw configurationError(`${path}.default`, "aboveMax", raw.default);
  }
  return Object.freeze({
    default: cloneFrozen(raw.default, `${path}.default`),
    description: raw.description as string | undefined,
    unit: raw.unit as string | undefined,
    min: raw.min as number | undefined,
    max: raw.max as number | undefined,
    validate: raw.validate as FilterParameterDefinition["validate"],
  });
}

function compileFilter(raw: unknown, path: string): Readonly<FilterDefinition> {
  assertRecord(raw, path);
  rejectUnknownKeys(raw, FILTER_KEYS, path);
  if (raw.description !== undefined && typeof raw.description !== "string") {
    throw configurationError(`${path}.description`, "expectedString", raw.description);
  }
  if (raw.validate !== undefined && typeof raw.validate !== "function") {
    throw configurationError(`${path}.validate`, "expectedFunction", raw.validate);
  }
  if (raw.defaults !== undefined) assertRecord(raw.defaults, `${path}.defaults`);
  if (raw.parameters !== undefined) assertRecord(raw.parameters, `${path}.parameters`);
  const parameters = Object.fromEntries(
    Object.entries(raw.parameters ?? {}).map(([name, parameter]) => [
      name,
      compileParameter(parameter, `${path}.parameters.${name}`),
    ]),
  );
  for (const [name, value] of Object.entries(raw.defaults ?? {})) {
    const parameter = parameters[name];
    if (!parameter) throw configurationError(`${path}.defaults.${name}`, "unknownParameter", value);
    if (typeof value === "number") {
      if (typeof parameter.min === "number" && value < parameter.min) {
        throw configurationError(`${path}.defaults.${name}`, "belowMin", value);
      }
      if (typeof parameter.max === "number" && value > parameter.max) {
        throw configurationError(`${path}.defaults.${name}`, "aboveMax", value);
      }
    }
  }
  return Object.freeze({
    description: raw.description as string | undefined,
    defaults: cloneFrozen(raw.defaults ?? {}, `${path}.defaults`),
    parameters: Object.freeze(parameters) as FilterDefinition["parameters"],
    validate: raw.validate as FilterDefinition["validate"],
  });
}

function compileFilters<Filters extends FilterCatalog>(backend: unknown): Filters {
  const merged: Record<string, unknown> = {};
  if (backend === undefined) return Object.freeze(merged) as Filters;
  assertRecord(backend, "voice.voice.filters");
  for (const [name, definition] of Object.entries(backend)) {
    merged[name] = compileFilter(definition, `voice.voice.filters.${name}`);
  }
  return Object.freeze(merged) as Filters;
}

/** Validate and compile raw construction options before any asynchronous initialization begins. */
export function compileRuntimeConfiguration<
  Adapter extends ClientAdapter,
  SelectedVoice extends VoicePlugin,
  Metadata,
  Filters extends FilterCatalog = PluginFilters<SelectedVoice>,
>(
  raw: DisTubeOptions<Adapter, SelectedVoice, Metadata>,
): RuntimeConfiguration<Adapter, SelectedVoice, Metadata, Filters> {
  assertRecord(raw, "options");
  rejectUnknownKeys(raw, ROOT_KEYS, "");
  assertRecord(raw.queueDefaults ?? {}, "queueDefaults");
  rejectUnknownKeys((raw.queueDefaults ?? {}) as Record<string, unknown>, QUEUE_KEYS, "queueDefaults");
  assertRecord(raw.voiceDefaults ?? {}, "voiceDefaults");
  rejectUnknownKeys((raw.voiceDefaults ?? {}) as Record<string, unknown>, VOICE_KEYS, "voiceDefaults");

  const volume = raw.queueDefaults?.volume ?? DEFAULT_VOLUME;
  const historyLimit = raw.queueDefaults?.historyLimit ?? DEFAULT_HISTORY_LIMIT;
  const cleanupTimeoutMs = raw.cleanupTimeoutMs ?? DEFAULT_CLEANUP_TIMEOUT_MS;
  if (!Number.isInteger(volume) || volume < 0 || volume > 1000) {
    throw configurationError("queueDefaults.volume", "expectedIntegerBetween0And1000", volume);
  }
  if (!Number.isInteger(historyLimit) || historyLimit < 0) {
    throw configurationError("queueDefaults.historyLimit", "expectedNonNegativeInteger", historyLimit);
  }
  if (!Number.isFinite(cleanupTimeoutMs) || cleanupTimeoutMs <= 0) {
    throw configurationError("cleanupTimeoutMs", "expectedPositiveFiniteNumber", cleanupTimeoutMs);
  }
  const repeatMode = raw.queueDefaults?.repeatMode ?? RepeatMode.OFF;
  if (!Object.values(RepeatMode).includes(repeatMode)) {
    throw configurationError("queueDefaults.repeatMode", "unknownRepeatMode", repeatMode);
  }
  if (!raw.adapter) throw configurationError("adapter", "required");
  if (!raw.voice) throw configurationError("voice", "required");
  if (raw.plugins !== undefined && !Array.isArray(raw.plugins))
    throw configurationError("plugins", "expectedArray", raw.plugins);

  return Object.freeze({
    adapter: raw.adapter,
    voice: raw.voice,
    plugins: Object.freeze([...(raw.plugins ?? [])]),
    queueDefaults: Object.freeze({
      volume,
      autoplay: optionalBoolean(raw.queueDefaults?.autoplay, "queueDefaults.autoplay", false),
      repeatMode,
      historyLimit,
    }),
    voiceDefaults: Object.freeze({
      selfDeaf: optionalBoolean(raw.voiceDefaults?.selfDeaf, "voiceDefaults.selfDeaf", true),
      selfMute: optionalBoolean(raw.voiceDefaults?.selfMute, "voiceDefaults.selfMute", false),
    }),
    cleanupTimeoutMs,
    policies: compilePolicies<Metadata>(raw.policies),
    filters: compileFilters<Filters>(raw.voice.voice.filters),
  });
}

