import { normalizeError } from "@/errors/DisTubeError";

export type RuntimeLifecycleState =
  | { readonly kind: "initializing" }
  | { readonly kind: "ready" }
  | { readonly kind: "failed"; readonly error: Error }
  | { readonly kind: "destroying" }
  | { readonly kind: "destroyed"; readonly error?: Error };

/** Explicit runtime readiness/destruction gate with cancellable, safely detached initialization. */
export class RuntimeLifecycle {
  readonly #controller = new AbortController();
  #state: RuntimeLifecycleState = Object.freeze({ kind: "initializing" });
  #initialization?: Promise<void>;

  get state(): RuntimeLifecycleState {
    return this.#state;
  }

  start(initialize: (signal: AbortSignal) => Promise<void>): void {
    if (this.#initialization) throw new Error("Runtime initialization already started");
    this.#initialization = Promise.resolve()
      .then(() => initialize(this.#controller.signal))
      .then(
        () => {
          if (this.#state.kind === "initializing") this.#state = Object.freeze({ kind: "ready" });
        },
        (error: unknown) => {
          if (this.#state.kind === "initializing") {
            this.#state = Object.freeze({ kind: "failed", error: normalizeError(error) });
          }
        },
      );
  }

  async ready(): Promise<void> {
    if (this.#state.kind === "destroying" || this.#state.kind === "destroyed") {
      throw this.#state.kind === "destroyed" && this.#state.error
        ? this.#state.error
        : new Error("Runtime is destroying or destroyed");
    }
    await this.#initialization;
    if (this.#state.kind === "failed") throw this.#state.error;
    if (this.#state.kind !== "ready") throw new Error(`Runtime is ${this.#state.kind}`);
  }

  beginDestroy(): void {
    if (this.#state.kind === "destroying" || this.#state.kind === "destroyed") return;
    this.#state = Object.freeze({ kind: "destroying" });
  }

  cancelInitialization(): void {
    this.#controller.abort(new DOMException("Runtime destruction began.", "AbortError"));
  }

  settled(): Promise<void> {
    return this.#initialization ?? Promise.resolve();
  }

  completeDestroy(error?: Error): void {
    this.#state = Object.freeze({ kind: "destroyed", error });
  }
}

