/** A runtime scheduling phase that tests can drain independently. */
export type SchedulerPhase = "commit" | "publication" | "timeout";

/** A scheduled task that can be cancelled before it begins. */
export interface ScheduledTask {
  readonly cancel: () => void;
}

/**
 * Schedules runtime work without exposing the host event loop to policy-owning modules.
 */
export interface Scheduler {
  schedule(phase: SchedulerPhase, task: () => void, delayMs?: number): ScheduledTask;
}

/** A monotonic time source suitable for durations and playback anchors. */
export interface MonotonicClock {
  now(): number;
}

/** Production monotonic clock backed by the host performance timeline. */
export class SystemMonotonicClock implements MonotonicClock {
  now(): number {
    return performance.now();
  }
}

/** Production scheduler using microtasks for turns and timers only for explicit deadlines. */
export class SystemScheduler implements Scheduler {
  schedule(phase: SchedulerPhase, task: () => void, delayMs = 0): ScheduledTask {
    let cancelled = false;
    if (phase === "timeout" || delayMs > 0) {
      const timer = setTimeout(() => {
        if (!cancelled) task();
      }, delayMs);
      return {
        cancel: () => {
          cancelled = true;
          clearTimeout(timer);
        },
      };
    }
    queueMicrotask(() => {
      if (!cancelled) task();
    });
    return { cancel: () => (cancelled = true) };
  }
}

