import type { ClientAdapter, NormalizedVoiceChannel, SnowflakeId } from "@/adapters/types";
import { QueueDeleteReason, VoiceDisconnectReason } from "@/enums";
import { DisTubeError, normalizeError } from "@/errors/DisTubeError";
import type { EventJournal } from "@/events/EventJournal";
import type { FilterCatalog } from "@/filters/contracts";
import type { MediaResolver } from "@/media/MediaResolver";
import type { Song } from "@/media/Song";
import type { PlaybackClock } from "@/playback/PlaybackClock";
import type { PreparedPlayback, VoiceRuntimeCapability } from "@/plugin";
import type { Queue } from "@/queue/Queue";
import { QueueRuntime } from "@/queue/QueueRuntime";
import { SessionCoordinator } from "@/session/SessionCoordinator";
import { SessionEvents } from "@/session/SessionEvents";
import type { QueueDefaults, VoiceDefaults } from "@/types/options";
import type { MediaInput, PlayOptions, VoiceJoinOptions } from "@/types/playback";
import type { VoiceAggregateTransition } from "@/voice/VoiceAggregate";
import { VoiceRuntime } from "@/voice/VoiceRuntime";
import type { VoiceSession } from "@/voice/VoiceSession";

export interface SessionCleanupUnit {
  readonly name: string;
  readonly run: () => void | Promise<void>;
}

export interface GuildSessionOptions<
  Adapter extends ClientAdapter,
  Metadata,
  Filters extends FilterCatalog,
  Connection,
  Prepared extends PreparedPlayback,
> {
  readonly guildId: SnowflakeId;
  readonly adapter: Adapter;
  readonly voice: VoiceRuntimeCapability<Filters, Connection, Prepared>;
  readonly resolver: MediaResolver<Metadata>;
  readonly queueDefaults: Required<QueueDefaults>;
  readonly voiceDefaults: Required<VoiceDefaults>;
  readonly filters: Filters;
  readonly journal: EventJournal<Metadata, Filters>;
  readonly createPlaybackClock: () => PlaybackClock;
  readonly onIdle: (session: GuildSession<Adapter, Metadata, Filters, Connection, Prepared>) => void;
}

/** Per-guild composition and sole cross-lifetime authority for Queue and Voice Runtime generations. */
export class GuildSession<
  Adapter extends ClientAdapter,
  Metadata,
  Filters extends FilterCatalog,
  Connection,
  Prepared extends PreparedPlayback,
> {
  readonly guildId: SnowflakeId;
  readonly #adapter: Adapter;
  readonly #voiceCapability: VoiceRuntimeCapability<Filters, Connection, Prepared>;
  readonly #resolver: MediaResolver<Metadata>;
  readonly #queueDefaults: Required<QueueDefaults>;
  readonly #voiceDefaults: Required<VoiceDefaults>;
  readonly #filters: Filters;
  readonly #createPlaybackClock: () => PlaybackClock;
  readonly #onIdle: GuildSessionOptions<Adapter, Metadata, Filters, Connection, Prepared>["onIdle"];
  readonly #coordinator = new SessionCoordinator();
  readonly #events: SessionEvents<Metadata, Filters>;
  #queueRuntime?: QueueRuntime<Metadata, Filters, Connection, Prepared>;
  #queueRuntimeGeneration = 0;
  #voiceRuntime?: VoiceRuntime<Adapter, Filters, Connection, Prepared>;
  #voiceRuntimeGeneration = 0;
  #voiceConnectPromise?: Promise<VoiceSession>;
  #destroyPromise?: Promise<void>;
  #destroyed = false;

  constructor(options: GuildSessionOptions<Adapter, Metadata, Filters, Connection, Prepared>) {
    this.guildId = options.guildId;
    this.#adapter = options.adapter;
    this.#voiceCapability = options.voice;
    this.#resolver = options.resolver;
    this.#queueDefaults = options.queueDefaults;
    this.#voiceDefaults = options.voiceDefaults;
    this.#filters = options.filters;
    this.#createPlaybackClock = options.createPlaybackClock;
    this.#onIdle = options.onIdle;
    this.#events = new SessionEvents({
      guildId: options.guildId,
      journal: options.journal,
      isActive: () => !this.#destroyed,
    });
  }

  get queue(): Queue<Metadata, Filters> | undefined {
    return this.#queueRuntime?.active ? this.#queueRuntime.queue : undefined;
  }

  get voice(): VoiceSession | undefined {
    return this.#voiceRuntime?.state === "active" ? this.#voiceRuntime.voice : undefined;
  }

  get isIdle(): boolean {
    return !this.#queueRuntime && !this.#voiceRuntime && !this.#voiceConnectPromise;
  }

  play(
    channel: NormalizedVoiceChannel,
    input: MediaInput<Metadata>,
    options: PlayOptions<Metadata> = {},
  ): Promise<Queue<Metadata, Filters>> {
    this.#assertUsable();
    const voiceReady = this.#connectIfAbsent(channel, options.signal);
    const queueRuntime = this.#queueRuntime ?? this.#createQueue();
    return queueRuntime.play(input, options, voiceReady);
  }

  async join(channel: NormalizedVoiceChannel, options: VoiceJoinOptions = {}): Promise<VoiceSession> {
    this.#assertUsable();
    const slot = this.#coordinator.reserveStructural(options.signal);
    return slot.run(async () => {
      const current = this.#voiceRuntime;
      if (!current) return this.#connectIfAbsent(channel, options.signal, options);
      if (current.voice.channelId === channel.id) return current.voice;
      await current.move(channel, options);
      return current.voice;
    });
  }

  async leave(): Promise<void> {
    this.#assertUsable();
    if (!this.#voiceRuntime && !this.#voiceConnectPromise) throw new DisTubeError("NO_VOICE");
    this.#coordinator.invalidate("queue", "playback", "voice");
    const slot = this.#coordinator.reserveStructural();
    await slot.run(async () => {
      await this.#queueRuntime?.terminate(QueueDeleteReason.VOICE_DISCONNECTED, true);
      const runtime = this.#voiceRuntime;
      if (!runtime) throw new DisTubeError("NO_VOICE");
      await runtime.leave(VoiceDisconnectReason.LEFT);
    });
  }

  beginDestroy(): void {
    if (this.#destroyed) return;
    this.#destroyed = true;
    this.#queueRuntime?.beginDestroy();
    this.#voiceRuntime?.beginDestroy();
    this.#coordinator.destroy();
  }

  destroy(): Promise<void> {
    this.#destroyPromise ??= this.#destroy();
    return this.#destroyPromise;
  }

  cleanupUnits(): readonly SessionCleanupUnit[] {
    this.beginDestroy();
    const prefix = `session:${this.guildId}`;
    const queue = this.#queueRuntime;
    const voice = this.#voiceRuntime;
    return Object.freeze([
      ...(queue?.cleanupUnits(`${prefix}:queue`) ?? []),
      { name: `${prefix}:connection`, run: () => voice?.cleanup() },
      { name: `${prefix}:subscriptions`, run: () => this.#coordinator.destroy() },
      {
        name: `${prefix}:voice`,
        run: () => {
          voice?.destroy();
          if (this.#voiceRuntime === voice) this.#voiceRuntime = undefined;
        },
      },
      { name: `${prefix}:journal`, run: () => {} },
    ]);
  }

  async #destroy(): Promise<void> {
    const errors: Error[] = [];
    for (const unit of this.cleanupUnits()) {
      try {
        await unit.run();
      } catch (error: unknown) {
        errors.push(normalizeError(error));
      }
    }
    if (errors.length > 0) throw new AggregateError(errors, "GuildSession cleanup failed");
  }

  #createQueue(): QueueRuntime<Metadata, Filters, Connection, Prepared> {
    const runtimeGeneration = ++this.#queueRuntimeGeneration;
    const runtime = new QueueRuntime({
      guildId: this.guildId,
      runtimeGeneration,
      voice: this.#voiceCapability,
      voiceAccess: {
        snapshot: () => this.#voiceRuntime?.snapshot,
        connection: () => this.#voiceRuntime?.connection,
        requireConnection: () => {
          const voice = this.#voiceRuntime;
          if (!voice) throw new DisTubeError("NO_VOICE");
          return voice.requireConnection();
        },
      },
      resolver: this.#resolver,
      defaults: this.#queueDefaults,
      filters: this.#filters,
      coordinator: this.#coordinator,
      events: this.#events,
      playbackClock: this.#createPlaybackClock(),
      observer: {
        terminal: generation => {
          if (this.#queueRuntime?.runtimeGeneration !== generation) return;
          this.#queueRuntime = undefined;
          this.#retireIfIdle();
        },
        error: (generation, error, song) => {
          const current = this.#queueRuntime;
          if (!current || current.runtimeGeneration !== generation) return;
          this.#events.error(error, current.queue, song, generation);
        },
      },
    });
    this.#queueRuntime = runtime;
    return runtime;
  }

  #connectIfAbsent(
    channel: NormalizedVoiceChannel,
    callerSignal?: AbortSignal,
    overrides: VoiceJoinOptions = {},
  ): Promise<VoiceSession> {
    if (this.#voiceRuntime?.state === "active") return Promise.resolve(this.#voiceRuntime.voice);
    if (this.#voiceConnectPromise) return this.#voiceConnectPromise;
    const runtimeGeneration = ++this.#voiceRuntimeGeneration;
    const runtime = new VoiceRuntime({
      guildId: this.guildId,
      runtimeGeneration,
      adapter: this.#adapter,
      capability: this.#voiceCapability,
      defaults: this.#voiceDefaults,
      coordinator: this.#coordinator,
      observer: {
        transition: (generation, transition) => this.#applyVoiceTransition(generation, transition),
        disconnect: (generation, reason, error) =>
          this.#runBackground(this.#handleRemoteDisconnect(generation, reason, error)),
        error: (generation, error) => {
          if (this.#voiceRuntime?.runtimeGeneration === generation) {
            this.#events.error(error, this.#queueRuntime?.queue, undefined, generation);
          }
        },
      },
    });
    this.#voiceConnectPromise = (async () => {
      try {
        const transition = await runtime.connect(channel, { ...overrides, signal: callerSignal });
        const record = await this.#coordinator.commit({
          name: "activateVoiceRuntime",
          validate: () => {
            if (this.#voiceRuntime) throw new DisTubeError("VOICE_CONNECTION_FAILED");
          },
          commit: () => {
            if (transition.kind !== "connect") throw new DisTubeError("VOICE_CONNECTION_FAILED");
            this.#voiceRuntime = runtime;
            this.#events.voiceConnect(runtime.voice, transition.newSnapshot, runtimeGeneration);
            return runtime.voice;
          },
        });
        runtime.activateNotifications();
        return record.result;
      } catch (cause: unknown) {
        await runtime.cleanup().catch(() => {});
        throw cause instanceof DisTubeError ? cause : new DisTubeError("VOICE_CONNECTION_FAILED", { cause });
      } finally {
        this.#voiceConnectPromise = undefined;
        this.#retireIfIdle();
      }
    })();
    return this.#voiceConnectPromise;
  }

  #applyVoiceTransition(runtimeGeneration: number, transition: VoiceAggregateTransition): void {
    const runtime = this.#voiceRuntime;
    if (
      !runtime ||
      runtime.runtimeGeneration !== runtimeGeneration ||
      transition.kind === "connect" ||
      !transition.changed
    ) {
      return;
    }
    this.#events.voice(runtime.voice, transition, runtimeGeneration);
    if (transition.kind === "disconnect") {
      this.#voiceRuntime = undefined;
      this.#retireIfIdle();
    }
  }

  async #handleRemoteDisconnect(
    runtimeGeneration: number,
    reason: VoiceDisconnectReason,
    error?: Error,
  ): Promise<void> {
    if (this.#voiceRuntime?.runtimeGeneration !== runtimeGeneration) return;
    this.#coordinator.invalidate("queue", "playback", "voice");
    const slot = this.#coordinator.reserveStructural();
    await slot.run(async () => {
      const runtime = this.#voiceRuntime;
      if (!runtime || runtime.runtimeGeneration !== runtimeGeneration) return;
      if (error)
        this.#events.error(error, this.#queueRuntime?.queue, this.#queueRuntime?.queue.current, runtimeGeneration);
      await this.#queueRuntime?.terminate(QueueDeleteReason.VOICE_DISCONNECTED, true, true);
      await runtime.acceptRemoteDisconnect(reason);
    });
  }

  #runBackground(task: Promise<void>, song?: Song<Metadata>): void {
    void task.catch((error: unknown) => {
      if (this.#destroyed || (error instanceof DOMException && error.name === "AbortError")) return;
      this.#events.error(normalizeError(error), this.#queueRuntime?.queue, song);
    });
  }

  #retireIfIdle(): void {
    if (this.isIdle) this.#onIdle(this);
  }

  #assertUsable(): void {
    if (this.#destroyed) throw new DisTubeError("DESTROYED");
  }
}

