export type CommandOperationScope = "queue" | "voice" | "playback";

export interface CommandOperation {
  readonly signal: AbortSignal;
  readonly scope: CommandOperationScope;
  readonly generation: number;
  isCurrent(): boolean;
  complete(): void;
}

export interface StructuralSlot {
  readonly invocation: number;
  run<Result>(terminal: () => Promise<Result>): Promise<Result>;
  cancel(reason?: unknown): void;
}

export interface SessionTransaction<Result> {
  readonly name: string;
  readonly validate?: () => void;
  readonly commit: () => Result;
}

export interface SessionCommitRecord<Result> {
  readonly sequence: number;
  readonly name: string;
  readonly result: Result;
}

interface OperationRecord {
  readonly controller: AbortController;
  readonly generation: number;
  readonly detachCaller?: () => void;
}

/** Deep per-guild owner of command generations, structural ordering, and synchronous transaction turns. */
export class SessionCoordinator {
  readonly #generations: Record<CommandOperationScope, number> = { queue: 0, voice: 0, playback: 0 };
  readonly #active: Record<CommandOperationScope, Set<OperationRecord>> = {
    queue: new Set(),
    voice: new Set(),
    playback: new Set(),
  };
  #structuralTail: Promise<void> = Promise.resolve();
  #commitTail: Promise<void> = Promise.resolve();
  #invocation = 0;
  #commitSequence = 0;

  begin(scope: CommandOperationScope, callerSignal?: AbortSignal): CommandOperation {
    const controller = new AbortController();
    const generation = this.#generations[scope];
    let detachCaller: (() => void) | undefined;
    if (callerSignal) {
      const abort = (): void => controller.abort(callerSignal.reason);
      if (callerSignal.aborted) abort();
      else {
        callerSignal.addEventListener("abort", abort, { once: true });
        detachCaller = () => callerSignal.removeEventListener("abort", abort);
      }
    }
    const record: OperationRecord = { controller, generation, detachCaller };
    this.#active[scope].add(record);
    let completed = false;
    const complete = (): void => {
      if (completed) return;
      completed = true;
      detachCaller?.();
      this.#active[scope].delete(record);
    };
    return Object.freeze({
      signal: controller.signal,
      scope,
      generation,
      isCurrent: () => !completed && !controller.signal.aborted && this.#generations[scope] === generation,
      complete,
    });
  }

  invalidate(...scopes: readonly CommandOperationScope[]): void {
    for (const scope of scopes) {
      this.#generations[scope] += 1;
      for (const record of this.#active[scope]) {
        record.controller.abort(new DOMException(`The ${scope} operation was superseded.`, "AbortError"));
        record.detachCaller?.();
      }
      this.#active[scope].clear();
    }
  }

  reserveStructural(signal?: AbortSignal): StructuralSlot {
    const invocation = ++this.#invocation;
    const previous = this.#structuralTail;
    let release: () => void = () => {};
    let released = false;
    let cancelled = false;
    let cancelReason: unknown = new DOMException("The structural operation was superseded.", "AbortError");
    this.#structuralTail = new Promise<void>(resolve => {
      release = resolve;
    });
    const releaseOnce = (): void => {
      if (released) return;
      released = true;
      release();
    };
    const cancel = (reason?: unknown): void => {
      cancelled = true;
      cancelReason = reason ?? cancelReason;
      void previous.finally(releaseOnce);
    };
    if (signal) {
      if (signal.aborted) cancel(signal.reason);
      else signal.addEventListener("abort", () => cancel(signal.reason), { once: true });
    }
    return Object.freeze({
      invocation,
      cancel,
      run: async <Result>(terminal: () => Promise<Result>): Promise<Result> => {
        await previous;
        if (cancelled) {
          releaseOnce();
          throw cancelReason;
        }
        try {
          const result = await terminal();
          if (cancelled) throw cancelReason;
          return result;
        } finally {
          releaseOnce();
        }
      },
    });
  }

  commit<Result>(transaction: SessionTransaction<Result>): Promise<SessionCommitRecord<Result>> {
    const previous = this.#commitTail;
    let release: () => void = () => {};
    this.#commitTail = new Promise<void>(resolve => {
      release = resolve;
    });
    return previous.then(() => this.#executeTransaction(transaction)).finally(release);
  }

  commitTerminal<Result>(transaction: SessionTransaction<Result>): SessionCommitRecord<Result> {
    return this.#executeTransaction(transaction);
  }

  destroy(): void {
    this.invalidate("queue", "voice", "playback");
  }

  #executeTransaction<Result>(transaction: SessionTransaction<Result>): SessionCommitRecord<Result> {
    const validation: unknown = transaction.validate?.();
    if (validation instanceof Promise)
      throw new TypeError(`Transaction ${transaction.name} returned asynchronous validation`);
    const result = transaction.commit();
    if (result instanceof Promise) throw new TypeError(`Transaction ${transaction.name} returned asynchronous work`);
    return Object.freeze({ sequence: ++this.#commitSequence, name: transaction.name, result });
  }
}

