import type { SnowflakeId } from "@/adapters/types";
import type { ErrorEventPayload } from "@/api/events";
import type { VoiceSnapshot } from "@/api/snapshots";
import { DisTubeEvent } from "@/enums";
import type { EventCorrelationCategory, EventJournal } from "@/events/EventJournal";
import type { FilterCatalog } from "@/filters/contracts";
import type { Song } from "@/media/Song";
import type { Queue } from "@/queue/Queue";
import type { QueueCommit } from "@/queue/QueueAggregate";
import type { VoiceAggregateTransition } from "@/voice/VoiceAggregate";
import type { VoiceSession } from "@/voice/VoiceSession";

export interface SessionEventsOptions<Metadata, Filters extends FilterCatalog> {
  readonly guildId: SnowflakeId;
  readonly journal: EventJournal<Metadata, Filters>;
  readonly isActive: () => boolean;
}

/** Maps committed aggregate intents and background diagnostics to immutable Event Journal records. */
export class SessionEvents<Metadata, Filters extends FilterCatalog> {
  readonly #guildId: SnowflakeId;
  readonly #journal: EventJournal<Metadata, Filters>;
  readonly #isActive: () => boolean;

  constructor(options: SessionEventsOptions<Metadata, Filters>) {
    this.#guildId = options.guildId;
    this.#journal = options.journal;
    this.#isActive = options.isActive;
  }

  queue<Result>(
    queue: Queue<Metadata, Filters>,
    commit: QueueCommit<Metadata, Filters, Result>,
    generation?: number,
  ): void {
    for (const event of commit.events) {
      switch (event.kind) {
        case "init":
          this.#append(DisTubeEvent.INIT_QUEUE, "command", commit.revision, generation, {
            queue,
            snapshot: commit.newSnapshot,
          });
          break;
        case "addSong":
          this.#append(DisTubeEvent.ADD_SONG, "command", commit.revision, generation, {
            queue,
            snapshot: commit.newSnapshot,
            song: event.song,
            reason: event.reason,
          });
          break;
        case "addPlaylist":
          this.#append(DisTubeEvent.ADD_PLAYLIST, "command", commit.revision, generation, {
            queue,
            snapshot: commit.newSnapshot,
            playlist: event.playlist,
            reason: event.reason,
          });
          break;
        case "playSong":
          this.#append(DisTubeEvent.PLAY_SONG, "playback", commit.revision, generation, {
            queue,
            snapshot: commit.newSnapshot,
            song: event.song,
          });
          break;
        case "finishSong":
          this.#append(DisTubeEvent.FINISH_SONG, "playback", commit.revision, generation, {
            queue,
            snapshot: commit.newSnapshot,
            song: event.song,
          });
          break;
        case "change":
          this.#append(DisTubeEvent.QUEUE_CHANGE, "command", commit.revision, generation, {
            queue,
            reason: event.reason,
            oldSnapshot: commit.oldSnapshot,
            newSnapshot: commit.newSnapshot,
          });
          break;
        case "delete":
          this.#append(DisTubeEvent.DELETE_QUEUE, "lifecycle", commit.revision, generation, {
            queue,
            snapshot: commit.newSnapshot,
            reason: event.reason,
          });
          break;
      }
    }
  }

  voiceConnect(voice: VoiceSession, snapshot: VoiceSnapshot, generation?: number): void {
    this.#append(DisTubeEvent.VOICE_CONNECT, "connection", snapshot.revision, generation, { voice, snapshot });
  }

  voice(voice: VoiceSession, transition: VoiceAggregateTransition, generation?: number): void {
    if (!transition.changed || transition.kind === "connect") return;
    if (transition.kind === "change") {
      this.#append(DisTubeEvent.VOICE_CHANGE, "connection", transition.newSnapshot.revision, generation, {
        voice,
        reason: transition.reason,
        oldSnapshot: transition.oldSnapshot,
        newSnapshot: transition.newSnapshot,
      });
      return;
    }
    this.#append(DisTubeEvent.VOICE_DISCONNECT, "lifecycle", transition.newSnapshot.revision, generation, {
      voice,
      snapshot: transition.newSnapshot,
      reason: transition.reason,
    });
  }

  error(error: Error, queue?: Queue<Metadata, Filters>, song?: Song<Metadata>, generation?: number): void {
    const payload: ErrorEventPayload<Metadata, Filters> = {
      error,
      ...(queue ? { queue, snapshot: queue.snapshot() } : {}),
      ...(song ? { song } : {}),
    };
    this.#append(DisTubeEvent.ERROR, "diagnostic", payload.snapshot?.revision ?? 0, generation, payload);
  }

  debug(message: string, generation?: number): void {
    this.#append(DisTubeEvent.DEBUG, "diagnostic", 0, generation, message);
  }

  #append<Event extends DisTubeEvent>(
    event: Event,
    correlation: EventCorrelationCategory,
    aggregateRevision: number,
    generation: number | undefined,
    ...args: import("@/api/events").DisTubeEventMap<Metadata, Filters>[Event]
  ): void {
    if (!this.#isActive()) return;
    this.#journal.append({
      guildId: this.#guildId,
      event,
      aggregateRevision,
      correlation,
      ...(generation === undefined ? {} : { generation }),
      args,
    });
  }
}

src/session/SessionRegistry.ts.source:
import type { ClientAdapter, SnowflakeId } from "@/adapters/types";
import type { FilterCatalog } from "@/filters/contracts";
import type { PreparedPlayback } from "@/plugin";
import type { Queue } from "@/queue/Queue";
import { GuildSession, type GuildSessionOptions } from "./GuildSession";

export class SessionRegistry<
  Adapter extends ClientAdapter,
  Metadata,
  Filters extends FilterCatalog,
  Connection,
  Prepared extends PreparedPlayback,
> {
  readonly #sessions = new Map<SnowflakeId, GuildSession<Adapter, Metadata, Filters, Connection, Prepared>>();
  readonly #createOptions: (
    guildId: SnowflakeId,
    onIdle: GuildSessionOptions<Adapter, Metadata, Filters, Connection, Prepared>["onIdle"],
  ) => GuildSessionOptions<Adapter, Metadata, Filters, Connection, Prepared>;

  constructor(
    createOptions: (
      guildId: SnowflakeId,
      onIdle: GuildSessionOptions<Adapter, Metadata, Filters, Connection, Prepared>["onIdle"],
    ) => GuildSessionOptions<Adapter, Metadata, Filters, Connection, Prepared>,
  ) {
    this.#createOptions = createOptions;
  }

  get(guildId: SnowflakeId): GuildSession<Adapter, Metadata, Filters, Connection, Prepared> | undefined {
    return this.#sessions.get(guildId);
  }

  getOrCreate(guildId: SnowflakeId): GuildSession<Adapter, Metadata, Filters, Connection, Prepared> {
    const existing = this.#sessions.get(guildId);
    if (existing) return existing;
    const session = new GuildSession(
      this.#createOptions(guildId, candidate => {
        if (candidate.isIdle && this.#sessions.get(guildId) === candidate) this.#sessions.delete(guildId);
      }),
    );
    this.#sessions.set(guildId, session);
    return session;
  }

  queues(): readonly Queue<Metadata, Filters>[] {
    return [...this.#sessions.values()].flatMap(session => (session.queue ? [session.queue] : []));
  }

  sessions(): readonly GuildSession<Adapter, Metadata, Filters, Connection, Prepared>[] {
    return [...this.#sessions.values()];
  }

  clear(): void {
    this.#sessions.clear();
  }
}

src/url/UrlPolicy.ts.source:
import { lookup } from "node:dns/promises";
import { isIP } from "node:net";
import { DisTubeError } from "@/errors/DisTubeError";

export const HTTP_REDIRECT_CODES: ReadonlySet<number> = new Set([301, 302, 303, 307, 308]);
export const MAX_REDIRECT_DEPTH = 10;
const DEFAULT_REQUEST_TIMEOUT_MS = 10_000;
const DEFAULT_PROTOCOLS: readonly string[] = Object.freeze(["https:", "http:", "file:"] as const);

export interface UrlFilterOptions {
  readonly enabled?: boolean;
  readonly allowedProtocols?: readonly string[];
  readonly allowedHostnames?: readonly string[];
  readonly pattern?: RegExp;
  readonly blockLocalAddress?: boolean;
}

export interface ParsedUrl {
  readonly url: URL;
  readonly normalized: string;
}

export type UrlPolicyDecision =
  | { readonly allowed: true; readonly parsed: ParsedUrl }
  | {
      readonly allowed: false;
      readonly reason: "invalid" | "protocol" | "hostname" | "pattern" | "privateAddress";
    };

export type AddressResolver = (hostname: string, signal?: AbortSignal) => Promise<readonly string[]>;

export interface UrlPolicyDependencies {
  readonly resolveAddresses?: AddressResolver;
}

export interface FollowRedirectOptions {
  readonly maxRedirects?: number;
  readonly requestTimeoutMs?: number;
  readonly signal?: AbortSignal;
  readonly policy?: UrlPolicy;
  readonly fetch?: typeof fetch;
}

/** Focused URL safety policy with no media, Queue, plugin, voice, or event dependencies. */
export class UrlPolicy {
  readonly #options: Readonly<Required<Omit<UrlFilterOptions, "pattern">> & Pick<UrlFilterOptions, "pattern">>;
  readonly #resolveAddresses: AddressResolver;

  constructor(options: UrlFilterOptions = {}, dependencies: UrlPolicyDependencies = {}) {
    this.#options = Object.freeze({
      enabled: options.enabled ?? true,
      allowedProtocols: Object.freeze(
        (options.allowedProtocols ?? DEFAULT_PROTOCOLS).map(protocol => protocol.toLowerCase()),
      ),
      allowedHostnames: Object.freeze((options.allowedHostnames ?? []).map(hostname => hostname.toLowerCase())),
      pattern: options.pattern,
      blockLocalAddress: options.blockLocalAddress ?? false,
    });
    this.#resolveAddresses = dependencies.resolveAddresses ?? resolveHostAddresses;
  }

  async evaluate(input: unknown, signal?: AbortSignal): Promise<UrlPolicyDecision> {
    const parsed = parseSupportedUrl(input);
    if (!parsed) return { allowed: false, reason: "invalid" };
    if (!this.#options.enabled) return { allowed: true, parsed };
    if (!this.#options.allowedProtocols.includes(parsed.url.protocol.toLowerCase())) {
      return { allowed: false, reason: "protocol" };
    }
    if (
      this.#options.allowedHostnames.length > 0 &&
      !this.#options.allowedHostnames.some(
        hostname => parsed.url.hostname === hostname || parsed.url.hostname.endsWith(`.${hostname}`),
      )
    ) {
      return { allowed: false, reason: "hostname" };
    }
    if (this.#options.pattern && !this.#options.pattern.test(parsed.normalized)) {
      return { allowed: false, reason: "pattern" };
    }
    if (this.#options.blockLocalAddress) {
      if (parsed.url.protocol === "file:" || isLocalHostname(parsed.url.hostname)) {
        return { allowed: false, reason: "privateAddress" };
      }
      const hostname = parsed.url.hostname.replace(/^\[|\]$/gu, "");
      const addresses = isIP(hostname) ? [hostname] : await this.#resolveAddresses(hostname, signal);
      if (addresses.some(isPrivateAddress)) return { allowed: false, reason: "privateAddress" };
    }
    return { allowed: true, parsed };
  }

  async assertAllowed(input: unknown, signal?: AbortSignal): Promise<ParsedUrl> {
    const result = await this.evaluate(input, signal);
    if (result.allowed) return result.parsed;
    throw new DisTubeError("URL_POLICY_FAILED", {
      context: { url: typeof input === "string" ? input : String(input), reason: result.reason },
    });
  }
}

async function resolveHostAddresses(hostname: string, signal?: AbortSignal): Promise<readonly string[]> {
  signal?.throwIfAborted();
  const addresses = await lookup(hostname, { all: true });
  signal?.throwIfAborted();
  return addresses.map(address => address.address);
}

function parseSupportedUrl(input: unknown): ParsedUrl | undefined {
  if (typeof input !== "string" || input.includes(" ")) return undefined;
  try {
    const url = new URL(input);
    if (!DEFAULT_PROTOCOLS.includes(url.protocol as (typeof DEFAULT_PROTOCOLS)[number])) return undefined;
    return Object.freeze({ url, normalized: url.toString() });
  } catch {
    return undefined;
  }
}

function isLocalHostname(hostname: string): boolean {
  const normalized = hostname.replace(/^\[|\]$/gu, "").toLowerCase();
  return normalized === "localhost" || normalized.endsWith(".localhost");
}

function isPrivateAddress(address: string): boolean {
  const normalized = address.replace(/^\[|\]$/gu, "").toLowerCase();
  if (isIP(normalized) === 4) {
    const [a = 0, b = 0] = normalized.split(".").map(Number);
    return (
      a === 0 ||
      a === 10 ||
      a === 127 ||
      (a === 100 && b >= 64 && b <= 127) ||
      (a === 169 && b === 254) ||
      (a === 172 && b >= 16 && b <= 31) ||
      (a === 192 && b === 168) ||
      (a === 198 && (b === 18 || b === 19)) ||
      a >= 224
    );
  }
  if (isIP(normalized) === 6) {
    if (normalized === "::" || normalized === "::1") return true;
    if (/^(?:fc|fd)/u.test(normalized) || /^fe[89ab]/u.test(normalized)) return true;
    const mapped = /^::ffff:(\d+\.\d+\.\d+\.\d+)$/u.exec(normalized)?.[1];
    if (mapped) return isPrivateAddress(mapped);
    const hexadecimal = /^::ffff:([\da-f]{1,4}):([\da-f]{1,4})$/u.exec(normalized);
    if (hexadecimal) {
      const high = Number.parseInt(hexadecimal[1] ?? "0", 16);
      const low = Number.parseInt(hexadecimal[2] ?? "0", 16);
      return isPrivateAddress(`${high >> 8}.${high & 255}.${low >> 8}.${low & 255}`);
    }
    return false;
  }
  return false;
}

export function isURL(input: unknown): input is `${(typeof DEFAULT_PROTOCOLS)[number]}//${string}` {
  return parseSupportedUrl(input) !== undefined;
}

export function isURLAllowedByFilter(url: string, policy?: UrlFilterOptions): boolean {
  const parsed = parseSupportedUrl(url);
  if (!parsed || !policy?.enabled) return parsed !== undefined;
  const protocols = (policy.allowedProtocols ?? DEFAULT_PROTOCOLS).map(protocol => protocol.toLowerCase());
  if (!protocols.includes(parsed.url.protocol.toLowerCase())) return false;
  if (policy.allowedHostnames?.length) {
    const hostname = parsed.url.hostname.toLowerCase();
    if (!policy.allowedHostnames.some(allowed => hostname === allowed || hostname.endsWith(`.${allowed}`)))
      return false;
  }
  if (policy.pattern && !policy.pattern.test(parsed.normalized)) return false;
  if (policy.blockLocalAddress && (parsed.url.protocol === "file:" || isLocalHostname(parsed.url.hostname)))
    return false;
  if (policy.blockLocalAddress && isIP(parsed.url.hostname) > 0 && isPrivateAddress(parsed.url.hostname)) return false;
  return true;
}

export async function followRedirectLink(url: string, options: FollowRedirectOptions = {}): Promise<string> {
  const maxRedirects = options.maxRedirects ?? MAX_REDIRECT_DEPTH;
  if (!Number.isInteger(maxRedirects) || maxRedirects < 0) {
    throw new DisTubeError("URL_POLICY_FAILED", { context: { url, reason: "redirectLimit", redirects: maxRedirects } });
  }
  const request = options.fetch ?? fetch;
  let current = (await options.policy?.assertAllowed(url, options.signal))?.normalized ?? new URL(url).toString();
  for (let redirects = 0; redirects <= maxRedirects; redirects += 1) {
    options.signal?.throwIfAborted();
    const timeout = AbortSignal.timeout(options.requestTimeoutMs ?? DEFAULT_REQUEST_TIMEOUT_MS);
    const signal = options.signal ? AbortSignal.any([options.signal, timeout]) : timeout;
    let response: Response;
    try {
      response = await request(current, { method: "HEAD", redirect: "manual", signal });
    } catch (cause: unknown) {
      if (options.signal?.aborted) throw options.signal.reason;
      throw new DisTubeError("URL_POLICY_FAILED", { cause, context: { url: current, reason: "request" } });
    }
    if (!HTTP_REDIRECT_CODES.has(response.status)) return current;
    const location = response.headers.get("location");
    if (!location) return current;
    if (redirects === maxRedirects) {
      throw new DisTubeError("URL_POLICY_FAILED", {
        context: { url: current, reason: "redirectLimit", redirects: maxRedirects },
      });
    }
    const next = new URL(location, current).toString();
    current = (await options.policy?.assertAllowed(next, options.signal))?.normalized ?? next;
  }
  return current;
}

export interface ParsedURL<T extends string = string> {
  readonly type: T;
  readonly id: string;
}

export function parseURLWithRegex<T extends string>(
  url: string,
  regex: RegExp,
  supportedTypes: readonly T[],
): ParsedURL<T> | null {
  const match = url.match(regex);
  const type = match?.[1];
  const id = match?.[2];
  if (!type || !id || !supportedTypes.includes(type as T)) return null;
  return Object.freeze({ type: type as T, id });
}

export function validateURLPattern(url: string, hostname: string, regex?: RegExp): boolean {
  const parsed = parseSupportedUrl(url);
  if (!parsed) return false;
  if (parsed.url.hostname !== hostname && !parsed.url.hostname.endsWith(`.${hostname}`)) return false;
  return !regex || regex.test(parsed.normalized);
}

