import type { SnowflakeId } from "@/adapters/types";
import type { VoiceSnapshot } from "@/api/snapshots";
import type { VoiceChangeReason, VoiceDisconnectReason } from "@/enums";

export type VoiceAggregateCommand =
  | {
      readonly type: "connect";
      readonly channelId: SnowflakeId;
      readonly selfMute: boolean;
      readonly selfDeaf: boolean;
    }
  | {
      readonly type: "change";
      readonly reason: VoiceChangeReason;
      readonly channelId?: SnowflakeId;
      readonly selfMute?: boolean;
      readonly selfDeaf?: boolean;
      readonly serverMute?: boolean;
      readonly serverDeaf?: boolean;
      readonly status?: VoiceSnapshot["status"];
    }
  | { readonly type: "disconnect"; readonly reason: VoiceDisconnectReason };

export type VoiceAggregateTransition =
  | {
      readonly kind: "connect";
      readonly changed: true;
      readonly newSnapshot: VoiceSnapshot;
    }
  | {
      readonly kind: "change";
      readonly changed: boolean;
      readonly reason: VoiceChangeReason;
      readonly oldSnapshot: VoiceSnapshot;
      readonly newSnapshot: VoiceSnapshot;
    }
  | {
      readonly kind: "disconnect";
      readonly changed: boolean;
      readonly reason: VoiceDisconnectReason;
      readonly oldSnapshot: VoiceSnapshot;
      readonly newSnapshot: VoiceSnapshot;
    };

/** Pure VoiceSession state and revision authority. */
export class VoiceAggregate {
  readonly #guildId: SnowflakeId;
  #snapshot?: VoiceSnapshot;

  constructor(guildId: SnowflakeId) {
    this.#guildId = guildId;
  }

  snapshot(): VoiceSnapshot | undefined {
    return this.#snapshot;
  }

  execute(command: VoiceAggregateCommand): VoiceAggregateTransition {
    if (command.type === "connect") {
      const snapshot = Object.freeze({
        guildId: this.#guildId,
        revision: 1,
        channelId: command.channelId,
        status: "ready" as const,
        selfMute: command.selfMute,
        selfDeaf: command.selfDeaf,
        serverMute: false,
        serverDeaf: false,
      });
      this.#snapshot = snapshot;
      return Object.freeze({ kind: "connect", changed: true, newSnapshot: snapshot });
    }
    const current = this.#snapshot;
    if (!current) throw new Error("Voice Aggregate is not connected");
    if (command.type === "disconnect") {
      const changed = current.status !== "disconnected";
      const next = changed
        ? Object.freeze({ ...current, revision: current.revision + 1, status: "disconnected" as const })
        : current;
      this.#snapshot = next;
      return Object.freeze({
        kind: "disconnect",
        changed,
        reason: command.reason,
        oldSnapshot: current,
        newSnapshot: next,
      });
    }
    const candidate = {
      ...current,
      channelId: command.channelId ?? current.channelId,
      selfMute: command.selfMute ?? current.selfMute,
      selfDeaf: command.selfDeaf ?? current.selfDeaf,
      serverMute: command.serverMute ?? current.serverMute,
      serverDeaf: command.serverDeaf ?? current.serverDeaf,
      status: command.status ?? current.status,
    };
    const changed =
      candidate.channelId !== current.channelId ||
      candidate.selfMute !== current.selfMute ||
      candidate.selfDeaf !== current.selfDeaf ||
      candidate.serverMute !== current.serverMute ||
      candidate.serverDeaf !== current.serverDeaf ||
      candidate.status !== current.status;
    const next = changed ? Object.freeze({ ...candidate, revision: current.revision + 1 }) : current;
    this.#snapshot = next;
    return Object.freeze({
      kind: "change",
      changed,
      reason: command.reason,
      oldSnapshot: current,
      newSnapshot: next,
    });
  }

  clear(): void {
    this.#snapshot = undefined;
  }
}

src/voice/VoiceManager.ts.source:
import type { GuildIdResolvable } from "@/types/guild";
import type { VoiceJoinOptions } from "@/types/playback";
import type { VoiceSession } from "./VoiceSession";

interface VoiceManagerController {
  join(channel: unknown, options?: VoiceJoinOptions): Promise<VoiceSession>;
  leave(guild: GuildIdResolvable): Promise<void>;
  getVoice(guild: GuildIdResolvable): VoiceSession | undefined;
}

/** Public voice lifecycle entrypoint. */
export class VoiceManager {
  readonly #controller: VoiceManagerController;

  /** @internal */
  constructor(controller: unknown) {
    this.#controller = controller as VoiceManagerController;
  }

  join(channel: unknown, options?: VoiceJoinOptions): Promise<VoiceSession> {
    return this.#controller.join(channel, options);
  }

  leave(guild: GuildIdResolvable): Promise<void> {
    return this.#controller.leave(guild);
  }

  get(guild: GuildIdResolvable): VoiceSession | undefined {
    return this.#controller.getVoice(guild);
  }
}

