import type { ClientAdapter, NormalizedVoiceChannel, SnowflakeId } from "@/adapters/types";
import type { VoiceSnapshot } from "@/api/snapshots";
import { VoiceChangeReason, VoiceDisconnectReason, VoiceFeature } from "@/enums";
import { DisTubeError, normalizeError } from "@/errors/DisTubeError";
import type { FilterCatalog } from "@/filters/contracts";
import type { PreparedPlayback, VoiceLifecycleNotification, VoiceRuntimeCapability } from "@/plugin";
import { ResourceScope } from "@/resources/ResourceScope";
import type { CommandOperation, SessionCoordinator } from "@/session/SessionCoordinator";
import type { VoiceDefaults } from "@/types/options";
import type { VoiceJoinOptions } from "@/types/playback";
import { VoiceAggregate, type VoiceAggregateTransition } from "@/voice/VoiceAggregate";
import { VoiceSession } from "@/voice/VoiceSession";

export type VoiceAcknowledgementPolicy = "command" | "notification" | "correlated-both";

export interface VoiceAcknowledgementPolicies {
  readonly move: VoiceAcknowledgementPolicy;
  readonly selfMute: VoiceAcknowledgementPolicy;
  readonly selfDeaf: VoiceAcknowledgementPolicy;
  readonly remoteLifecycle: VoiceAcknowledgementPolicy;
}

export type VoiceRuntimeLifecycleState = "connecting" | "active" | "terminal";

export interface VoiceRuntimeObserver {
  transition(runtimeGeneration: number, transition: VoiceAggregateTransition): void;
  disconnect(runtimeGeneration: number, reason: VoiceDisconnectReason, error?: Error): void;
  error(runtimeGeneration: number, error: Error): void;
}

export interface VoiceRuntimeOptions<
  Adapter extends ClientAdapter,
  Filters extends FilterCatalog,
  Connection,
  Prepared extends PreparedPlayback,
> {
  readonly guildId: SnowflakeId;
  readonly runtimeGeneration: number;
  readonly adapter: Adapter;
  readonly capability: VoiceRuntimeCapability<Filters, Connection, Prepared>;
  readonly defaults: Required<VoiceDefaults>;
  readonly coordinator: Pick<SessionCoordinator, "begin" | "commit">;
  readonly observer: VoiceRuntimeObserver;
}

interface ConnectionSubscription {
  readonly generation: number;
  readonly controller: AbortController;
  readonly pending: VoiceLifecycleNotification[];
  active: boolean;
}

/** Owns one VoiceSession generation, its aggregate, connection subscription, and connection Resource Scope. */
export class VoiceRuntime<
  Adapter extends ClientAdapter,
  Filters extends FilterCatalog,
  Connection,
  Prepared extends PreparedPlayback,
> {
  readonly acknowledgement: Readonly<VoiceAcknowledgementPolicies> = Object.freeze({
    move: "correlated-both",
    selfMute: "correlated-both",
    selfDeaf: "correlated-both",
    remoteLifecycle: "notification",
  });
  readonly runtimeGeneration: number;
  readonly voice: VoiceSession;
  readonly #adapter: Adapter;
  readonly #capability: VoiceRuntimeCapability<Filters, Connection, Prepared>;
  readonly #defaults: Required<VoiceDefaults>;
  readonly #coordinator: Pick<SessionCoordinator, "begin" | "commit">;
  readonly #observer: VoiceRuntimeObserver;
  readonly #aggregate: VoiceAggregate;
  #state: VoiceRuntimeLifecycleState = "connecting";
  #connection?: Connection;
  #connectionScope?: ResourceScope;
  #subscription?: ConnectionSubscription;
  #subscriptionGeneration = 0;
  #disconnectReported = false;
  #cleanupPromise?: Promise<void>;
  #acceptingCommands = true;

  constructor(options: VoiceRuntimeOptions<Adapter, Filters, Connection, Prepared>) {
    this.runtimeGeneration = options.runtimeGeneration;
    this.#adapter = options.adapter;
    this.#capability = options.capability;
    this.#defaults = options.defaults;
    this.#coordinator = options.coordinator;
    this.#observer = options.observer;
    this.#aggregate = new VoiceAggregate(options.guildId);
    this.voice = new VoiceSession(options.guildId, this);
  }

  get state(): VoiceRuntimeLifecycleState {
    return this.#state;
  }

  get connection(): Connection | undefined {
    return this.#connection;
  }

  get snapshot(): VoiceSnapshot | undefined {
    return this.#aggregate.snapshot();
  }

  getVoiceSnapshot(): VoiceSnapshot {
    const snapshot = this.#aggregate.snapshot();
    if (!snapshot) throw new DisTubeError("NO_VOICE");
    return snapshot;
  }

  async connect(channel: NormalizedVoiceChannel, options: VoiceJoinOptions = {}): Promise<VoiceAggregateTransition> {
    if (this.#state !== "connecting") throw new DisTubeError("VOICE_CONNECTION_FAILED");
    const operation = this.#coordinator.begin("voice", options.signal);
    const subscription = this.#createSubscription();
    let candidateScope: ResourceScope | undefined;
    try {
      const connection = await this.#capability.join({
        adapter: this.#adapter,
        channel,
        selfDeaf: options.selfDeaf ?? this.#defaults.selfDeaf,
        selfMute: options.selfMute ?? this.#defaults.selfMute,
        signal: operation.signal,
        notify: notification => this.#notify(subscription, notification),
      });
      candidateScope = this.#connectionCandidate(connection, subscription.generation);
      this.#assertCurrent(operation);
      const record = await this.#coordinator.commit({
        name: "connectVoice",
        validate: () => {
          this.#assertCurrent(operation);
          if (this.#state !== "connecting") throw new DisTubeError("VOICE_CONNECTION_FAILED");
        },
        commit: () => {
          const transition = this.#aggregate.execute({
            type: "connect",
            channelId: channel.id,
            selfMute: options.selfMute ?? this.#defaults.selfMute,
            selfDeaf: options.selfDeaf ?? this.#defaults.selfDeaf,
          });
          this.#connection = connection;
          this.#connectionScope = candidateScope;
          this.#state = "active";
          this.#promoteSubscription(subscription, false);
          return transition;
        },
      });
      candidateScope = undefined;
      return record.result;
    } catch (cause: unknown) {
      this.#discardSubscription(subscription);
      if (candidateScope) await candidateScope.dispose();
      this.#state = "terminal";
      this.#acceptingCommands = false;
      throw cause instanceof DisTubeError ? cause : new DisTubeError("VOICE_CONNECTION_FAILED", { cause });
    } finally {
      operation.complete();
    }
  }

  activateNotifications(): void {
    const subscription = this.#subscription;
    if (!subscription || subscription.active) return;
    subscription.active = true;
    for (const notification of subscription.pending.splice(0)) this.#acceptNotification(subscription, notification);
  }

  async move(channel: NormalizedVoiceChannel, options: VoiceJoinOptions = {}): Promise<VoiceAggregateTransition> {
    const connection = this.requireConnection();
    const operation = this.#coordinator.begin("voice", options.signal);
    const subscription = this.#createSubscription();
    const snapshot = this.getVoiceSnapshot();
    try {
      await this.#capability.move({
        adapter: this.#adapter,
        channel,
        connection,
        selfDeaf: options.selfDeaf ?? snapshot.selfDeaf,
        selfMute: options.selfMute ?? snapshot.selfMute,
        signal: operation.signal,
        notify: notification => this.#notify(subscription, notification),
      });
      this.#assertCurrent(operation);
      const record = await this.#coordinator.commit({
        name: "moveVoice",
        validate: () => {
          this.#assertCurrent(operation);
          this.#assertActive();
        },
        commit: () => {
          const transition = this.#aggregate.execute({
            type: "change",
            reason: VoiceChangeReason.MOVED,
            channelId: channel.id,
          });
          this.#promoteSubscription(subscription, true);
          return transition;
        },
      });
      this.#observer.transition(this.runtimeGeneration, record.result);
      return record.result;
    } catch (error: unknown) {
      this.#discardSubscription(subscription);
      throw error;
    } finally {
      operation.complete();
    }
  }

  async leave(reason: VoiceDisconnectReason): Promise<VoiceAggregateTransition> {
    this.#assertActive();
    const operation = this.#coordinator.begin("voice");
    try {
      const cleanupErrors = await this.#disposeConnection();
      const record = await this.#coordinator.commit({
        name: "leaveVoice",
        validate: () => {
          if (this.#state !== "active") throw new DisTubeError("NO_VOICE");
        },
        commit: () => this.#terminate(reason),
      });
      this.#observer.transition(this.runtimeGeneration, record.result);
      if (cleanupErrors.length > 0) throw new AggregateError(cleanupErrors, "Voice connection cleanup failed");
      return record.result;
    } finally {
      operation.complete();
    }
  }

  async acceptRemoteDisconnect(reason: VoiceDisconnectReason): Promise<VoiceAggregateTransition | undefined> {
    if (this.#state !== "active") return undefined;
    const cleanupErrors = await this.#disposeConnection();
    const record = await this.#coordinator.commit({
      name: "disconnectVoice",
      validate: () => {
        if (this.#state !== "active") throw new DisTubeError("NO_VOICE");
      },
      commit: () => this.#terminate(reason),
    });
    this.#observer.transition(this.runtimeGeneration, record.result);
    for (const error of cleanupErrors) this.#observer.error(this.runtimeGeneration, error);
    return record.result;
  }

  async setSelfMute(value: boolean, signal?: AbortSignal): Promise<void> {
    if (this.getVoiceSnapshot().selfMute === value) return;
    await this.#control("setSelfMute", VoiceFeature.SELF_MUTE, value, VoiceChangeReason.SELF_MUTE, signal);
  }

  async setSelfDeaf(value: boolean, signal?: AbortSignal): Promise<void> {
    if (this.getVoiceSnapshot().selfDeaf === value) return;
    await this.#control("setSelfDeaf", VoiceFeature.SELF_DEAF, value, VoiceChangeReason.SELF_DEAF, signal);
  }

  requireConnection(): Connection {
    this.#assertActive();
    if (this.#connection === undefined) throw new DisTubeError("NO_VOICE");
    return this.#connection;
  }

  cleanup(): Promise<void> {
    this.#cleanupPromise ??= this.#cleanup();
    return this.#cleanupPromise;
  }

  async #cleanup(): Promise<void> {
    if (this.#state === "terminal") return;
    const errors = await this.#disposeConnection();
    if (this.#aggregate.snapshot()) this.#terminate(VoiceDisconnectReason.LEFT);
    else this.#state = "terminal";
    if (errors.length > 0) throw new AggregateError(errors, "Voice connection cleanup failed");
  }

  destroy(): void {
    this.#abortSubscription();
    if (this.#aggregate.snapshot() && this.#state !== "terminal") this.#terminate(VoiceDisconnectReason.LEFT);
    else this.#state = "terminal";
    this.#connection = undefined;
    this.#connectionScope = undefined;
  }

  beginDestroy(): void {
    this.#acceptingCommands = false;
    this.#abortSubscription();
  }

  async #control(
    methodName: "setSelfMute" | "setSelfDeaf",
    feature: VoiceFeature,
    value: boolean,
    reason: VoiceChangeReason,
    signal?: AbortSignal,
  ): Promise<VoiceAggregateTransition> {
    const method = this.#capability[methodName];
    if (!method) throw new DisTubeError("VOICE_FEATURE_UNSUPPORTED", { context: { feature } });
    const operation = this.#coordinator.begin("voice", signal);
    try {
      await method.call(this.#capability, this.requireConnection(), value, operation.signal);
      this.#assertCurrent(operation);
      const record = await this.#coordinator.commit({
        name: methodName,
        validate: () => {
          this.#assertCurrent(operation);
          this.#assertActive();
        },
        commit: () =>
          this.#aggregate.execute({
            type: "change",
            reason,
            ...(methodName === "setSelfMute" ? { selfMute: value } : { selfDeaf: value }),
          }),
      });
      this.#observer.transition(this.runtimeGeneration, record.result);
      return record.result;
    } finally {
      operation.complete();
    }
  }

  #connectionCandidate(connection: Connection, generation: number): ResourceScope {
    const scope = new ResourceScope(`voice-connection:${this.voice.guildId}:${generation}`);
    scope.register("connection", () => {
      const controller = new AbortController();
      return this.#capability.leave(connection, controller.signal);
    });
    return scope;
  }

  #createSubscription(): ConnectionSubscription {
    return {
      generation: ++this.#subscriptionGeneration,
      controller: new AbortController(),
      pending: [],
      active: false,
    };
  }

  #promoteSubscription(subscription: ConnectionSubscription, active: boolean): void {
    this.#abortSubscription();
    this.#subscription = subscription;
    subscription.active = active;
    if (active) {
      for (const notification of subscription.pending.splice(0)) this.#acceptNotification(subscription, notification);
    }
  }

  #discardSubscription(subscription: ConnectionSubscription): void {
    if (!subscription.controller.signal.aborted) subscription.controller.abort();
    subscription.pending.splice(0);
  }

  #abortSubscription(): void {
    const subscription = this.#subscription;
    this.#subscription = undefined;
    if (!subscription) return;
    this.#discardSubscription(subscription);
  }

  #notify(subscription: ConnectionSubscription, notification: VoiceLifecycleNotification): void {
    if (subscription.controller.signal.aborted) return;
    if (this.#subscription !== subscription) {
      subscription.pending.push(notification);
      return;
    }
    if (!subscription.active) {
      subscription.pending.push(notification);
      return;
    }
    this.#acceptNotification(subscription, notification);
  }

  #acceptNotification(subscription: ConnectionSubscription, notification: VoiceLifecycleNotification): void {
    if (this.#subscription !== subscription || subscription.controller.signal.aborted || this.#state !== "active")
      return;
    if (notification.type === "disconnect") {
      if (this.#disconnectReported) return;
      this.#disconnectReported = true;
      this.#observer.disconnect(this.runtimeGeneration, notification.reason, notification.error);
      return;
    }
    if (notification.type === "error") {
      this.#observer.error(this.runtimeGeneration, notification.error);
      return;
    }
    if (notification.type === "finish") return;
    void this.#coordinator
      .commit({
        name: "voiceNotification",
        validate: () => {
          if (
            this.#subscription !== subscription ||
            subscription.controller.signal.aborted ||
            this.#state !== "active"
          ) {
            throw new DisTubeError("NO_VOICE");
          }
        },
        commit: () =>
          this.#aggregate.execute({
            type: "change",
            reason: notification.reason,
            channelId: notification.channelId,
            selfMute: notification.selfMute,
            selfDeaf: notification.selfDeaf,
            serverMute: notification.serverMute,
            serverDeaf: notification.serverDeaf,
            status:
              notification.reason === VoiceChangeReason.RECONNECTING
                ? "reconnecting"
                : notification.reason === VoiceChangeReason.RECONNECTED
                  ? "ready"
                  : undefined,
          }),
      })
      .then(record => {
        if (record.result.changed) this.#observer.transition(this.runtimeGeneration, record.result);
      })
      .catch((error: unknown) => {
        if (this.#state === "active" && this.#subscription === subscription) {
          this.#observer.error(this.runtimeGeneration, normalizeError(error));
        }
      });
  }

  async #disposeConnection(): Promise<readonly Error[]> {
    this.#abortSubscription();
    const scope = this.#connectionScope;
    this.#connectionScope = undefined;
    this.#connection = undefined;
    if (!scope) return [];
    const result = await scope.dispose();
    return result.errors;
  }

  #terminate(reason: VoiceDisconnectReason): VoiceAggregateTransition {
    const transition = this.#aggregate.execute({ type: "disconnect", reason });
    this.#state = "terminal";
    this.#acceptingCommands = false;
    this.#disconnectReported = true;
    this.#connection = undefined;
    this.#connectionScope = undefined;
    this.#abortSubscription();
    return transition;
  }

  #assertCurrent(operation: CommandOperation): void {
    if (operation.isCurrent()) return;
    throw operation.signal.reason ?? new DOMException("Operation superseded", "AbortError");
  }

  #assertActive(): void {
    if (!this.#acceptingCommands || this.#state !== "active") throw new DisTubeError("NO_VOICE");
  }
}

src/voice/VoiceSession.ts.source:
import type { SnowflakeId } from "@/adapters/types";
import type { VoiceSnapshot } from "@/api/snapshots";

interface VoiceSessionController {
  getVoiceSnapshot(): VoiceSnapshot;
  setSelfMute(selfMute: boolean, signal?: AbortSignal): Promise<void>;
  setSelfDeaf(selfDeaf: boolean, signal?: AbortSignal): Promise<void>;
}

/** Stable public voice handle. Backend connection identity remains private. */
export class VoiceSession {
  readonly guildId: SnowflakeId;
  readonly #controller: VoiceSessionController;

  /** @internal */
  constructor(guildId: SnowflakeId, controller: unknown) {
    this.guildId = guildId;
    this.#controller = controller as VoiceSessionController;
  }

  get revision(): number {
    return this.snapshot().revision;
  }

  get channelId(): SnowflakeId {
    return this.snapshot().channelId;
  }

  get status(): VoiceSnapshot["status"] {
    return this.snapshot().status;
  }

  get selfMute(): boolean {
    return this.snapshot().selfMute;
  }

  get selfDeaf(): boolean {
    return this.snapshot().selfDeaf;
  }

  snapshot(): VoiceSnapshot {
    return this.#controller.getVoiceSnapshot();
  }

  async setSelfMute(selfMute: boolean, signal?: AbortSignal): Promise<this> {
    await this.#controller.setSelfMute(selfMute, signal);
    return this;
  }

  async setSelfDeaf(selfDeaf: boolean, signal?: AbortSignal): Promise<this> {
    await this.#controller.setSelfDeaf(selfDeaf, signal);
    return this;
  }
}

tests/acceptance/media-playback.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import { DisTube, DisTubeEvent, QueueDeleteReason, Song } from "@";
import { DisTubePlugin, type SourceCapability, StreamLease } from "@/plugin";
import { TestAdapter, TestSourcePlugin, TestVoicePlugin, tick, voiceChannel } from "../support";

describe("media discovery and playback preparation", () => {
  it("runs a full resolve pass before searchSong and distinguishes pass from throw", async () => {
    const calls: string[] = [];
    class PassingSource extends DisTubePlugin {
      override readonly id = "passing";
      override readonly source: SourceCapability = {
        resolve: input => {
          calls.push(`first:resolve:${input}`);
          return undefined;
        },
        searchSong: query => {
          calls.push(`first:search:${query}`);
          return undefined;
        },
      };
    }
    class HandlingSource extends DisTubePlugin {
      override readonly id = "handling";
      override readonly source: SourceCapability = {
        resolve: input => {
          calls.push(`second:resolve:${input}`);
          return undefined;
        },
        searchSong: query => {
          calls.push(`second:search:${query}`);
          return new Song({ source: "test", id: query, duration: 1 });
        },
        getStream: song => new StreamLease({ url: `https://cdn.example/${song.id}` }),
      };
    }
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new PassingSource(), new HandlingSource()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);

    await distube.play(voiceChannel, "query");

    expect(calls).toEqual(["first:resolve:query", "second:resolve:query", "first:search:query", "second:search:query"]);
    await distube.destroy();
  });

  it("stops routing on a real provider failure and preserves its cause", async () => {
    const next = vi.fn();
    class FailingSource extends DisTubePlugin {
      override readonly id = "failing";
      override readonly source: SourceCapability = {
        resolve: () => {
          throw new Error("provider");
        },
      };
    }
    class LaterSource extends DisTubePlugin {
      override readonly id = "later";
      override readonly source: SourceCapability = { resolve: next };
    }
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new FailingSource(), new LaterSource()],
    });

    await expect(distube.play(voiceChannel, "https://example.com")).rejects.toMatchObject({
      code: "MEDIA_RESOLUTION_FAILED",
    });
    expect(next).not.toHaveBeenCalled();
    await distube.destroy();
  });

  it("applies reject-only input and media policies without mutating an existing Queue", async () => {
    const source = new TestSourcePlugin();
    let rejectMedia = false;
    const distube = new DisTube<TestAdapter, TestVoicePlugin, { request: string }>({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [source],
      policies: {
        validateInput: input => {
          if (input === "blocked") throw new Error("input blocked");
        },
        validateMedia: () => {
          if (rejectMedia) throw new Error("media blocked");
        },
      },
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "first", { metadata: { request: "one" } });
    const before = queue.snapshot();

    await expect(queue.add("blocked")).rejects.toMatchObject({ code: "POLICY_REJECTED" });
    rejectMedia = true;
    await expect(queue.add("second")).rejects.toMatchObject({ code: "POLICY_REJECTED" });

    const after = queue.snapshot();
    expect({ ...after, currentTime: before.currentTime }).toEqual(before);
    expect(after.currentTime).toBeGreaterThanOrEqual(before.currentTime);
    expect(queue.current?.metadata).toEqual({ request: "one" });
    await distube.destroy();
  });

  it("uses an unvisited fallback source while retaining the original public Song", async () => {
    class SpotifySource extends DisTubePlugin {
      override readonly id = "spotify";
      override readonly source: SourceCapability = {
        resolve: input =>
          input.startsWith("spotify:")
            ? new Song({ source: "spotify", id: input, name: "Original Spotify Song", duration: 200 })
            : undefined,
        getFallbackQuery: song => song.name,
      };
    }
    const voice = new TestVoicePlugin();
    voice.prepareUnsupportedSources.add("spotify");
    const fallback = new TestSourcePlugin();
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice,
      plugins: [new SpotifySource(), fallback],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);

    const queue = await distube.play(voiceChannel, "spotify:track:one");

    expect(queue.current?.source).toBe("spotify");
    expect(queue.current?.id).toBe("spotify:track:one");
    expect(fallback.calls.filter(call => call === "search:Original Spotify Song")).toHaveLength(1);
    expect(voice.calls).toContain("prepare:test:search:Original Spotify Song");
    expect(voice.calls).toContain("play:spotify:spotify:track:one");
    await distube.destroy();
  });

  it("keeps active playback when replacement preparation fails", async () => {
    const source = new TestSourcePlugin();
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [source] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "first");
    await queue.add("second");
    voice.prepareErrors.set("search:second", new Error("prepare failed"));

    await expect(queue.skip()).rejects.toMatchObject({ code: "PLAYBACK_FAILED" });

    expect(queue.current?.id).toBe("search:first");
    expect(voice.calls.filter(call => call === "stop")).toHaveLength(0);
    expect(source.disposed.filter(id => id === "search:first")).toHaveLength(0);
    await distube.destroy();
  });

  it("keeps active playback and disposes the candidate when replacement activation fails", async () => {
    const source = new TestSourcePlugin();
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [source] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "first");
    await queue.add("second");
    voice.playErrors.set("search:second", new Error("activation failed"));

    await expect(queue.skip()).rejects.toMatchObject({ code: "PLAYBACK_FAILED" });

    expect(queue.current?.id).toBe("search:first");
    expect(source.disposed.filter(id => id === "search:second")).toHaveLength(1);
    expect(source.disposed.filter(id => id === "search:first")).toHaveLength(0);
    await distube.destroy();
  });

  it("buffers an immediate synchronous finish until activation is current", async () => {
    const voice = new TestVoicePlugin();
    voice.immediatePlaybackNotification = { type: "finish" };
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [new TestSourcePlugin()] });
    const deletions = vi.fn();
    distube.on(DisTubeEvent.DELETE_QUEUE, deletions);

    const queue = await distube.play(voiceChannel, "first");
    await tick();
    await tick();

    expect(queue.destroyed).toBe(true);
    expect(deletions).toHaveBeenCalledOnce();
    await distube.destroy();
  });

  it("rejects stale finish and error notifications after replacement", async () => {
    const source = new TestSourcePlugin();
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [source] });
    const errors = vi.fn();
    distube.on(DisTubeEvent.ERROR, errors);
    const queue = await distube.play(voiceChannel, "first");
    const staleNotify = voice.playbackNotifies[0];
    await queue.add("second");
    await queue.skip();

    staleNotify?.({ type: "finish" });
    staleNotify?.({ type: "error", error: new Error("stale") });
    await tick();

    expect(queue.current?.id).toBe("search:second");
    expect(errors).not.toHaveBeenCalled();
    expect(source.disposed.filter(id => id === "search:first")).toHaveLength(1);
    await distube.destroy();
  });

  it("disposes leases on navigation, natural finish, and stop", async () => {
    const source = new TestSourcePlugin();
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [source] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "first");
    await queue.add("second");

    await queue.skip();
    expect(source.disposed).toContain("search:first");
    voice.finish();
    await tick();
    await tick();
    expect(source.disposed).toContain("search:second");

    const replacement = await distube.play(voiceChannel, "third");
    await replacement.stop();
    expect(source.disposed).toContain("search:third");
    await distube.destroy();
  });

  it("emits background playback error, discards failed Song, and advances without finishSong", async () => {
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [new TestSourcePlugin()] });
    const errors = vi.fn();
    const finishes = vi.fn();
    distube.on(DisTubeEvent.ERROR, errors);
    distube.on(DisTubeEvent.FINISH_SONG, finishes);
    const queue = await distube.play(voiceChannel, "first");
    await queue.add("second");

    voice.fail();
    await tick();
    await tick();

    expect(errors).toHaveBeenCalledOnce();
    expect(errors.mock.calls[0]?.[0].song?.id).toBe("search:first");
    expect(finishes).not.toHaveBeenCalled();
    expect(queue.current?.id).toBe("search:second");
    await distube.destroy();
  });

  it("discards multiple failed successors in one structural progression", async () => {
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [new TestSourcePlugin()] });
    const errors = vi.fn();
    const deletions = vi.fn();
    distube.on(DisTubeEvent.ERROR, errors);
    distube.on(DisTubeEvent.DELETE_QUEUE, deletions);
    const queue = await distube.play(voiceChannel, "first");
    await queue.add("second");
    await queue.add("third");
    voice.prepareErrors.set("search:second", new Error("second failed"));
    voice.prepareErrors.set("search:third", new Error("third failed"));

    voice.fail(new Error("first failed"));
    await tick();
    await tick();

    expect(errors).toHaveBeenCalledTimes(3);
    expect(errors.mock.calls.map(call => call[0].song.id)).toEqual(["search:first", "search:second", "search:third"]);
    expect(deletions).toHaveBeenCalledOnce();
    expect(deletions.mock.calls[0]?.[0].reason).toBe(QueueDeleteReason.ERROR);
    expect(queue.destroyed).toBe(true);
    await distube.destroy();
  });

  it("distinguishes clean and failed related exhaustion", async () => {
    const source = new TestSourcePlugin();
    const voice = new TestVoicePlugin();
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice,
      plugins: [source],
      queueDefaults: { autoplay: true },
    });
    const errors = vi.fn();
    const deletions: QueueDeleteReason[] = [];
    distube.on(DisTubeEvent.ERROR, errors);
    distube.on(DisTubeEvent.DELETE_QUEUE, payload => deletions.push(payload.reason));

    await distube.play(voiceChannel, "clean");
    voice.finish();
    await tick();
    await tick();
    expect(deletions).toContain(QueueDeleteReason.NO_RELATED);

    source.relatedError = new Error("related provider");
    await distube.play(voiceChannel, "failed");
    voice.finish();
    await tick();
    await tick();
    expect(errors).toHaveBeenCalled();
    expect(deletions).toContain(QueueDeleteReason.ERROR);
    await distube.destroy();
  });
});

tests/acceptance/voice-lifecycle.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import { DisTube, DisTubeEvent, QueueDeleteReason, VoiceChangeReason, VoiceDisconnectReason } from "@";
import { secondVoiceChannel, TestAdapter, TestSourcePlugin, TestVoicePlugin, tick, voiceChannel } from "../support";

describe("Queue and VoiceSession lifecycles", () => {
  it("joins without Queue and explicitly moves while preserving playback", async () => {
    const voicePlugin = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const changes: VoiceChangeReason[] = [];
    distube.on(DisTubeEvent.VOICE_CHANGE, payload => changes.push(payload.reason));

    const voice = await distube.voice.join(voiceChannel);
    expect(distube.getQueue(voiceChannel)).toBeUndefined();
    const queue = await distube.play(voiceChannel, "first");
    const moved = await distube.voice.join(secondVoiceChannel);
    await tick();

    expect(moved).toBe(voice);
    expect(voice.channelId).toBe(secondVoiceChannel.id);
    expect(queue.current?.id).toBe("search:first");
    expect(changes).toContain(VoiceChangeReason.MOVED);
    await distube.destroy();
  });

  it("play never moves an existing connection to its channel argument", async () => {
    const voicePlugin = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const voice = await distube.voice.join(voiceChannel);

    const queue = await distube.play(secondVoiceChannel, "first");

    expect(voice.channelId).toBe(voiceChannel.id);
    expect(queue.current?.id).toBe("search:first");
    expect(voicePlugin.calls).not.toContain(`move:${secondVoiceChannel.id}`);
    await distube.destroy();
  });

  it("stop and natural finish delete Queue but preserve voice without a timer", async () => {
    const voicePlugin = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const deletions: QueueDeleteReason[] = [];
    distube.on(DisTubeEvent.DELETE_QUEUE, payload => deletions.push(payload.reason));
    const first = await distube.play(voiceChannel, "first");

    await first.stop();
    await tick();
    expect(distube.getQueue(voiceChannel)).toBeUndefined();
    expect(distube.voice.get(voiceChannel)).toBeDefined();
    expect(deletions).toContain(QueueDeleteReason.STOPPED);

    await distube.play(secondVoiceChannel, "second");
    voicePlugin.finish();
    await tick();
    await tick();
    expect(distube.getQueue(voiceChannel)).toBeUndefined();
    expect(distube.voice.get(voiceChannel)?.channelId).toBe(voiceChannel.id);
    expect(deletions).toContain(QueueDeleteReason.FINISHED);
    await distube.destroy();
  });

  it("explicit leave deletes Queue and VoiceSession with enumerated reasons", async () => {
    const voicePlugin = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const deleteQueue = vi.fn();
    const disconnect = vi.fn();
    distube.on(DisTubeEvent.DELETE_QUEUE, deleteQueue);
    distube.on(DisTubeEvent.VOICE_DISCONNECT, disconnect);
    await distube.play(voiceChannel, "first");

    await distube.voice.leave(voiceChannel);
    await tick();

    expect(distube.getQueue(voiceChannel)).toBeUndefined();
    expect(distube.voice.get(voiceChannel)).toBeUndefined();
    expect(deleteQueue.mock.calls[0]?.[0].reason).toBe(QueueDeleteReason.VOICE_DISCONNECTED);
    expect(disconnect.mock.calls[0]?.[0].reason).toBe(VoiceDisconnectReason.LEFT);
    const leaveCalls = voicePlugin.calls.filter(call => call.startsWith("leave:")).length;
    await expect(distube.voice.leave(voiceChannel)).resolves.toBeUndefined();
    await tick();
    expect(voicePlugin.calls.filter(call => call.startsWith("leave:"))).toHaveLength(leaveCalls);
    expect(deleteQueue).toHaveBeenCalledTimes(1);
    expect(disconnect).toHaveBeenCalledTimes(1);
    await distube.destroy();
  });

  it("treats leave without an existing guild session as a no-op", async () => {
    const voicePlugin = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin });
    const deleteQueue = vi.fn();
    const disconnect = vi.fn();
    distube.on(DisTubeEvent.DELETE_QUEUE, deleteQueue);
    distube.on(DisTubeEvent.VOICE_DISCONNECT, disconnect);

    await expect(distube.voice.leave(voiceChannel)).resolves.toBeUndefined();

    expect(distube.getQueue(voiceChannel)).toBeUndefined();
    expect(distube.voice.get(voiceChannel)).toBeUndefined();
    expect(voicePlugin.calls.some(call => call.startsWith("leave:"))).toBe(false);
    expect(deleteQueue).not.toHaveBeenCalled();
    expect(disconnect).not.toHaveBeenCalled();
    await distube.destroy();
  });

  it("retains a successful automatic voice connection when play resolution fails", async () => {
    const source = new TestSourcePlugin();
    source.searchError = new Error("provider failed");
    const distube = new DisTube({ adapter: new TestAdapter(), voice: new TestVoicePlugin(), plugins: [source] });

    await expect(distube.play(voiceChannel, "first")).rejects.toBeInstanceOf(Error);

    expect(distube.getQueue(voiceChannel)).toBeUndefined();
    expect(distube.voice.get(voiceChannel)).toBeDefined();
    await distube.destroy();
  });

  it("commits mute/deaf and remote disconnect notifications with reason enums", async () => {
    const voicePlugin = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const changes: VoiceChangeReason[] = [];
    const disconnects: VoiceDisconnectReason[] = [];
    distube.on(DisTubeEvent.VOICE_CHANGE, payload => changes.push(payload.reason));
    distube.on(DisTubeEvent.VOICE_DISCONNECT, payload => disconnects.push(payload.reason));
    const queue = await distube.play(voiceChannel, "first");
    const voice = distube.voice.get(voiceChannel);
    expect(voice).toBeDefined();

    await voice?.setSelfMute(true);
    await voice?.setSelfDeaf(false);
    voicePlugin.remoteDisconnect();
    await tick();
    await tick();

    expect(changes).toContain(VoiceChangeReason.SELF_MUTE);
    expect(disconnects).toContain(VoiceDisconnectReason.REMOTE);
    expect(queue.destroyed).toBe(true);
    expect(distube.voice.get(voiceChannel)).toBeUndefined();
    await distube.destroy();
  });

  it("deduplicates synchronous command notifications into one voice transition", async () => {
    const voicePlugin = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin });
    const changes = vi.fn();
    distube.on(DisTubeEvent.VOICE_CHANGE, changes);
    const voice = await distube.voice.join(voiceChannel);

    await voice.setSelfMute(true);
    await tick();

    expect(voice.selfMute).toBe(true);
    expect(changes.mock.calls.filter(call => call[0].reason === VoiceChangeReason.SELF_MUTE)).toHaveLength(1);
    await distube.destroy();
  });

  it("rejects callbacks from the replaced move subscription generation", async () => {
    const voicePlugin = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin });
    const voice = await distube.voice.join(voiceChannel);
    const staleNotify = voicePlugin.connections.get(voiceChannel.guildId)?.notify;

    await distube.voice.join(secondVoiceChannel);
    staleNotify?.({ type: "change", reason: VoiceChangeReason.MOVED, channelId: voiceChannel.id });
    await tick();

    expect(voice.channelId).toBe(secondVoiceChannel.id);
    await distube.destroy();
  });

  it("accepts current reconnect notifications without changing connection identity", async () => {
    const voicePlugin = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin });
    const voice = await distube.voice.join(voiceChannel);

    voicePlugin.notifyChange({ type: "change", reason: VoiceChangeReason.RECONNECTING });
    await tick();
    expect(voice.status).toBe("reconnecting");
    voicePlugin.notifyChange({ type: "change", reason: VoiceChangeReason.RECONNECTED });
    await tick();

    expect(voice.status).toBe("ready");
    expect(distube.voice.get(voiceChannel)).toBe(voice);
    await distube.destroy();
  });

  it("cancels a pending move without committing its channel", async () => {
    let release: (() => void) | undefined;
    const voicePlugin = new TestVoicePlugin();
    voicePlugin.moveDelay = () => new Promise<void>(resolve => (release = resolve));
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin });
    const voice = await distube.voice.join(voiceChannel);
    const controller = new AbortController();
    const moving = distube.voice.join(secondVoiceChannel, { signal: controller.signal });

    controller.abort(new DOMException("cancelled", "AbortError"));
    release?.();

    await expect(moving).rejects.toMatchObject({ name: "AbortError" });
    expect(voice.channelId).toBe(voiceChannel.id);
    await distube.destroy();
  });

  it("reports an unavailable optional voice control with its exact feature", async () => {
    const voicePlugin = new TestVoicePlugin();
    const { setSelfMute: _unsupported, ...supportedVoice } = voicePlugin.voice;
    Object.defineProperty(voicePlugin, "voice", { value: supportedVoice });
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin });
    const voice = await distube.voice.join(voiceChannel);

    await expect(voice.setSelfMute(true)).rejects.toMatchObject({
      code: "VOICE_FEATURE_UNSUPPORTED",
      context: { feature: "selfMute" },
    });
    await distube.destroy();
  });

  it("isolates a replacement VoiceSession generation without restoring a deleted Queue", async () => {
    const voicePlugin = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const deletedQueue = await distube.play(voiceChannel, "first");
    const original = distube.voice.get(voiceChannel);
    if (!original) throw new Error("Expected the original VoiceSession");

    await distube.voice.leave(voiceChannel);
    const terminalSnapshot = original.snapshot();
    const replacement = await distube.voice.join(secondVoiceChannel);

    expect(replacement).not.toBe(original);
    expect(replacement.channelId).toBe(secondVoiceChannel.id);
    expect(original.snapshot()).toBe(terminalSnapshot);
    expect(original.status).toBe("disconnected");
    await expect(original.setSelfMute(true)).rejects.toMatchObject({ code: "NO_VOICE" });
    expect(replacement.selfMute).toBe(false);
    expect(deletedQueue.destroyed).toBe(true);
    expect(distube.getQueue(voiceChannel)).toBeUndefined();
    await distube.destroy();
  });

  it("publishes Queue deletion before VoiceSession disconnection for a current remote disconnect", async () => {
    const voicePlugin = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: voicePlugin, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const order: string[] = [];
    distube.on(DisTubeEvent.DELETE_QUEUE, payload => order.push(`queue:${payload.reason}`));
    distube.on(DisTubeEvent.VOICE_DISCONNECT, payload => order.push(`voice:${payload.reason}`));
    await distube.play(voiceChannel, "first");

    voicePlugin.remoteDisconnect();
    await tick();
    await tick();

    expect(order).toEqual([`queue:${QueueDeleteReason.VOICE_DISCONNECTED}`, `voice:${VoiceDisconnectReason.REMOTE}`]);
    await distube.destroy();
  });
});

tests/acceptance/queue.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import { DisTube, DisTubeEvent, QueueChangeReason, QueuePlacement, QueueSkipBehavior, RepeatMode, Song } from "@";
import { secondVoiceChannel, TestAdapter, TestSourcePlugin, TestVoicePlugin, tick, voiceChannel } from "../support";

describe("finalized Queue contract", () => {
  it("applies append, next, and one-based numeric placement", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "current");

    await queue.add("append", { placement: QueuePlacement.APPEND });
    await queue.add("next", { placement: QueuePlacement.NEXT });
    await queue.add("second", { placement: 2 });

    expect(queue.upcoming.map(song => song.id)).toEqual(["search:next", "search:second", "search:append"]);
    await expect(queue.add("invalid", { placement: 5 })).rejects.toMatchObject({ code: "NO_SONG_POSITION" });
    await distube.destroy();
  });

  it("uses HISTORY by default for skipped current and supports DISCARD", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "one");

    await queue.add("two", { skip: true });
    expect(queue.current?.id).toBe("search:two");
    expect(queue.history.map(song => song.id)).toEqual(["search:one"]);

    await queue.add("three", { skip: true, skipBehavior: QueueSkipBehavior.DISCARD });
    expect(queue.current?.id).toBe("search:three");
    expect(queue.history.map(song => song.id)).toEqual(["search:one"]);
    await distube.destroy();
  });

  it("sets paused state idempotently and keeps explicit setters idempotent", async () => {
    const voice = new TestVoicePlugin();
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice,
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const reasons: QueueChangeReason[] = [];
    distube.on(DisTubeEvent.QUEUE_CHANGE, payload => reasons.push(payload.reason));
    const queue = await distube.play(voiceChannel, "one");

    await queue.setPaused(true);
    await queue.setPaused(true);
    await queue.setPaused(false);
    await queue.setPaused(false);
    await queue.setVolume(250);
    await queue.setVolume(250);
    await queue.setAutoplay(true);
    await queue.setAutoplay(true);
    await queue.setRepeatMode(RepeatMode.QUEUE);
    await queue.setRepeatMode(RepeatMode.QUEUE);
    await expect(queue.setVolume(1001)).rejects.toMatchObject({ code: "INVALID_INPUT" });
    await tick();

    expect(reasons.filter(reason => reason === QueueChangeReason.VOLUME)).toHaveLength(1);
    expect(reasons.filter(reason => reason === QueueChangeReason.AUTOPLAY)).toHaveLength(1);
    expect(reasons.filter(reason => reason === QueueChangeReason.REPEAT_MODE)).toHaveLength(1);
    expect(reasons.filter(reason => reason === QueueChangeReason.PAUSE)).toHaveLength(1);
    expect(reasons.filter(reason => reason === QueueChangeReason.RESUME)).toHaveLength(1);
    expect(voice.calls.filter(call => call === "pause")).toHaveLength(1);
    expect(voice.calls.filter(call => call === "resume")).toHaveLength(1);
    await distube.destroy();
  });

  it("moves, removes, clears, and shuffles upcoming Songs with zero-based indices", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const reasons: QueueChangeReason[] = [];
    distube.on(DisTubeEvent.QUEUE_CHANGE, payload => reasons.push(payload.reason));
    const queue = await distube.play(voiceChannel, "current");
    await queue.add("one");
    await queue.add("two");
    await queue.add("three");
    const current = queue.current;

    await queue.move(0, 2);
    expect(queue.upcoming.map(song => song.id)).toEqual(["search:two", "search:three", "search:one"]);
    const removed = await queue.remove(1);
    expect(removed.id).toBe("search:three");
    expect(queue.upcoming.map(song => song.id)).toEqual(["search:two", "search:one"]);
    await expect(queue.move(2, 0)).rejects.toMatchObject({ code: "NO_SONG_POSITION" });
    await expect(queue.remove(-1)).rejects.toMatchObject({ code: "NO_SONG_POSITION" });
    const controller = new AbortController();
    const cancelled = new Error("cancelled");
    controller.abort(cancelled);
    await expect(queue.move(0, 1, controller.signal)).rejects.toBe(cancelled);

    const beforeMoveNoop = queue.revision;
    await queue.move(0, 0);
    expect(queue.revision).toBe(beforeMoveNoop);
    await queue.clearUpcoming();
    expect(queue.upcoming).toEqual([]);
    const beforeClearNoop = queue.revision;
    await queue.clearUpcoming();
    expect(queue.revision).toBe(beforeClearNoop);

    await queue.add("one");
    await queue.add("two");
    await queue.add("three");
    const random = vi.spyOn(Math, "random").mockReturnValue(0);
    await queue.shuffle();
    random.mockRestore();
    expect(queue.upcoming.map(song => song.id)).toEqual(["search:two", "search:three", "search:one"]);
    const beforeShuffleNoop = queue.revision;
    const unchangedRandom = vi.spyOn(Math, "random").mockReturnValue(0.999);
    await queue.shuffle();
    unchangedRandom.mockRestore();
    expect(queue.revision).toBe(beforeShuffleNoop);
    expect(queue.current).toBe(current);
    expect(reasons.filter(reason => reason === QueueChangeReason.EDIT)).toHaveLength(4);
    await distube.destroy();
  });

  it("checks optional pause features only for effective state changes", async () => {
    const voice = new TestVoicePlugin();
    const { pause: _pause, resume: _resume, ...withoutPauseControls } = voice.voice;
    Object.defineProperty(voice, "voice", { value: withoutPauseControls });
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "one");

    await expect(queue.setPaused(false)).resolves.toBe(queue);
    await expect(queue.setPaused(true)).rejects.toMatchObject({
      code: "VOICE_FEATURE_UNSUPPORTED",
      context: { feature: "pause" },
    });
    await distube.destroy();
  });

  it("edits a zero-based mutable clone of upcoming atomically", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "current");
    await queue.add("one");
    await queue.add("two");
    const current = queue.current;

    await queue.edit(upcoming => {
      expect(upcoming.map(song => song.id)).toEqual(["search:one", "search:two"]);
      upcoming.reverse();
      upcoming.push(new Song({ source: "custom", id: "three", duration: 1 }));
    });

    expect(queue.current).toBe(current);
    expect(queue.upcoming.map(song => song.id)).toEqual(["search:two", "search:one", "three"]);
    const before = queue.snapshot();
    await expect(
      queue.edit(upcoming => {
        upcoming.push(null as unknown as Song);
      }),
    ).rejects.toMatchObject({ code: "INVALID_INPUT" });
    const after = queue.snapshot();
    expect({ ...after, currentTime: before.currentTime }).toEqual(before);
    expect(after.currentTime).toBeGreaterThanOrEqual(before.currentTime);
    await distube.destroy();
  });

  it("uses one-based jump positions and preserves history for previous", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "one");
    await queue.add("two");
    await queue.add("three");

    const jumped = await queue.jumpTo(3);
    expect(jumped.id).toBe("search:three");
    expect(queue.history.map(song => song.id)).toEqual(["search:one", "search:two"]);
    const previous = await queue.previous();
    expect(previous.id).toBe("search:two");
    expect(queue.upcoming[0]?.id).toBe("search:three");
    await distube.destroy();
  });

  it("applies SONG, QUEUE, and OFF natural progression", async () => {
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "one");
    await queue.add("two");

    await queue.setRepeatMode(RepeatMode.SONG);
    voice.finish();
    await tick();
    await tick();
    expect(queue.current?.id).toBe("search:one");

    await queue.setRepeatMode(RepeatMode.QUEUE);
    voice.finish();
    await tick();
    await tick();
    expect(queue.current?.id).toBe("search:two");
    expect(queue.upcoming[0]?.id).toBe("search:one");

    await queue.setRepeatMode(RepeatMode.OFF);
    voice.finish();
    await tick();
    await tick();
    expect(queue.current?.id).toBe("search:one");
    await distube.destroy();
  });

  it("rejects skip at end and manual addRelated failure without deleting Queue", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "one");

    await expect(queue.skip()).rejects.toMatchObject({ code: "NO_UP_NEXT" });
    await expect(queue.addRelated()).rejects.toMatchObject({ code: "NO_RELATED" });
    expect(distube.getQueue(voiceChannel)).toBe(queue);
    await distube.destroy();
  });

  it("retains final reads on destroyed handles and rejects later mutations", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "one");
    const song = queue.current;

    await queue.stop();

    expect(queue.destroyed).toBe(true);
    expect(queue.current).toBe(song);
    expect(queue.snapshot().destroyed).toBe(true);
    await expect(queue.setPaused(true)).rejects.toMatchObject({ code: "QUEUE_DESTROYED" });
    await distube.destroy();
  });

  it("isolates a replacement Queue generation while retaining the current VoiceSession", async () => {
    const voicePlugin = new TestVoicePlugin();
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: voicePlugin,
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const original = await distube.play(voiceChannel, "original");
    const voice = distube.voice.get(voiceChannel);
    const originalSong = original.current;

    await original.stop();
    const terminalSnapshot = original.snapshot();
    const replacement = await distube.play(secondVoiceChannel, "replacement");

    expect(replacement).not.toBe(original);
    expect(replacement.current?.id).toBe("search:replacement");
    expect(original.snapshot()).toBe(terminalSnapshot);
    expect(original.current).toBe(originalSong);
    expect(original.destroyed).toBe(true);
    await expect(original.setVolume(250)).rejects.toMatchObject({ code: "QUEUE_DESTROYED" });
    expect(replacement.volume).toBe(100);
    expect(distube.voice.get(voiceChannel)).toBe(voice);
    expect(voice?.channelId).toBe(voiceChannel.id);
    expect(voicePlugin.calls).not.toContain(`move:${secondVoiceChannel.id}`);
    await distube.destroy();
  });
});

tests/acceptance/filters.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import { DisTube, DisTubeEvent, QueueChangeReason, VoiceFeature } from "@";
import { TestAdapter, TestSourcePlugin, TestVoicePlugin, tick, voiceChannel } from "../support";

describe("backend-owned typed filters", () => {
  it("supports typed single and atomic batch operations with in-place updates", async () => {
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "one");

    await queue.filters.add("gain", { level: 1, unit: "dB" });
    await queue.filters.add({ gain: { level: 2, unit: "custom-unit" }, speed: { rate: 1.25 } });

    expect(queue.filters.active).toEqual({
      gain: { level: 2, unit: "custom-unit" },
      speed: { rate: 1.25 },
    });
    expect(Object.keys(queue.filters.active)).toEqual(["gain", "speed"]);
    await distube.destroy();
  });

  it("treats inactive removal and empty or identical changes as no-ops", async () => {
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const changes = vi.fn();
    distube.on(DisTubeEvent.QUEUE_CHANGE, changes);
    const queue = await distube.play(voiceChannel, "one");

    await expect(queue.filters.remove("gain")).resolves.toBe(queue.filters);
    expect(voice.appliedFilters).toHaveLength(0);
    expect(changes).not.toHaveBeenCalled();
    await queue.filters.add({});
    expect(voice.appliedFilters).toHaveLength(0);
    await queue.filters.add("gain", { level: 1, unit: "dB" });
    await tick();
    const applications = voice.appliedFilters.length;
    const events = changes.mock.calls.length;
    await queue.filters.add("gain", { level: 1, unit: "dB" });
    expect(voice.appliedFilters).toHaveLength(applications);
    expect(changes).toHaveBeenCalledTimes(events);
    await distube.destroy();
  });

  it("commits only after backend success and preserves old state on failure", async () => {
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const reasons: QueueChangeReason[] = [];
    distube.on(DisTubeEvent.QUEUE_CHANGE, payload => reasons.push(payload.reason));
    const queue = await distube.play(voiceChannel, "one");
    await queue.filters.add("gain", { level: 1, unit: "dB" });
    const before = queue.snapshot();
    voice.filterError = new Error("backend rejected");

    await expect(queue.filters.set({ speed: { rate: 1.5 } })).rejects.toThrow("backend rejected");

    const after = queue.snapshot();
    expect({ ...after, currentTime: before.currentTime }).toEqual(before);
    expect(after.currentTime).toBeGreaterThanOrEqual(before.currentTime);
    expect(reasons.filter(reason => reason === QueueChangeReason.FILTERS)).toHaveLength(1);
    await distube.destroy();
  });

  it("maps missing backend filter support to VoiceFeature.FILTERS", async () => {
    const voice = new TestVoicePlugin();
    Object.defineProperty(voice.voice, "applyFilters", { value: undefined });
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [new TestSourcePlugin()] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "one");

    await expect(queue.filters.add("gain", { level: 1, unit: "dB" })).rejects.toMatchObject({
      code: "VOICE_FEATURE_UNSUPPORTED",
      context: { feature: VoiceFeature.FILTERS },
    });
    await distube.destroy();
  });

  it("serializes concurrent filter mutations by invocation order", async () => {
    const voice = new TestVoicePlugin();
    let releaseFirst: (() => void) | undefined;
    let markStarted: (() => void) | undefined;
    const started = new Promise<void>(resolve => (markStarted = resolve));
    let applications = 0;
    voice.filterDelay = async () => {
      applications += 1;
      markStarted?.();
      if (applications === 1) await new Promise<void>(resolve => (releaseFirst = resolve));
    };
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [new TestSourcePlugin()] });
    const queue = await distube.play(voiceChannel, "one");
    const first = queue.filters.add("gain", { level: 1, unit: "dB" });
    const second = queue.filters.add("speed", { rate: 1.5 });

    await started;
    expect(applications).toBe(1);
    releaseFirst?.();
    await Promise.all([first, second]);

    expect(queue.filters.active).toEqual({ gain: { level: 1, unit: "dB" }, speed: { rate: 1.5 } });
    await distube.destroy();
  });

  it("aborts before backend acknowledgement without committing filter state", async () => {
    const voice = new TestVoicePlugin();
    let release: (() => void) | undefined;
    let markStarted: (() => void) | undefined;
    const started = new Promise<void>(resolve => (markStarted = resolve));
    voice.filterDelay = () =>
      new Promise<void>(resolve => {
        release = resolve;
        markStarted?.();
      });
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [new TestSourcePlugin()] });
    const queue = await distube.play(voiceChannel, "one");
    const controller = new AbortController();
    const mutation = queue.filters.add("gain", { level: 1, unit: "dB" }, controller.signal);

    await started;
    controller.abort(new DOMException("cancelled", "AbortError"));
    release?.();

    await expect(mutation).rejects.toMatchObject({ name: "AbortError" });
    expect(queue.filters.active).toEqual({});
    await distube.destroy();
  });

  it("rebases filter acknowledgement over an independent Queue control revision", async () => {
    const voice = new TestVoicePlugin();
    let release: (() => void) | undefined;
    let markStarted: (() => void) | undefined;
    const started = new Promise<void>(resolve => (markStarted = resolve));
    voice.filterDelay = () =>
      new Promise<void>(resolve => {
        release = resolve;
        markStarted?.();
      });
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [new TestSourcePlugin()] });
    const queue = await distube.play(voiceChannel, "one");
    const mutation = queue.filters.add("gain", { level: 2, unit: "dB" });

    await started;
    await queue.setVolume(42);
    release?.();
    await mutation;

    expect(queue.volume).toBe(42);
    expect(queue.filters.active.gain).toEqual({ level: 2, unit: "dB" });
    await distube.destroy();
  });
});

tests/url/UrlPolicy.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import { DisTubeError } from "@";
import {
  followRedirectLink,
  isURL,
  isURLAllowedByFilter,
  parseURLWithRegex,
  UrlPolicy,
  validateURLPattern,
} from "@/url/UrlPolicy";

describe("UrlPolicy", () => {
  it("parses and filters supported URLs independently", async () => {
    const policy = new UrlPolicy({ allowedProtocols: ["https:"], allowedHostnames: ["example.com"] });
    await expect(policy.evaluate("https://media.example.com/song")).resolves.toMatchObject({ allowed: true });
    await expect(policy.evaluate("http://example.com/song")).resolves.toEqual({ allowed: false, reason: "protocol" });
    await expect(policy.evaluate("https://other.test/song")).resolves.toEqual({
      allowed: false,
      reason: "hostname",
    });
    expect(isURL("https://example.com")).toBe(true);
    expect(isURL("mailto:test@example.com")).toBe(false);
    await expect(policy.evaluate("not a url")).resolves.toEqual({ allowed: false, reason: "invalid" });
    await expect(new UrlPolicy({ enabled: false }).evaluate("file:///tmp/audio")).resolves.toMatchObject({
      allowed: true,
    });
    await expect(new UrlPolicy({ pattern: /allowed/u }).evaluate("https://example.com/denied")).resolves.toEqual({
      allowed: false,
      reason: "pattern",
    });
  });

  it("blocks literal and resolved private addresses", async () => {
    const resolveAddresses = vi.fn(async () => ["10.0.0.1"]);
    const policy = new UrlPolicy({ blockLocalAddress: true }, { resolveAddresses });
    await expect(policy.evaluate("http://127.0.0.1/test")).resolves.toEqual({
      allowed: false,
      reason: "privateAddress",
    });
    await expect(policy.evaluate("https://provider.test/song")).resolves.toEqual({
      allowed: false,
      reason: "privateAddress",
    });
    expect(resolveAddresses).toHaveBeenCalledWith("provider.test", undefined);
  });

  it("covers private IPv4, IPv6, local hostname, and public address boundaries", async () => {
    const policy = new UrlPolicy({ blockLocalAddress: true }, { resolveAddresses: async () => ["8.8.8.8"] });
    for (const address of [
      "0.0.0.0",
      "10.0.0.1",
      "100.64.0.1",
      "169.254.1.1",
      "172.16.0.1",
      "192.168.0.1",
      "198.18.0.1",
      "224.0.0.1",
      "[::1]",
      "[fc00::1]",
      "[fe80::1]",
      "[::ffff:127.0.0.1]",
    ]) {
      await expect(policy.evaluate(`http://${address}/`)).resolves.toEqual({
        allowed: false,
        reason: "privateAddress",
      });
    }
    await expect(policy.evaluate("http://localhost/test")).resolves.toEqual({
      allowed: false,
      reason: "privateAddress",
    });
    await expect(policy.evaluate("file:///tmp/audio")).resolves.toEqual({
      allowed: false,
      reason: "privateAddress",
    });
    await expect(policy.evaluate("https://public.example/test")).resolves.toMatchObject({ allowed: true });
  });

  it("throws a typed policy error", async () => {
    const policy = new UrlPolicy({ allowedProtocols: ["https:"] });
    const error = await policy.assertAllowed("http://example.com").catch(reason => reason);
    expect(error).toBeInstanceOf(DisTubeError);
    expect(error).toMatchObject({ code: "URL_POLICY_FAILED", context: { reason: "protocol" } });
  });
});

describe("URL helpers", () => {
  it("follows bounded redirects and validates every destination", async () => {
    const fetcher = vi
      .fn<typeof fetch>()
      .mockResolvedValueOnce(new Response(null, { status: 302, headers: { location: "/next" } }))
      .mockResolvedValueOnce(new Response(null, { status: 200 }));
    await expect(followRedirectLink("https://example.com/start", { fetch: fetcher })).resolves.toBe(
      "https://example.com/next",
    );
    expect(fetcher).toHaveBeenCalledTimes(2);

    const noLocation = vi.fn<typeof fetch>().mockResolvedValue(new Response(null, { status: 302 }));
    await expect(followRedirectLink("https://example.com/start", { fetch: noLocation })).resolves.toBe(
      "https://example.com/start",
    );
  });

  it("rejects redirect overflow and preserves request causes", async () => {
    const redirect = vi
      .fn<typeof fetch>()
      .mockResolvedValue(new Response(null, { status: 302, headers: { location: "/again" } }));
    await expect(followRedirectLink("https://example.com", { fetch: redirect, maxRedirects: 0 })).rejects.toMatchObject(
      {
        code: "URL_POLICY_FAILED",
        context: { reason: "redirectLimit", redirects: 0 },
      },
    );
    const cause = new Error("network");
    await expect(
      followRedirectLink("https://example.com", { fetch: vi.fn<typeof fetch>().mockRejectedValue(cause) }),
    ).rejects.toMatchObject({ code: "URL_POLICY_FAILED", cause });
    await expect(followRedirectLink("https://example.com", { maxRedirects: -1 })).rejects.toMatchObject({
      context: { reason: "redirectLimit", redirects: -1, url: "https://example.com" },
    });
  });

  it("preserves caller cancellation and applies policy to redirect targets", async () => {
    const controller = new AbortController();
    controller.abort(new Error("cancelled"));
    await expect(
      followRedirectLink("https://example.com", { signal: controller.signal, fetch: vi.fn<typeof fetch>() }),
    ).rejects.toThrow("cancelled");

    const duringRequest = new AbortController();
    const abortingFetch = vi.fn<typeof fetch>().mockImplementation(async () => {
      duringRequest.abort(new Error("during request"));
      throw new DOMException("Aborted", "AbortError");
    });
    await expect(
      followRedirectLink("https://example.com", { signal: duringRequest.signal, fetch: abortingFetch }),
    ).rejects.toThrow("during request");

    const policy = new UrlPolicy({ allowedHostnames: ["example.com"] });
    const redirect = vi
      .fn<typeof fetch>()
      .mockResolvedValue(new Response(null, { status: 302, headers: { location: "https://blocked.test" } }));
    await expect(followRedirectLink("https://example.com", { policy, fetch: redirect })).rejects.toMatchObject({
      code: "URL_POLICY_FAILED",
      context: { reason: "hostname", url: "https://blocked.test/" },
    });
  });

  it("keeps pure regex and hostname helpers deterministic", () => {
    expect(isURLAllowedByFilter("https://example.com/a", { enabled: true, allowedProtocols: ["https:"] })).toBe(true);
    expect(parseURLWithRegex("service:track:42", /service:(track):(\d+)/u, ["track"])).toEqual({
      type: "track",
      id: "42",
    });
    expect(validateURLPattern("https://media.example.com/42", "example.com", /\/42$/u)).toBe(true);
    expect(isURLAllowedByFilter("invalid", { enabled: true })).toBe(false);
    expect(isURLAllowedByFilter("http://example.com", { enabled: true, allowedProtocols: ["https:"] })).toBe(false);
    expect(isURLAllowedByFilter("https://blocked.test", { enabled: true, allowedHostnames: ["example.com"] })).toBe(
      false,
    );
    expect(isURLAllowedByFilter("https://example.com/blocked", { enabled: true, pattern: /allowed/u })).toBe(false);
    expect(isURLAllowedByFilter("file:///tmp/audio", { enabled: true, blockLocalAddress: true })).toBe(false);
    expect(isURLAllowedByFilter("http://10.0.0.1", { enabled: true, blockLocalAddress: true })).toBe(false);
    expect(parseURLWithRegex("missing", /service:(track):(\d+)/u, ["track"])).toBeNull();
    expect(parseURLWithRegex("service:album:42", /service:(album):(\d+)/u, ["track"])).toBeNull();
    expect(validateURLPattern("invalid", "example.com")).toBe(false);
    expect(validateURLPattern("https://other.test", "example.com")).toBe(false);
    expect(validateURLPattern("https://example.com", "example.com")).toBe(true);
  });
});

tests/acceptance/runtime-concurrency.tes.source:
import { describe, expect, it, vi } from "vitest";
import { DisTube, DisTubeEvent } from "@";
import { otherGuildChannel, TestAdapter, TestSourcePlugin, TestVoicePlugin, tick, voiceChannel } from "../support";

function deferred(): { readonly promise: Promise<void>; readonly resolve: () => void } {
  let resolve: () => void = () => {};
  const promise = new Promise<void>(done => {
    resolve = done;
  });
  return { promise, resolve };
}

describe("GuildSession concurrency", () => {
  it("interns one Queue and commits concurrent first plays in invocation order", async () => {
    const source = new TestSourcePlugin();
    const slow = deferred();
    source.searchDelay = query => (query === "slow" ? slow.promise : Promise.resolve());
    const distube = new DisTube({ adapter: new TestAdapter(), voice: new TestVoicePlugin(), plugins: [source] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const initQueue = vi.fn();
    distube.on(DisTubeEvent.INIT_QUEUE, initQueue);

    const first = distube.play(voiceChannel, "slow");
    const second = distube.play(voiceChannel, "fast");
    let secondSettled = false;
    void second.then(() => {
      secondSettled = true;
    });
    await tick();
    expect(secondSettled).toBe(false);

    slow.resolve();
    const [firstQueue, secondQueue] = await Promise.all([first, second]);
    await tick();

    expect(firstQueue).toBe(secondQueue);
    expect(firstQueue.current?.id).toBe("search:slow");
    expect(firstQueue.upcoming.map(song => song.id)).toEqual(["search:fast"]);
    expect(initQueue).toHaveBeenCalledOnce();
    await distube.destroy();
  });

  it("lets independent guilds progress without waiting for each other", async () => {
    const source = new TestSourcePlugin();
    const slow = deferred();
    source.searchDelay = query => (query === "slow" ? slow.promise : Promise.resolve());
    const distube = new DisTube({ adapter: new TestAdapter(), voice: new TestVoicePlugin(), plugins: [source] });
    distube.on(DisTubeEvent.ERROR, () => undefined);

    const firstGuild = distube.play(voiceChannel, "slow");
    const secondGuild = distube.play(otherGuildChannel, "fast");
    const secondQueue = await secondGuild;

    expect(secondQueue.guildId).toBe(otherGuildChannel.guildId);
    expect(secondQueue.current?.id).toBe("search:fast");
    slow.resolve();
    await firstGuild;
    await distube.destroy();
  });

  it("keeps committed-state controls responsive during unrelated resolution", async () => {
    const source = new TestSourcePlugin();
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [source] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "first");
    const slow = deferred();
    source.searchDelay = query => (query === "later" ? slow.promise : Promise.resolve());

    const pendingAdd = queue.add("later");
    await tick();
    await queue.setPaused(true);

    expect(queue.paused).toBe(true);
    expect(voice.calls).toContain("pause");
    slow.resolve();
    await pendingAdd;
    await distube.destroy();
  });

  it("invalidates pending work on stop without poisoning the guild", async () => {
    const source = new TestSourcePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: new TestVoicePlugin(), plugins: [source] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "first");
    const slow = deferred();
    source.searchDelay = query => (query === "later" ? slow.promise : Promise.resolve());
    const pendingAdd = queue.add("later");
    await tick();

    await queue.stop();
    slow.resolve();

    await expect(pendingAdd).rejects.toBeInstanceOf(Error);
    expect(distube.getQueue(voiceChannel)).toBeUndefined();
    const replacement = await distube.play(voiceChannel, "replacement");
    expect(replacement).not.toBe(queue);
    await distube.destroy();
  });

  it("releases structural ordering after a command-time resolution failure", async () => {
    const source = new TestSourcePlugin();
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [source] });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "first");
    source.searchError = new Error("selected provider failed");

    await expect(queue.add("failed")).rejects.toMatchObject({ code: "MEDIA_RESOLUTION_FAILED" });
    source.searchError = undefined;
    await queue.add("second");
    await queue.skip();

    expect(queue.current?.id).toBe("search:second");
    await distube.destroy();
  });
});

tests/session/GuildSession.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import { DisTubeEvent, RepeatMode, VoiceDisconnectReason } from "@/enums";
import { EventJournal } from "@/events/EventJournal";
import { MediaResolver } from "@/media/MediaResolver";
import { PlaybackClock } from "@/playback/PlaybackClock";
import type { PreparedPlayback, VoiceRuntimeCapability } from "@/plugin";
import type { SourceEntry } from "@/plugins/PluginGraph";
import { GuildSession } from "@/session/GuildSession";
import {
  secondVoiceChannel,
  TestAdapter,
  type TestConnection,
  type TestFilters,
  TestSourcePlugin,
  TestVoicePlugin,
  testFilters,
  tick,
  voiceChannel,
} from "../support";
import { DeterministicScheduler } from "../support/DeterministicScheduler";

function deferred(): { readonly promise: Promise<void>; readonly resolve: () => void } {
  let resolve: () => void = () => {};
  const promise = new Promise<void>(done => {
    resolve = done;
  });
  return { promise, resolve };
}

function sessionFixture(
  options: {
    readonly plugin?: TestVoicePlugin;
    readonly capability?: VoiceRuntimeCapability<TestFilters, TestConnection, PreparedPlayback>;
  } = {},
): {
  readonly session: GuildSession<TestAdapter, unknown, TestFilters, TestConnection, PreparedPlayback>;
  readonly plugin: TestVoicePlugin;
  readonly source: TestSourcePlugin;
  readonly scheduler: DeterministicScheduler;
  readonly publish: ReturnType<typeof vi.fn>;
  readonly onIdle: ReturnType<typeof vi.fn>;
} {
  const plugin = options.plugin ?? new TestVoicePlugin();
  const source = new TestSourcePlugin();
  const sourceEntry: SourceEntry = { plugin: source, source: source.source };
  const resolver = new MediaResolver([sourceEntry]);
  const scheduler = new DeterministicScheduler();
  const publish = vi.fn();
  const onIdle = vi.fn();
  const journal = new EventJournal<unknown, TestFilters>(scheduler, publish);
  return {
    plugin,
    source,
    scheduler,
    publish,
    onIdle,
    session: new GuildSession({
      guildId: voiceChannel.guildId,
      adapter: new TestAdapter(),
      voice: options.capability ?? plugin.voice,
      resolver,
      queueDefaults: { volume: 100, autoplay: false, repeatMode: RepeatMode.OFF, historyLimit: 50 },
      voiceDefaults: { selfMute: false, selfDeaf: true },
      filters: testFilters,
      journal,
      createPlaybackClock: () => new PlaybackClock(scheduler.clock),
      onIdle,
    }),
  };
}

describe("GuildSession", () => {
  it("owns independent Queue and Voice generations and retires only after both are gone", async () => {
    const { session, plugin, onIdle } = sessionFixture();

    expect(session.isIdle).toBe(true);
    expect(session.queue).toBeUndefined();
    expect(session.voice).toBeUndefined();

    const voice = await session.join(voiceChannel);
    expect(session.voice).toBe(voice);
    expect(session.isIdle).toBe(false);
    expect(await session.join(voiceChannel)).toBe(voice);
    expect(plugin.calls.filter(call => call.startsWith("join:"))).toHaveLength(1);

    const queue = await session.play(secondVoiceChannel, "first");
    expect(session.queue).toBe(queue);
    expect(session.voice).toBe(voice);
    expect(plugin.calls.filter(call => call.startsWith("move:"))).toHaveLength(0);

    await queue.stop();
    expect(session.queue).toBeUndefined();
    expect(session.voice).toBe(voice);
    expect(onIdle).not.toHaveBeenCalled();

    await session.leave();
    expect(session.queue).toBeUndefined();
    expect(session.voice).toBeUndefined();
    expect(session.isIdle).toBe(true);
    expect(onIdle).toHaveBeenCalledWith(session);
    await expect(session.leave()).rejects.toMatchObject({ code: "NO_VOICE" });
  });

  it("shares one pending voice connection across concurrent first plays", async () => {
    const plugin = new TestVoicePlugin();
    const release = deferred();
    const join = vi.fn(async request => {
      await release.promise;
      return plugin.voice.join(request);
    });
    const { session } = sessionFixture({ plugin, capability: { ...plugin.voice, join } });

    const first = session.play(voiceChannel, "first");
    const second = session.play(voiceChannel, "second");
    await Promise.resolve();
    expect(join).toHaveBeenCalledOnce();

    release.resolve();
    const [firstQueue, secondQueue] = await Promise.all([first, second]);

    expect(secondQueue).toBe(firstQueue);
    expect(session.voice?.channelId).toBe(voiceChannel.id);
    expect(firstQueue.current?.id).toBe("search:first");
    expect(firstQueue.snapshot().upcoming.map(song => song.id)).toEqual(["search:second"]);
    await session.destroy();
  });

  it("exposes flat frozen cleanup units and aggregates connection failure while continuing terminal cleanup", async () => {
    const plugin = new TestVoicePlugin();
    const failure = new Error("connection cleanup failed");
    const { session } = sessionFixture({
      plugin,
      capability: {
        ...plugin.voice,
        leave: () => Promise.reject(failure),
      },
    });
    await session.join(voiceChannel);

    const units = session.cleanupUnits();
    expect(Object.isFrozen(units)).toBe(true);
    expect(units.map(unit => unit.name)).toEqual([
      `session:${voiceChannel.guildId}:connection`,
      `session:${voiceChannel.guildId}:subscriptions`,
      `session:${voiceChannel.guildId}:voice`,
      `session:${voiceChannel.guildId}:journal`,
    ]);

    const first = session.destroy();
    const second = session.destroy();
    expect(second).toBe(first);
    const error = await first.catch(cause => cause);
    expect(error).toBeInstanceOf(AggregateError);
    expect(error).toMatchObject({ message: "GuildSession cleanup failed" });
    expect((error as AggregateError).errors).toHaveLength(1);
    expect((error as AggregateError).errors[0]).toEqual(
      new AggregateError([failure], "Voice connection cleanup failed"),
    );
    expect(session.voice).toBeUndefined();
    expect(session.isIdle).toBe(true);
  });

  it("rejects work after destruction and ignores stale callbacks from a replaced Voice generation", async () => {
    const { session, plugin, onIdle, publish, scheduler } = sessionFixture();
    const firstVoice = await session.join(voiceChannel);
    const staleNotify = plugin.connections.get(voiceChannel.guildId)?.notify;
    await session.leave();
    const replacement = await session.join(secondVoiceChannel);

    staleNotify?.({ type: "disconnect", reason: VoiceDisconnectReason.REMOTE, error: new Error("stale") });
    await tick();
    expect(session.voice).toBe(replacement);
    expect(session.voice).not.toBe(firstVoice);

    session.beginDestroy();
    session.beginDestroy();
    expect(() => session.play(voiceChannel, "late")).toThrowError(expect.objectContaining({ code: "DESTROYED" }));
    await expect(session.join(voiceChannel)).rejects.toMatchObject({ code: "DESTROYED" });
    await expect(session.leave()).rejects.toMatchObject({ code: "DESTROYED" });
    await expect(session.destroy()).resolves.toBeUndefined();

    scheduler.drain("publication");
    expect(publish.mock.calls.some(call => call[0] === DisTubeEvent.ERROR)).toBe(false);
    expect(onIdle).toHaveBeenCalled();
  });
});

tests/aggregates/QueueAggregate.test.ts.source:
import fc from "fast-check";
import { describe, expect, it } from "vitest";
import type { VoiceSnapshot } from "@/api/snapshots";
import {
  QueueAddReason,
  QueueChangeReason,
  QueueDeleteReason,
  QueuePlacement,
  QueueSkipBehavior,
  RepeatMode,
} from "@/enums";
import type { EmptyFilterCatalog } from "@/filters/contracts";
import { Playlist } from "@/media/Playlist";
import { Song } from "@/media/Song";
import { QueueAggregate, type QueueCommand } from "@/queue/QueueAggregate";
import { type ReferenceQueueCommand, ReferenceQueueModel } from "../models/ReferenceQueueModel";

const guildId = "100000000000000001";
const filters = Object.freeze({}) as EmptyFilterCatalog;

function song(id: string): Song {
  return new Song({ source: "test", id, name: id, duration: 10 });
}

function aggregate(historyLimit = 2): QueueAggregate<unknown, EmptyFilterCatalog> {
  return new QueueAggregate({
    guildId,
    historyLimit,
    repeatMode: RepeatMode.OFF,
    autoplay: false,
    volume: 100,
    filters,
  });
}

function add(
  media: Song | Playlist,
  overrides: Partial<Extract<QueueCommand<unknown, EmptyFilterCatalog>, { type: "add" }>> = {},
): Extract<QueueCommand<unknown, EmptyFilterCatalog>, { type: "add" }> {
  return {
    type: "add",
    media,
    reason: QueueAddReason.PLAY,
    placement: QueuePlacement.APPEND,
    replace: false,
    skipBehavior: QueueSkipBehavior.HISTORY,
    ...overrides,
  };
}

describe("QueueAggregate structural transitions", () => {
  it("owns placement, current/upcoming ordering, and event/playback intents", () => {
    const queue = aggregate();
    const first = song("first");
    const second = song("second");
    const third = song("third");
    const initial = queue.execute<Song>(add(Playlist.from([first, second])));
    expect(initial.newSnapshot.current).toBe(first);
    expect(initial.newSnapshot.upcoming).toEqual([second]);
    expect(initial.events.map(event => event.kind)).toEqual(["init", "addPlaylist", "playSong"]);
    expect(initial.playback).toEqual({ kind: "activate", song: first });

    queue.execute(add(third, { placement: QueuePlacement.NEXT }));
    expect(queue.snapshot().upcoming).toEqual([third, second]);
    queue.execute(add(song("middle"), { placement: 2 }));
    expect(queue.snapshot().upcoming.map(item => item.id)).toEqual(["third", "middle", "second"]);
    expect(() => queue.plan(add(song("invalid"), { placement: 99 }))).toThrowError(
      expect.objectContaining({ code: "NO_SONG_POSITION" }),
    );
  });

  it("bounds history and implements skip, previous, and jump", () => {
    const queue = aggregate(2);
    const songs = [song("one"), song("two"), song("three"), song("four")];
    queue.execute(add(Playlist.from(songs)));
    expect(queue.execute<Song>({ type: "skip" }).result).toBe(songs[1]);
    expect(queue.execute<Song>({ type: "skip" }).result).toBe(songs[2]);
    expect(queue.execute<Song>({ type: "skip" }).result).toBe(songs[3]);
    expect(queue.snapshot().history).toEqual([songs[1], songs[2]]);
    expect(queue.execute<Song>({ type: "previous" }).result).toBe(songs[2]);
    expect(queue.snapshot().upcoming).toEqual([songs[3]]);

    queue.execute(add(Playlist.from([song("five"), song("six")])));
    const jumped = queue.execute<Song>({ type: "jump", position: 4 });
    expect(jumped.result.id).toBe("six");
    expect(jumped.events[0]).toEqual({ kind: "change", reason: QueueChangeReason.JUMP });
    expect(() => queue.plan({ type: "jump", position: 99 })).toThrowError(
      expect.objectContaining({ code: "NO_SONG_POSITION" }),
    );
  });

  it("replaces current media with history or discard semantics", () => {
    const queue = aggregate();
    const first = song("first");
    const replacement = song("replacement");
    queue.execute(add(first));
    queue.execute(add(replacement, { replace: true }));
    expect(queue.snapshot().history).toEqual([first]);
    const discarded = song("discarded");
    queue.execute(add(discarded, { replace: true, skipBehavior: QueueSkipBehavior.DISCARD }));
    expect(queue.snapshot().history).toEqual([first]);
  });
});

describe("QueueAggregate controls and projections", () => {
  it("commits setters, edit, filters, no-ops, and independent Voice projection", () => {
    const queue = aggregate();
    const first = song("first");
    queue.execute(add(Playlist.from([first, song("second")])));
    const voice: VoiceSnapshot = Object.freeze({
      guildId,
      revision: 3,
      channelId: "200000000000000001",
      status: "ready",
      selfMute: false,
      selfDeaf: true,
      serverMute: false,
      serverDeaf: false,
    });
    const beforeNoop = queue.revision;
    expect(queue.execute({ type: "setVolume", volume: 100 }, voice).revision).toBe(beforeNoop);
    expect(queue.execute({ type: "setVolume", volume: 250 }, voice).newSnapshot).toMatchObject({ volume: 250, voice });
    queue.execute({ type: "setAutoplay", autoplay: true });
    queue.execute({ type: "setRepeatMode", repeatMode: RepeatMode.QUEUE });
    const paused = queue.execute({ type: "setPaused", paused: true });
    expect(paused.events).toEqual([{ kind: "change", reason: QueueChangeReason.PAUSE }]);
    expect(paused.playback).toEqual({ kind: "pause" });
    queue.execute({ type: "seek", time: 5 });
    const beforePausedNoop = queue.revision;
    expect(queue.execute({ type: "setPaused", paused: true }).revision).toBe(beforePausedNoop);
    const resumed = queue.execute({ type: "setPaused", paused: false });
    expect(resumed.events).toEqual([{ kind: "change", reason: QueueChangeReason.RESUME }]);
    expect(resumed.playback).toEqual({ kind: "resume" });
    queue.execute({ type: "edit", upcoming: [song("edited")] });
    queue.execute({ type: "setFilters", filters });
    expect(queue.snapshot()).toMatchObject({
      autoplay: true,
      repeatMode: RepeatMode.QUEUE,
      paused: false,
      currentTime: 5,
      volume: 250,
    });
    expect(queue.snapshot().upcoming[0]?.id).toBe("edited");
    expect(() => queue.plan({ type: "setPaused", paused: true })).not.toThrow();
  });

  it("moves, removes, clears, and validates shuffled upcoming Songs", () => {
    const queue = aggregate();
    const [current, first, second, third] = [song("current"), song("first"), song("second"), song("third")];
    queue.execute(add(Playlist.from([current, first, second, third])));

    const moved = queue.execute({ type: "moveUpcoming", fromIndex: 0, toIndex: 2 });
    expect(moved.newSnapshot.upcoming).toEqual([second, third, first]);
    expect(moved.events).toEqual([{ kind: "change", reason: QueueChangeReason.EDIT }]);
    queue.execute({ type: "moveUpcoming", fromIndex: 2, toIndex: 0 });
    expect(queue.snapshot().upcoming).toEqual([first, second, third]);

    const beforeMoveNoop = queue.revision;
    expect(queue.execute({ type: "moveUpcoming", fromIndex: 1, toIndex: 1 }).revision).toBe(beforeMoveNoop);

    const removed = queue.execute<Song>({ type: "removeUpcoming", index: 1 });
    expect(removed.result).toBe(second);
    expect(removed.newSnapshot.upcoming).toEqual([first, third]);
    expect(removed.events).toEqual([{ kind: "change", reason: QueueChangeReason.EDIT }]);

    const shuffled = queue.execute({ type: "shuffleUpcoming", upcoming: [third, first] });
    expect(shuffled.newSnapshot.upcoming).toEqual([third, first]);
    expect(shuffled.events).toEqual([{ kind: "change", reason: QueueChangeReason.EDIT }]);
    const beforeShuffleNoop = queue.revision;
    expect(queue.execute({ type: "shuffleUpcoming", upcoming: [third, first] }).revision).toBe(beforeShuffleNoop);
    expect(() => queue.plan({ type: "shuffleUpcoming", upcoming: [first, first] })).toThrowError(
      expect.objectContaining({ code: "INVALID_INPUT" }),
    );

    const cleared = queue.execute({ type: "clearUpcoming" });
    expect(cleared.newSnapshot.upcoming).toEqual([]);
    expect(cleared.events).toEqual([{ kind: "change", reason: QueueChangeReason.EDIT }]);
    const beforeClearNoop = queue.revision;
    expect(queue.execute({ type: "clearUpcoming" }).revision).toBe(beforeClearNoop);

    expect(() => queue.plan({ type: "moveUpcoming", fromIndex: 0, toIndex: 0 })).toThrowError(
      expect.objectContaining({ code: "NO_SONG_POSITION" }),
    );
    expect(() => queue.plan({ type: "removeUpcoming", index: -1 })).toThrowError(
      expect.objectContaining({ code: "NO_SONG_POSITION" }),
    );
  });

  it("validates controls and edit candidates", () => {
    const queue = aggregate();
    expect(() => queue.plan({ type: "seek", time: -1 })).toThrowError(
      expect.objectContaining({ code: "INVALID_INPUT" }),
    );
    expect(() => queue.plan({ type: "setVolume", volume: 1001 })).toThrowError(
      expect.objectContaining({ code: "INVALID_INPUT" }),
    );
    expect(() => queue.plan({ type: "edit", upcoming: [{} as Song] })).toThrowError(
      expect.objectContaining({ code: "INVALID_INPUT" }),
    );
    expect(() => queue.plan({ type: "skip" })).toThrowError(expect.objectContaining({ code: "NO_UP_NEXT" }));
    expect(() => queue.plan({ type: "previous" })).toThrowError(expect.objectContaining({ code: "NO_PREVIOUS" }));
  });
});

describe("QueueAggregate progression and conflicts", () => {
  it("models repeat, finish, autoplay request, successor activation, failure, and destruction", () => {
    const queue = aggregate();
    const first = song("first");
    const second = song("second");
    queue.execute(add(Playlist.from([first, second])));
    queue.execute({ type: "setRepeatMode", repeatMode: RepeatMode.SONG });
    expect(queue.execute<Song>({ type: "finish", song: first }).playback).toEqual({ kind: "restart", song: first });
    queue.execute({ type: "activateSuccessor", song: first, autoplay: false });
    queue.execute({ type: "setRepeatMode", repeatMode: RepeatMode.OFF });
    const finish = queue.execute<Song | undefined>({ type: "finish", song: first });
    expect(finish.result).toBe(second);
    expect(finish.playback).toEqual({ kind: "activate", song: second });
    queue.execute({ type: "activateSuccessor", song: second, autoplay: false });
    expect(queue.execute<Song | undefined>({ type: "playbackFailed", song: second }).result).toBeUndefined();
    queue.execute({ type: "setAutoplay", autoplay: true });
    queue.execute({ type: "activateSuccessor", song: first, autoplay: true });
    expect(queue.execute({ type: "finish", song: first }).playback).toEqual({ kind: "findRelated", song: first });
    const destroyed = queue.execute({ type: "destroy", reason: QueueDeleteReason.STOPPED });
    expect(destroyed.newSnapshot.destroyed).toBe(true);
    expect(destroyed.events).toEqual([{ kind: "delete", reason: QueueDeleteReason.STOPPED }]);
    expect(() => queue.plan({ type: "setAutoplay", autoplay: false })).toThrowError(
      expect.objectContaining({ code: "QUEUE_DESTROYED" }),
    );
  });

  it("rebases independent controls and rejects structural conflicts", () => {
    const queue = aggregate();
    const first = song("first");
    queue.execute(add(first));
    const structural = queue.plan(add(song("later")));
    queue.execute({ type: "setVolume", volume: 200 });
    const rebased = queue.commit(structural);
    expect(rebased.rebased).toBe(true);
    expect(rebased.newSnapshot.volume).toBe(200);
    expect(rebased.newSnapshot.upcoming[0]?.id).toBe("later");

    const conflicting = queue.plan(add(song("conflict")));
    queue.execute(add(song("other")));
    expect(() => queue.commit(conflicting)).toThrowError(
      expect.objectContaining({ context: { operation: "queueRevisionConflict" } }),
    );
  });
});

describe("QueueAggregate reference model", () => {
  it("matches generated command sequences", () => {
    const command = fc.oneof(
      fc.record({ type: fc.constant("setVolume" as const), volume: fc.integer({ min: 0, max: 1000 }) }),
      fc.record({ type: fc.constant("setAutoplay" as const), autoplay: fc.boolean() }),
      fc.record({ type: fc.constant("setPaused" as const), paused: fc.boolean() }),
      fc.record({
        type: fc.constant("moveUpcoming" as const),
        fromIndex: fc.integer({ min: -2, max: 6 }),
        toIndex: fc.integer({ min: -2, max: 6 }),
      }),
      fc.record({ type: fc.constant("removeUpcoming" as const), index: fc.integer({ min: -2, max: 6 }) }),
      fc.constant({ type: "clearUpcoming" as const }),
      fc.constant({ type: "skip" as const }),
      fc.constant({ type: "previous" as const }),
    );
    fc.assert(
      fc.property(fc.array(command, { maxLength: 50 }), commands => {
        const queue = aggregate(3);
        const model = new ReferenceQueueModel(100, 3);
        const initial = [song("one"), song("two"), song("three"), song("four")];
        queue.execute(add(Playlist.from(initial)));
        model.execute({ type: "add", songs: initial, placement: QueuePlacement.APPEND });
        for (const next of commands) {
          try {
            queue.execute(next);
          } catch {
            // Reference commands that cannot navigate are defined as no-ops.
          }
          model.execute(next as ReferenceQueueCommand<unknown>);
          expect(model.assertEquivalent(queue.snapshot())).toBe(true);
        }
      }),
    );
  });
});

tests/acceptance/events.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import { DisTube, DisTubeEvent, QueueAddReason, QueueChangeReason, QueueDeleteReason, VoiceChangeReason } from "@";
import { Song } from "@/media/Song";
import { TestAdapter, TestSourcePlugin, TestVoicePlugin, tick, voiceChannel } from "../support";

describe("committed detached events", () => {
  it("exposes only the finalized event names", () => {
    expect(Object.values(DisTubeEvent)).toEqual([
      "initQueue",
      "addSong",
      "addPlaylist",
      "playSong",
      "finishSong",
      "queueChange",
      "deleteQueue",
      "voiceConnect",
      "voiceChange",
      "voiceDisconnect",
      "error",
      "debug",
    ]);
    expect(Object.values(DisTubeEvent)).not.toContain("finish");
    expect(Object.values(DisTubeEvent)).not.toContain("noRelated");
    expect(Object.values(DisTubeEvent)).not.toContain("disconnect");
  });

  it("publishes first-play Queue events in locked post-commit order", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const order: string[] = [];
    distube.on(DisTubeEvent.INIT_QUEUE, payload => {
      order.push("initQueue");
      expect(payload.snapshot.current?.id).toBe("search:first");
    });
    distube.on(DisTubeEvent.ADD_SONG, payload => {
      order.push("addSong");
      expect(payload.reason).toBe(QueueAddReason.PLAY);
    });
    distube.on(DisTubeEvent.PLAY_SONG, payload => {
      order.push("playSong");
      expect(payload.snapshot.current).toBe(payload.song);
    });

    const queue = await distube.play(voiceChannel, "first");
    await tick();

    expect(order).toEqual(["initQueue", "addSong", "playSong"]);
    expect(queue.current?.id).toBe("search:first");
    await distube.destroy();
  });

  it("uses exact oldSnapshot/newSnapshot keys for Queue and voice changes", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queueChange = vi.fn();
    const voiceChange = vi.fn();
    distube.on(DisTubeEvent.QUEUE_CHANGE, queueChange);
    distube.on(DisTubeEvent.VOICE_CHANGE, voiceChange);
    const queue = await distube.play(voiceChannel, "first");
    const voice = distube.voice.get(voiceChannel);

    await queue.setVolume(200);
    await voice?.setSelfMute(true);
    await tick();

    const queuePayload = queueChange.mock.calls[0]?.[0];
    expect(Object.keys(queuePayload).sort()).toEqual(["newSnapshot", "oldSnapshot", "queue", "reason"]);
    expect(queuePayload.reason).toBe(QueueChangeReason.VOLUME);
    expect(queuePayload.oldSnapshot.volume).toBe(100);
    expect(queuePayload.newSnapshot.volume).toBe(200);
    const voicePayload = voiceChange.mock.calls[0]?.[0];
    expect(Object.keys(voicePayload).sort()).toEqual(["newSnapshot", "oldSnapshot", "reason", "voice"]);
    expect(voicePayload.reason).toBe(VoiceChangeReason.SELF_MUTE);
    expect(voicePayload.oldSnapshot.selfMute).toBe(false);
    expect(voicePayload.newSnapshot.selfMute).toBe(true);
    await distube.destroy();
  });

  it("publishes natural finish, autoplay add, and successor play with enumerated reasons", async () => {
    const source = new TestSourcePlugin();
    source.related = new Song({ source: "test", id: "related", name: "Related", duration: 60 });
    const voice = new TestVoicePlugin();
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice,
      plugins: [source],
      queueDefaults: { autoplay: true },
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const events: string[] = [];
    distube.on(DisTubeEvent.FINISH_SONG, () => events.push("finishSong"));
    distube.on(DisTubeEvent.ADD_SONG, payload => {
      if (payload.reason === QueueAddReason.AUTOPLAY) events.push(`addSong:${payload.reason}`);
    });
    distube.on(DisTubeEvent.PLAY_SONG, payload => {
      if (payload.song.id === "related") events.push("playSong");
    });

    await distube.play(voiceChannel, "first");
    voice.finish();
    await tick();
    await tick();

    expect(events).toEqual(["finishSong", "addSong:autoplay", "playSong"]);
    await distube.destroy();
  });

  it("lets listener commands enter a later committed transition", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    let listenerCommand: Promise<unknown> | undefined;
    distube.on(DisTubeEvent.INIT_QUEUE, payload => {
      listenerCommand = payload.queue.setAutoplay(true);
    });

    const queue = await distube.play(voiceChannel, "first");
    await tick();
    await listenerCommand;

    expect(queue.autoplay).toBe(true);
    await distube.destroy();
  });

  it("does not await synchronous returns or asynchronous listener Promises", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    let resolveListener: () => void = () => {};
    const listener = new Promise<void>(resolve => {
      resolveListener = resolve;
    });
    distube.on(DisTubeEvent.ADD_SONG, () => listener);
    distube.on(DisTubeEvent.PLAY_SONG, () => 123);

    const queue = await distube.play(voiceChannel, "first");
    expect(queue.current?.id).toBe("search:first");
    resolveListener();
    await distube.destroy();
  });

  it("keeps raw synchronous throws and fatal missing error listeners", () => {
    const distube = new DisTube({ adapter: new TestAdapter(), voice: new TestVoicePlugin() });
    const listenerError = new Error("listener");
    distube.on(DisTubeEvent.DEBUG, () => {
      throw listenerError;
    });

    expect(() => distube.debug("message")).toThrow(listenerError);

    const fatal = new DisTube({ adapter: new TestAdapter(), voice: new TestVoicePlugin() });
    const background = new Error("background");
    expect(() => fatal.emit(DisTubeEvent.ERROR, { error: background })).toThrow(background);
  });

  it("emits background context once and keeps command failures rejection-only", async () => {
    const source = new TestSourcePlugin();
    const voice = new TestVoicePlugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [source] });
    const errors = vi.fn();
    const deletions = vi.fn();
    distube.on(DisTubeEvent.ERROR, errors);
    distube.on(DisTubeEvent.DELETE_QUEUE, deletions);
    const queue = await distube.play(voiceChannel, "first");
    const commandFailure = new Error("command failure");
    source.searchError = commandFailure;

    await expect(queue.add("second")).rejects.toMatchObject({
      code: "MEDIA_RESOLUTION_FAILED",
      cause: commandFailure,
    });
    await tick();
    expect(errors).not.toHaveBeenCalled();
    source.searchError = undefined;

    const failedSong = queue.current;
    voice.fail(new Error("background failure"));
    await tick();
    await tick();

    expect(errors).toHaveBeenCalledOnce();
    expect(errors.mock.calls[0]?.[0]).toMatchObject({ error: expect.any(Error), queue, song: failedSong });
    expect(deletions.mock.calls[0]?.[0].reason).toBe(QueueDeleteReason.ERROR);
    await distube.destroy();
  });

  it("reuses immutable Song references and independent voice revisions in snapshots", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "first");
    const song = queue.current;
    const before = queue.snapshot();
    const voice = distube.voice.get(voiceChannel);

    await voice?.setSelfMute(true);
    const after = queue.snapshot();

    expect(after.current).toBe(song);
    expect(Object.isFrozen(after)).toBe(true);
    expect(Object.isFrozen(after.upcoming)).toBe(true);
    expect(after.revision).toBe(before.revision);
    expect(after.voice?.revision).toBeGreaterThan(before.voice?.revision ?? 0);
    await distube.destroy();
  });
});

tests/public-contract/plugins-adapters.t.source:
import { describe, expect, it } from "vitest";
import { DisTube, DisTubeError, DisTubeEvent } from "@";
import type { DisTubePlugin } from "@/plugin";
import { LifecyclePlugin, TestAdapter, TestSourcePlugin, TestVoicePlugin, voiceChannel } from "../support";

describe("v6 plugin and adapter lifecycle", () => {
  it("initializes adapter, selected voice, then plugins and exposes class lookup", async () => {
    const adapter = new TestAdapter();
    const voice = new TestVoicePlugin();
    const calls: string[] = [];
    const one = new LifecyclePlugin("one", calls);
    const two = new LifecyclePlugin("two", calls);
    const source = new TestSourcePlugin();
    const distube = new DisTube({ adapter, voice, plugins: [one, source, two] });
    distube.on(DisTubeEvent.ERROR, () => undefined);

    await distube.play(voiceChannel, "query");

    expect(adapter.calls.slice(0, 2)).toEqual(["adapter:intents", "adapter:ready"]);
    expect(voice.calls[0]).toBe("voice:initialize");
    expect(calls).toEqual(["one:initialize", "two:initialize"]);
    expect(distube.plugins.get(TestSourcePlugin)).toBe(source);
    expect(distube.plugins.get(LifecyclePlugin)).toBe(one);
    await distube.destroy();
    expect(calls.slice(-2)).toEqual(["two:destroy", "one:destroy"]);
    expect(adapter.calls.at(-1)).toBe("adapter:destroy");
  });

  it("initializes a selected hybrid instance once when it is also in source order", async () => {
    class HybridVoice extends TestVoicePlugin {
      override readonly source = new TestSourcePlugin().source;
    }
    const voice = new HybridVoice();
    const distube = new DisTube({ adapter: new TestAdapter(), voice, plugins: [voice] });
    distube.on(DisTubeEvent.ERROR, () => undefined);

    await distube.play(voiceChannel, "query");

    expect(voice.calls.filter(call => call === "voice:initialize")).toHaveLength(1);
    await distube.destroy();
    expect(voice.calls.filter(call => call === "voice:destroy")).toHaveLength(1);
  });

  it("rejects invalid plugin instances and distinct duplicate IDs during construction", () => {
    const adapter = new TestAdapter();
    const voice = new TestVoicePlugin();
    const first = new LifecyclePlugin("duplicate", []);
    const second = new LifecyclePlugin("duplicate", []);

    expect(() => new DisTube({ adapter, voice, plugins: [first, second] })).toThrow(DisTubeError);
    expect(
      () =>
        new DisTube({
          adapter: new TestAdapter(),
          voice: new TestVoicePlugin(),
          plugins: [{} as DisTubePlugin],
        }),
    ).toThrow("plugin configuration");
  });

  it("rolls back initialized plugins in reverse order and destroys adapter last", async () => {
    const adapter = new TestAdapter();
    const voice = new TestVoicePlugin();
    const calls: string[] = [];
    const first = new LifecyclePlugin("first", calls);
    const failing = new LifecyclePlugin("failing", calls, true);
    const distube = new DisTube({ adapter, voice, plugins: [first, failing] });

    await expect(distube.play(voiceChannel, "query")).rejects.toMatchObject({ code: "PLUGIN_INITIALIZATION" });
    expect(calls).toEqual(["first:initialize", "failing:initialize", "first:destroy"]);
    expect(voice.calls).toContain("voice:destroy");
    expect(adapter.calls.at(-1)).toBe("adapter:destroy");
  });

  it("keeps guild identity normalization synchronous and side-effect free", () => {
    const adapter = new TestAdapter();
    const distube = new DisTube({ adapter, voice: new TestVoicePlugin() });

    expect(distube.getQueue(voiceChannel)).toBeUndefined();
    expect(adapter.calls).not.toContain("adapter:ready");
  });
});

