import { describe, expect, it, vi } from "vitest";
import { DisTube, DisTubeError, DisTubeEvent } from "@";
import { DisTubePlugin } from "@/plugin";
import { TestAdapter, TestSourcePlugin, TestVoicePlugin, tick, voiceChannel } from "../support";

class CleanupPlugin extends DisTubePlugin {
  readonly id: string;
  readonly #calls: string[];
  readonly #cleanup: () => void | Promise<void>;

  constructor(id: string, calls: string[], cleanup: () => void | Promise<void> = () => undefined) {
    super();
    this.id = id;
    this.#calls = calls;
    this.#cleanup = cleanup;
  }

  override initialize(): void {
    this.#calls.push(`${this.id}:initialize`);
  }

  override async destroy(): Promise<void> {
    this.#calls.push(`${this.id}:destroy`);
    await this.#cleanup();
  }
}

describe("v6 destruction", () => {
  it("is silent and idempotent while retaining final Queue reads", async () => {
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    const lifecycle = vi.fn();
    distube.on(DisTubeEvent.ERROR, () => undefined);
    distube.on(DisTubeEvent.DELETE_QUEUE, lifecycle);
    distube.on(DisTubeEvent.VOICE_DISCONNECT, lifecycle);
    const queue = await distube.play(voiceChannel, "first");
    await tick();
    lifecycle.mockClear();

    const firstDestroy = distube.destroy();
    expect(distube.destroy()).toBe(firstDestroy);
    expect(() => distube.getQueue(voiceChannel)).toThrowError(DisTubeError);
    await expect(queue.add("late")).rejects.toMatchObject({ code: "QUEUE_DESTROYED" });
    await firstDestroy;

    expect(lifecycle).not.toHaveBeenCalled();
    expect(queue.destroyed).toBe(true);
    expect(queue.current?.id).toBe("search:first");
    expect(queue.snapshot()).toBe(queue.snapshot());
  });

  it("times out each cleanup independently, continues in order, and aggregates failures", async () => {
    const calls: string[] = [];
    class CleanupVoice extends TestVoicePlugin {
      override destroy(): void {
        calls.push("voice:destroy");
      }
    }
    class CleanupAdapter extends TestAdapter {
      override async destroy(): Promise<void> {
        calls.push("adapter:destroy");
      }
    }
    const failing = new CleanupPlugin("failing", calls, () => {
      throw new Error("cleanup failed");
    });
    const hanging = new CleanupPlugin("hanging", calls, () => new Promise<void>(() => {}));
    const distube = new DisTube({
      adapter: new CleanupAdapter(),
      voice: new CleanupVoice(),
      plugins: [failing, hanging],
      cleanupTimeoutMs: 5,
    });

    const destroy = distube.destroy();
    expect(distube.destroy()).toBe(destroy);
    let failure: DisTubeError | undefined;
    try {
      await destroy;
    } catch (error: unknown) {
      if (error instanceof DisTubeError) failure = error;
    }

    expect(failure).toMatchObject({ code: "CLEANUP_FAILED" });
    expect(failure?.cause).toBeInstanceOf(AggregateError);
    const cause = failure?.cause;
    if (!(cause instanceof AggregateError)) throw new Error("Expected an aggregate cleanup failure");
    expect(cause.errors).toHaveLength(2);
    expect(calls.filter(call => call.endsWith(":destroy"))).toEqual([
      "hanging:destroy",
      "failing:destroy",
      "voice:destroy",
      "adapter:destroy",
    ]);
    await expect(distube.destroy()).rejects.toBe(failure);
  });
});

