import { describe, expect, it, vi } from "vitest";
import { VoiceChangeReason, VoiceDisconnectReason } from "@/enums";
import type { PreparedPlayback, VoiceRuntimeCapability } from "@/plugin";
import { type CommandOperation, SessionCoordinator } from "@/session/SessionCoordinator";
import { VoiceRuntime, type VoiceRuntimeObserver } from "@/voice/VoiceRuntime";
import {
  secondVoiceChannel,
  TestAdapter,
  type TestConnection,
  type TestFilters,
  TestVoicePlugin,
  tick,
  voiceChannel,
} from "../support";

function deferred(): { readonly promise: Promise<void>; readonly resolve: () => void } {
  let resolve: () => void = () => {};
  const promise = new Promise<void>(done => {
    resolve = done;
  });
  return { promise, resolve };
}

function fixture(capability?: VoiceRuntimeCapability<TestFilters, TestConnection, PreparedPlayback>): {
  readonly runtime: VoiceRuntime<TestAdapter, TestFilters, TestConnection, PreparedPlayback>;
  readonly coordinator: SessionCoordinator;
  readonly operations: CommandOperation[];
  readonly observer: VoiceRuntimeObserver;
} {
  const coordinator = new SessionCoordinator();
  const operations: CommandOperation[] = [];
  const begin = coordinator.begin.bind(coordinator);
  const observer: VoiceRuntimeObserver = {
    transition: vi.fn(),
    disconnect: vi.fn(),
    error: vi.fn(),
  };
  const voice = new TestVoicePlugin();
  return {
    coordinator,
    operations,
    observer,
    runtime: new VoiceRuntime({
      guildId: voiceChannel.guildId,
      runtimeGeneration: 4,
      adapter: new TestAdapter(),
      capability: capability ?? voice.voice,
      defaults: { selfMute: false, selfDeaf: true },
      coordinator: {
        begin: (...args) => {
          const operation = begin(...args);
          operations.push(operation);
          return operation;
        },
        commit: coordinator.commit.bind(coordinator),
      },
      observer,
    }),
  };
}

describe("VoiceRuntime", () => {
  it("applies defaults, exposes acknowledgement policy, and rejects a second initial connect", async () => {
    const plugin = new TestVoicePlugin();
    const join = vi.fn(plugin.voice.join.bind(plugin.voice));
    const { runtime, operations } = fixture({ ...plugin.voice, join });

    expect(runtime.acknowledgement).toEqual({
      move: "correlated-both",
      selfMute: "correlated-both",
      selfDeaf: "correlated-both",
      remoteLifecycle: "notification",
    });
    expect(runtime.state).toBe("connecting");
    expect(runtime.connection).toBeUndefined();
    expect(runtime.snapshot).toBeUndefined();
    expect(() => runtime.getVoiceSnapshot()).toThrowError(expect.objectContaining({ code: "NO_VOICE" }));

    const transition = await runtime.connect(voiceChannel, { selfMute: true });

    expect(transition).toMatchObject({ kind: "connect", changed: true });
    expect(join.mock.calls[0]?.[0]).toMatchObject({ selfMute: true, selfDeaf: true });
    expect(runtime.state).toBe("active");
    expect(runtime.connection).toBeDefined();
    expect(runtime.requireConnection()).toBe(runtime.connection);
    expect(runtime.getVoiceSnapshot()).toEqual(runtime.snapshot);
    expect(runtime.voice.snapshot()).toEqual(runtime.snapshot);
    expect(operations[0]?.isCurrent()).toBe(false);
    await expect(runtime.connect(voiceChannel)).rejects.toMatchObject({ code: "VOICE_CONNECTION_FAILED" });
  });

  it("completes command authority while retaining the current connection subscription", async () => {
    const plugin = new TestVoicePlugin();
    const { runtime, operations, observer } = fixture(plugin.voice);

    await runtime.connect(voiceChannel);
    runtime.activateNotifications();

    expect(operations).toHaveLength(1);
    expect(operations[0]?.isCurrent()).toBe(false);
    plugin.notifyChange({ type: "change", reason: VoiceChangeReason.RECONNECTING });
    await tick();

    expect(runtime.voice.status).toBe("reconnecting");
    expect(observer.transition).toHaveBeenCalledWith(
      4,
      expect.objectContaining({ reason: VoiceChangeReason.RECONNECTING }),
    );
  });

  it("disposes a stale connection candidate exactly once", async () => {
    const plugin = new TestVoicePlugin();
    const release = deferred();
    const capability: VoiceRuntimeCapability<TestFilters, TestConnection, PreparedPlayback> = {
      ...plugin.voice,
      join: async request => {
        await release.promise;
        return plugin.voice.join(request);
      },
    };
    const { runtime, coordinator } = fixture(capability);
    const connecting = runtime.connect(voiceChannel);
    await Promise.resolve();

    coordinator.invalidate("voice");
    release.resolve();

    await expect(connecting).rejects.toMatchObject({ code: "VOICE_CONNECTION_FAILED" });
    expect(plugin.calls.filter(call => call.startsWith("leave:"))).toHaveLength(1);
    expect(runtime.state).toBe("terminal");
  });

  it("memoizes connection cleanup before a synchronous disposer failure", async () => {
    const plugin = new TestVoicePlugin();
    const failure = new Error("leave failed");
    let leaveCalls = 0;
    const capability: VoiceRuntimeCapability<TestFilters, TestConnection, PreparedPlayback> = {
      ...plugin.voice,
      leave: () => {
        leaveCalls += 1;
        throw failure;
      },
    };
    const { runtime } = fixture(capability);
    await runtime.connect(voiceChannel);
    runtime.activateNotifications();

    const first = runtime.cleanup();
    const second = runtime.cleanup();

    expect(second).toBe(first);
    await expect(first).rejects.toEqual(new AggregateError([failure], "Voice connection cleanup failed"));
    expect(leaveCalls).toBe(1);
    expect(runtime.snapshot?.status).toBe("disconnected");
  });

  it("memoizes connection cleanup across asynchronous disposer rejection", async () => {
    const plugin = new TestVoicePlugin();
    const failure = new Error("async leave failed");
    const leave = vi.fn(() => Promise.reject(failure));
    const capability: VoiceRuntimeCapability<TestFilters, TestConnection, PreparedPlayback> = {
      ...plugin.voice,
      leave,
    };
    const { runtime } = fixture(capability);
    await runtime.connect(voiceChannel);
    runtime.activateNotifications();

    const first = runtime.cleanup();
    const second = runtime.cleanup();

    expect(second).toBe(first);
    await expect(first).rejects.toEqual(new AggregateError([failure], "Voice connection cleanup failed"));
    expect(leave).toHaveBeenCalledOnce();
  });

  it("buffers notifications until activation and routes current change, error, finish, and disconnect categories", async () => {
    const plugin = new TestVoicePlugin();
    const { runtime, observer } = fixture(plugin.voice);
    await runtime.connect(voiceChannel);

    plugin.notifyChange({ type: "change", reason: VoiceChangeReason.RECONNECTING });
    expect(observer.transition).not.toHaveBeenCalled();
    expect(runtime.voice.status).toBe("ready");

    runtime.activateNotifications();
    runtime.activateNotifications();
    await tick();
    expect(runtime.voice.status).toBe("reconnecting");
    expect(observer.transition).toHaveBeenCalledWith(
      4,
      expect.objectContaining({ reason: VoiceChangeReason.RECONNECTING, changed: true }),
    );

    const error = new Error("voice diagnostic");
    plugin.connections.get(voiceChannel.guildId)?.notify({ type: "error", error });
    plugin.connections.get(voiceChannel.guildId)?.notify({ type: "finish" });
    plugin.remoteDisconnect(voiceChannel.guildId, error);
    plugin.remoteDisconnect(voiceChannel.guildId, new Error("duplicate"));

    expect(observer.error).toHaveBeenCalledWith(4, error);
    expect(observer.disconnect).toHaveBeenCalledOnce();
    expect(observer.disconnect).toHaveBeenCalledWith(4, VoiceDisconnectReason.REMOTE, error);

    runtime.beginDestroy();
    plugin.connections.get(voiceChannel.guildId)?.notify({ type: "error", error: new Error("late") });
    expect(observer.error).toHaveBeenCalledOnce();
  });

  it("moves with committed defaults and applies idempotent mute/deaf controls before terminal leave", async () => {
    const plugin = new TestVoicePlugin();
    const move = vi.fn(plugin.voice.move.bind(plugin.voice));
    const setSelfMute = vi.fn(plugin.voice.setSelfMute?.bind(plugin.voice));
    const setSelfDeaf = vi.fn(plugin.voice.setSelfDeaf?.bind(plugin.voice));
    const { runtime, observer, operations } = fixture({ ...plugin.voice, move, setSelfMute, setSelfDeaf });
    await runtime.connect(voiceChannel, { selfMute: true, selfDeaf: true });
    runtime.activateNotifications();

    const moved = await runtime.move(secondVoiceChannel, { selfDeaf: false });
    expect(moved).toMatchObject({ kind: "change", reason: VoiceChangeReason.MOVED, changed: true });
    expect(move.mock.calls[0]?.[0]).toMatchObject({ selfMute: true, selfDeaf: false });
    expect(runtime.voice.channelId).toBe(secondVoiceChannel.id);
    expect(observer.transition).toHaveBeenCalledWith(4, moved);

    await runtime.setSelfMute(false);
    await runtime.setSelfMute(false);
    await runtime.setSelfDeaf(false);
    await tick();
    expect(setSelfMute).toHaveBeenCalledOnce();
    expect(setSelfDeaf).toHaveBeenCalledOnce();
    const muteTransitions = vi
      .mocked(observer.transition)
      .mock.calls.flatMap(([, transition]) =>
        transition.kind === "change" && transition.reason === VoiceChangeReason.SELF_MUTE ? [transition.changed] : [],
      );
    const deafTransitions = vi
      .mocked(observer.transition)
      .mock.calls.flatMap(([, transition]) =>
        transition.kind === "change" && transition.reason === VoiceChangeReason.SELF_DEAF ? [transition.changed] : [],
      );
    expect(muteTransitions).toEqual(expect.arrayContaining([true, false]));
    expect(deafTransitions).toEqual(expect.arrayContaining([true, false]));
    expect(runtime.voice.selfMute).toBe(false);
    expect(runtime.voice.selfDeaf).toBe(false);
    expect(operations.every(operation => !operation.isCurrent())).toBe(true);

    const left = await runtime.leave(VoiceDisconnectReason.LEFT);
    expect(left).toMatchObject({ kind: "disconnect", reason: VoiceDisconnectReason.LEFT, changed: true });
    expect(runtime.state).toBe("terminal");
    expect(runtime.connection).toBeUndefined();
    expect(runtime.voice.status).toBe("disconnected");
    expect(plugin.calls).toContain(`leave:${secondVoiceChannel.id}`);
    await expect(runtime.acceptRemoteDisconnect(VoiceDisconnectReason.REMOTE)).resolves.toBeUndefined();
    expect(() => runtime.requireConnection()).toThrowError(expect.objectContaining({ code: "NO_VOICE" }));
  });

  it("commits remote termination and reports connection cleanup failure without losing the primary transition", async () => {
    const plugin = new TestVoicePlugin();
    const failure = new Error("remote cleanup failed");
    const { runtime, observer } = fixture({
      ...plugin.voice,
      leave: () => Promise.reject(failure),
    });
    await runtime.connect(voiceChannel);
    runtime.activateNotifications();

    const transition = await runtime.acceptRemoteDisconnect(VoiceDisconnectReason.REMOTE);

    expect(transition).toMatchObject({ kind: "disconnect", reason: VoiceDisconnectReason.REMOTE, changed: true });
    expect(runtime.state).toBe("terminal");
    expect(runtime.connection).toBeUndefined();
    expect(observer.transition).toHaveBeenCalledWith(4, transition);
    expect(observer.error).toHaveBeenCalledWith(4, failure);
    await expect(runtime.cleanup()).resolves.toBeUndefined();
    runtime.destroy();
    expect(runtime.state).toBe("terminal");
  });

  it("terminates an unconnected runtime through memoized cleanup and destruction", async () => {
    const { runtime } = fixture();

    const first = runtime.cleanup();
    const second = runtime.cleanup();

    expect(second).toBe(first);
    await expect(first).resolves.toBeUndefined();
    expect(runtime.state).toBe("terminal");
    expect(runtime.snapshot).toBeUndefined();
    runtime.destroy();
    runtime.beginDestroy();
    expect(runtime.state).toBe("terminal");
  });
});

tests/events/DeterministicRuntime.test.t.source:
import { describe, expect, it, vi } from "vitest";
import { DisTube, DisTubeEvent } from "@";
import { TestAdapter, TestSourcePlugin, TestVoicePlugin, voiceChannel } from "../support";
import { DeterministicScheduler, FakeMonotonicClock } from "../support/DeterministicScheduler";

describe("deterministic runtime phases", () => {
  it("drains publication explicitly and advances live or paused Queue time", async () => {
    const scheduler = new DeterministicScheduler();
    const clock = new FakeMonotonicClock();
    const distube = new DisTube(
      { adapter: new TestAdapter(), voice: new TestVoicePlugin(), plugins: [new TestSourcePlugin()] },
      { scheduler, clock },
    );
    const published = vi.fn();
    distube.on(DisTubeEvent.INIT_QUEUE, published);
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const queue = await distube.play(voiceChannel, "first");

    expect(published).not.toHaveBeenCalled();
    expect(scheduler.drain("publication")).toBeGreaterThan(0);
    expect(published).toHaveBeenCalledOnce();
    clock.advanceBy(1500);
    expect(queue.currentTime).toBe(1.5);
    await queue.setPaused(true);
    clock.advanceBy(5000);
    expect(queue.currentTime).toBe(1.5);
    await queue.setPaused(false);
    clock.advanceBy(500);
    expect(queue.currentTime).toBe(2);
    await distube.destroy();
  });
});

