import type { DisTubeErrorCode, IntegrationOutcome } from "distube/errors";
import { DISTUBE_ERROR_CATALOG, DisTubeError as ErrorContract } from "distube/errors";
import { formatDuration, Playlist as MediaPlaylist, Song as MediaSong } from "distube/media";
import { UrlPolicy } from "distube/url";
import { describe, expect, it } from "vitest";
import type { Queue } from "@";
import { DisTube, DisTubeEvent, Playlist, QueuePlacement, QueueSkipBehavior, RepeatMode, Song, VoiceFeature } from "@";
import { TestAdapter, TestSourcePlugin, TestVoicePlugin, voiceChannel } from "../support";

describe("v6 public type surface", () => {
  it("infers adapter, selected voice filters, metadata, plugin lookup, and events", async () => {
    const adapter = new TestAdapter();
    const voice = new TestVoicePlugin();
    const source = new TestSourcePlugin();
    const distube = new DisTube<TestAdapter, TestVoicePlugin, { request: string }>({
      adapter,
      voice,
      plugins: [source],
      queueDefaults: { volume: 100, autoplay: false, repeatMode: RepeatMode.OFF, historyLimit: 50 },
    });
    distube.on(DisTubeEvent.ERROR, payload => payload.error);
    distube.on(DisTubeEvent.QUEUE_CHANGE, payload => {
      const oldRevision: number = payload.oldSnapshot.revision;
      const newRevision: number = payload.newSnapshot.revision;
      return oldRevision + newRevision;
    });

    expect(distube.plugins.get(TestSourcePlugin)).toBe(source);
    const queue = await distube.play(voiceChannel, "query", { metadata: { request: "one" } });
    const typedQueue: Queue<{ request: string }, import("../support").TestFilters> = queue;
    async function assertQueueControls(candidate: typeof typedQueue): Promise<void> {
      const paused: typeof candidate = await candidate.setPaused(true);
      const moved: typeof candidate = await candidate.move(0, 0);
      const removed: Song<{ request: string }> = await candidate.remove(0);
      const cleared: typeof candidate = await candidate.clearUpcoming();
      const shuffled: typeof candidate = await candidate.shuffle();
      void [paused, moved, removed, cleared, shuffled];
      // @ts-expect-error pause was replaced by setPaused(true).
      void candidate.pause;
      // @ts-expect-error resume was replaced by setPaused(false).
      void candidate.resume;
    }
    expect(assertQueueControls).toBeTypeOf("function");
    await typedQueue.filters.add("gain", { level: 1, unit: "dB" });
    await typedQueue.filters.add({ speed: { rate: 1.25 } });
    function assertFilterErrors(candidate: typeof typedQueue): void {
      // @ts-expect-error scalar shortcuts are not accepted.
      void candidate.filters.add("gain", 1);
      // @ts-expect-error unknown selected-voice filter name.
      void candidate.filters.add("unknown", {});
    }
    expect(assertFilterErrors).toBeTypeOf("function");
    expect(typedQueue.current?.metadata.request).toBe("one");
    await distube.destroy();
  });

  it("exports the locked enum choices", () => {
    expect(QueuePlacement).toEqual({ APPEND: "append", NEXT: "next" });
    expect(QueueSkipBehavior).toEqual({ HISTORY: "history", DISCARD: "discard" });
    expect(RepeatMode).toEqual({ OFF: "off", SONG: "song", QUEUE: "queue" });
    expect(VoiceFeature.FILTERS).toBe("filters");
  });

  it("accepts plugin-owned custom playable values and Playlist.from", async () => {
    const distube = new DisTube<TestAdapter, TestVoicePlugin, { source: string }>({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new TestSourcePlugin()],
    });
    distube.on(DisTubeEvent.ERROR, () => undefined);
    const custom = {
      async toPlayable(): Promise<Playlist<{ source: string }>> {
        return Playlist.from([new Song({ source: "custom", id: "one", duration: 1, metadata: { source: "custom" } })]);
      },
    };
    const queue = await distube.play(voiceChannel, custom);
    expect(queue.current?.source).toBe("custom");
    await distube.destroy();
  });

  it("exposes focused media, error, and URL subpaths", async () => {
    const song = new MediaSong({ source: "test", id: "one", duration: 5 });
    const playlist = MediaPlaylist.from([song]);
    const outcome: IntegrationOutcome<typeof song> = { kind: "handled", value: song };
    const error = new ErrorContract("NO_QUEUE");
    const policy = new UrlPolicy({ allowedProtocols: ["https:"] });

    expect(playlist.songs[0]).toBe(song);
    expect(formatDuration(5)).toBe("00:05");
    expect(outcome.value).toBe(song);
    expect(error.code).toBe("NO_QUEUE");
    function assertRemovedErrorCodes(): void {
      // @ts-expect-error duplicate pause is now an idempotent no-op.
      const paused: DisTubeErrorCode = "PAUSED";
      // @ts-expect-error duplicate resume is now an idempotent no-op.
      const resumed: DisTubeErrorCode = "RESUMED";
      // @ts-expect-error inactive defined-filter removal is now an idempotent no-op.
      const filterInactive: DisTubeErrorCode = "FILTER_INACTIVE";
      // @ts-expect-error obsolete code is absent from the public catalog.
      void DISTUBE_ERROR_CATALOG.PAUSED;
      // @ts-expect-error obsolete code is absent from the public catalog.
      void DISTUBE_ERROR_CATALOG.RESUMED;
      // @ts-expect-error obsolete code is absent from the public catalog.
      void DISTUBE_ERROR_CATALOG.FILTER_INACTIVE;
      void [paused, resumed, filterInactive];
    }
    expect(assertRemovedErrorCodes).toBeTypeOf("function");
    await expect(policy.evaluate("https://example.com")).resolves.toMatchObject({ allowed: true });
  });
});

