import { describe, expect, it } from "vitest";
import { DisTube } from "@";
import { DisTubePlugin } from "@/plugin";
import { TestAdapter, TestVoicePlugin } from "../support";

describe("Plugin Graph and Runtime Lifecycle", () => {
  it("indexes exact configured instances by stable ID", () => {
    class Plugin extends DisTubePlugin {
      override readonly id = "plugin";
    }
    const plugin = new Plugin();
    const distube = new DisTube({ adapter: new TestAdapter(), voice: new TestVoicePlugin(), plugins: [plugin] });

    expect(distube.plugins.getById("plugin")).toBe(plugin);
    void distube.destroy();
  });

  it("rejects selected voice adapter requirements before initialization", () => {
    const voice = new TestVoicePlugin();
    Object.defineProperty(voice, "voice", {
      value: { ...voice.voice, requiredAdapterCapabilities: ["voiceGateway"] as const },
    });

    expect(() => new DisTube({ adapter: new TestAdapter(), voice })).toThrowError(
      expect.objectContaining({ code: "ADAPTER_INCOMPATIBLE", context: { capability: "voiceGateway" } }),
    );
  });

  it("bounds destruction when initialization ignores cancellation", async () => {
    class HangingPlugin extends DisTubePlugin {
      override readonly id = "hanging";
      override initialize(): Promise<void> {
        return new Promise(() => {});
      }
    }
    const distube = new DisTube({
      adapter: new TestAdapter(),
      voice: new TestVoicePlugin(),
      plugins: [new HangingPlugin()],
      cleanupTimeoutMs: 5,
    });

    await expect(distube.destroy()).resolves.toBeUndefined();
    expect(() => distube.getQueues()).toThrowError(expect.objectContaining({ code: "DESTROYED" }));
  });
});

