import { describe, expect, it, vi } from "vitest";
import { DisTubeEvent } from "@/enums";
import { EventJournal } from "@/events/EventJournal";
import type { EmptyFilterCatalog } from "@/filters/contracts";
import { DeterministicScheduler } from "../support/DeterministicScheduler";

const guild = "100000000000000001";

describe("EventJournal", () => {
  it("stores immutable typed records and drains one publication turn", () => {
    const scheduler = new DeterministicScheduler();
    const published: string[] = [];
    const journal = new EventJournal<unknown, EmptyFilterCatalog>(scheduler, (_event, message) => {
      published.push(message as string);
    });
    const first = journal.append({
      guildId: guild,
      event: DisTubeEvent.DEBUG,
      aggregateRevision: 2,
      correlation: "diagnostic",
      generation: 4,
      args: ["first"],
    });
    journal.append({
      guildId: guild,
      event: DisTubeEvent.DEBUG,
      aggregateRevision: 3,
      correlation: "diagnostic",
      args: ["second"],
    });

    expect(Object.isFrozen(first)).toBe(true);
    expect(Object.isFrozen(first.args)).toBe(true);
    expect(first).toMatchObject({ sequence: 1, aggregateRevision: 2, generation: 4 });
    expect(journal.pending(guild)).toHaveLength(2);
    expect(scheduler.drainOne("publication")).toBe(true);
    expect(published).toEqual(["first"]);
    expect(journal.pending(guild)).toHaveLength(1);
    expect(scheduler.drain("publication")).toBe(1);
    expect(published).toEqual(["first", "second"]);
  });

  it("preserves one guild FIFO across logical session recreation", () => {
    const scheduler = new DeterministicScheduler();
    const published: string[] = [];
    const journal = new EventJournal<unknown, EmptyFilterCatalog>(scheduler, (_event, message) => {
      published.push(message as string);
    });
    const append = (message: string): void => {
      journal.append({
        guildId: guild,
        event: DisTubeEvent.DEBUG,
        aggregateRevision: 1,
        correlation: "command",
        args: [message],
      });
    };
    append("old-session");
    append("replacement-session");

    scheduler.drain("publication");
    expect(published).toEqual(["old-session", "replacement-session"]);
  });

  it("preserves raw publisher throw behavior while scheduling the next record", () => {
    const scheduler = new DeterministicScheduler();
    const error = new Error("listener");
    const publisher = vi.fn((_event: unknown, ...args: readonly unknown[]) => {
      const message = args[0];
      if (message === "first") throw error;
    });
    const journal = new EventJournal<unknown, EmptyFilterCatalog>(scheduler, publisher);
    for (const message of ["first", "second"]) {
      journal.append({
        guildId: guild,
        event: DisTubeEvent.DEBUG,
        aggregateRevision: 0,
        correlation: "diagnostic",
        args: [message],
      });
    }

    expect(() => scheduler.drainOne("publication")).toThrow(error);
    expect(scheduler.drainOne("publication")).toBe(true);
    expect(publisher).toHaveBeenCalledTimes(2);
  });

  it("does not make publication observe listener Promise settlement", () => {
    const scheduler = new DeterministicScheduler();
    const listener = new Promise<void>(() => {});
    const publisher = vi.fn(() => listener);
    const journal = new EventJournal<unknown, EmptyFilterCatalog>(scheduler, publisher);
    journal.append({
      guildId: guild,
      event: DisTubeEvent.DEBUG,
      aggregateRevision: 0,
      correlation: "diagnostic",
      args: ["message"],
    });

    expect(scheduler.drainOne("publication")).toBe(true);
    expect(publisher).toHaveReturnedWith(listener);
  });
});

tests/filters/FilterEngine.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import type { FilterCatalog, FilterDefinition, FilterState } from "@/filters/contracts";
import { FilterEngine, type FilterEnginePort } from "@/filters/FilterEngine";

interface GainParameters {
  readonly level: number;
  readonly unit: string;
}

interface ComplexParameters {
  readonly settings: readonly Readonly<{ readonly enabled: boolean }>[];
}

type TestCatalog = Readonly<{
  gain: FilterDefinition<GainParameters>;
  complex: FilterDefinition<ComplexParameters>;
}>;

const catalog = Object.freeze({
  gain: Object.freeze({
    defaults: Object.freeze({ level: 0, unit: "dB" }),
    parameters: Object.freeze({
      level: Object.freeze({
        min: -10,
        max: 10,
        validate: (value: number) => value !== 7,
      }),
      unit: Object.freeze({}),
    }),
    validate: (parameters: Readonly<GainParameters>) => parameters.unit !== "invalid",
  }),
  complex: Object.freeze({
    parameters: Object.freeze({ settings: Object.freeze({}) }),
  }),
}) satisfies TestCatalog & FilterCatalog;

function createPort(initial: FilterState<TestCatalog> = Object.freeze({})) {
  let state = { revision: 0, filters: initial };
  const applyBackend = vi.fn<FilterEnginePort<TestCatalog>["applyBackend"]>(async () => undefined);
  const commit = vi.fn<FilterEnginePort<TestCatalog>["commit"]>(async (candidate, expectedRevision) => {
    expect(expectedRevision).toBe(state.revision);
    state = { revision: state.revision + 1, filters: candidate };
  });
  const port: FilterEnginePort<TestCatalog> = {
    current: () => state,
    applyBackend,
    commit,
  };
  return { port, applyBackend, commit, current: () => state };
}

describe("FilterEngine", () => {
  it("treats deeply equal arrays and records as a no-op", async () => {
    const initial = Object.freeze({
      complex: Object.freeze({ settings: Object.freeze([Object.freeze({ enabled: true })]) }),
    });
    const harness = createPort(initial);
    const engine = new FilterEngine(catalog, harness.port);

    await engine.execute({
      kind: "add",
      filters: { complex: { settings: [{ enabled: true }] } },
    });

    expect(harness.applyBackend).not.toHaveBeenCalled();
    expect(harness.commit).not.toHaveBeenCalled();

    await engine.execute({
      kind: "add",
      filters: { complex: { settings: [{ enabled: true }, { enabled: false }] } },
    });

    expect(harness.applyBackend).toHaveBeenCalledTimes(1);
    expect(harness.commit).toHaveBeenCalledTimes(1);
  });

  it("validates filter names, parameter objects, fields, bounds, and validators", async () => {
    const harness = createPort();
    const engine = new FilterEngine(catalog, harness.port);

    await expect(engine.execute({ kind: "add", filters: { unknown: {} } })).rejects.toMatchObject({
      code: "FILTER_UNKNOWN",
      context: { name: "unknown" },
    });
    for (const value of [null, [], 1, "gain"]) {
      await expect(engine.execute({ kind: "add", filters: { gain: value } })).rejects.toMatchObject({
        code: "FILTER_INVALID",
        context: { name: "gain", reason: "parameters" },
      });
    }
    await expect(engine.execute({ kind: "add", filters: { gain: { unknown: true } } })).rejects.toMatchObject({
      code: "FILTER_INVALID",
      context: { name: "gain", parameter: "unknown" },
    });
    await expect(engine.execute({ kind: "add", filters: { gain: { level: -11 } } })).rejects.toMatchObject({
      code: "FILTER_INVALID",
      context: { name: "gain", parameter: "level", min: -10 },
    });
    await expect(engine.execute({ kind: "add", filters: { gain: { level: 11 } } })).rejects.toMatchObject({
      code: "FILTER_INVALID",
      context: { name: "gain", parameter: "level", max: 10 },
    });
    await expect(engine.execute({ kind: "add", filters: { gain: { level: 7 } } })).rejects.toMatchObject({
      code: "FILTER_INVALID",
      context: { name: "gain", parameter: "level" },
    });
    await expect(engine.execute({ kind: "add", filters: { gain: { unit: "invalid" } } })).rejects.toMatchObject({
      code: "FILTER_INVALID",
      context: { name: "gain" },
    });

    expect(harness.applyBackend).not.toHaveBeenCalled();
    expect(harness.commit).not.toHaveBeenCalled();
  });

  it("applies defaults, freezes candidates, and supports remove, set, and clear", async () => {
    const harness = createPort();
    const engine = new FilterEngine(catalog, harness.port);

    await engine.execute({ kind: "add", filters: { gain: { level: 3 } } });
    expect(harness.applyBackend).toHaveBeenLastCalledWith({ gain: { level: 3, unit: "dB" } }, expect.any(AbortSignal));
    const applied = harness.applyBackend.mock.calls.at(-1)?.[0];
    expect(Object.isFrozen(applied)).toBe(true);
    expect(Object.isFrozen(applied?.gain)).toBe(true);

    await engine.execute({ kind: "remove", names: ["gain"] });
    expect(harness.current().filters).toEqual({});
    const applications = harness.applyBackend.mock.calls.length;
    const commits = harness.commit.mock.calls.length;
    await expect(engine.execute({ kind: "remove", names: ["gain"] })).resolves.toBeUndefined();
    expect(harness.applyBackend).toHaveBeenCalledTimes(applications);
    expect(harness.commit).toHaveBeenCalledTimes(commits);
    await expect(
      engine.execute({ kind: "remove", names: ["unknown" as keyof TestCatalog & string] }),
    ).rejects.toMatchObject({
      code: "FILTER_UNKNOWN",
      context: { name: "unknown" },
    });

    await engine.execute({ kind: "set", filters: { gain: { level: 2, unit: "dB" } } });
    expect(harness.current().filters).toEqual({ gain: { level: 2, unit: "dB" } });
    await engine.execute({ kind: "clear" });
    expect(harness.current().filters).toEqual({});
  });

  it("rebases an acknowledgement when only the revision changed", async () => {
    const base = Object.freeze({ revision: 4, filters: Object.freeze({}) as FilterState<TestCatalog> });
    const rebased = Object.freeze({ revision: 5, filters: base.filters });
    let reads = 0;
    const commit = vi.fn(async () => undefined);
    const port: FilterEnginePort<TestCatalog> = {
      current: () => (reads++ === 0 ? base : rebased),
      applyBackend: async () => undefined,
      commit,
    };

    await new FilterEngine(catalog, port).execute({ kind: "add", filters: { gain: { level: 1 } } });

    expect(commit).toHaveBeenCalledWith({ gain: { level: 1, unit: "dB" } }, 5);
  });

  it("rejects an acknowledgement when the revision and filters changed", async () => {
    const base = Object.freeze({ revision: 4, filters: Object.freeze({}) as FilterState<TestCatalog> });
    const current = Object.freeze({
      revision: 5,
      filters: Object.freeze({ gain: Object.freeze({ level: 2, unit: "dB" }) }),
    });
    let reads = 0;
    const commit = vi.fn(async () => undefined);
    const port: FilterEnginePort<TestCatalog> = {
      current: () => (reads++ === 0 ? base : current),
      applyBackend: async () => undefined,
      commit,
    };

    await expect(
      new FilterEngine(catalog, port).execute({ kind: "add", filters: { gain: { level: 1 } } }),
    ).rejects.toMatchObject({
      code: "FILTER_STALE",
      context: { expectedRevision: 4, actualRevision: 5 },
    });
    expect(commit).not.toHaveBeenCalled();
  });

  it("rejects an already-aborted caller before reading state", async () => {
    const harness = createPort();
    const current = vi.spyOn(harness.port, "current");
    const controller = new AbortController();
    const reason = new Error("cancelled");
    controller.abort(reason);

    await expect(new FilterEngine(catalog, harness.port).execute({ kind: "clear" }, controller.signal)).rejects.toBe(
      reason,
    );
    expect(current).not.toHaveBeenCalled();
  });
});

tests/playback/PlaybackEngine.test.ts.source:
import { describe, expect, it, type Mock, vi } from "vitest";
import { MediaResolver } from "@/media/MediaResolver";
import { Song } from "@/media/Song";
import { PlaybackClock } from "@/playback/PlaybackClock";
import { PlaybackEngine, type PlaybackSubscription } from "@/playback/PlaybackEngine";
import {
  DisTubePlugin,
  type PreparedPlayback,
  type SourceCapability,
  StreamLease,
  type VoiceLifecycleNotification,
} from "@/plugin";
import type { SourceEntry } from "@/plugins/PluginGraph";
import { SessionCoordinator } from "@/session/SessionCoordinator";
import { type TestConnection, type TestFilters, TestSourcePlugin, TestVoicePlugin, voiceChannel } from "../support";
import { FakeMonotonicClock } from "../support/DeterministicScheduler";

const connection: TestConnection = { channelId: voiceChannel.id, notify: () => {} };
type PlaybackNotification = Extract<VoiceLifecycleNotification, { type: "finish" | "error" }>;
type NotificationHandler = (subscription: PlaybackSubscription<unknown>, notification: PlaybackNotification) => void;

function sourceEntry(plugin: DisTubePlugin & { readonly source: SourceCapability }): SourceEntry {
  return { plugin, source: plugin.source };
}

async function resolvedSong(resolver: MediaResolver, query: string): Promise<Song> {
  return (await resolver.resolve(query, undefined, new AbortController().signal)) as Song;
}

function engineFixture(
  options: {
    readonly source?: DisTubePlugin & { readonly source: SourceCapability };
    readonly voice?: TestVoicePlugin;
    readonly coordinator?: SessionCoordinator;
  } = {},
): {
  readonly engine: PlaybackEngine<unknown, TestFilters, TestConnection, PreparedPlayback>;
  readonly source: DisTubePlugin & { readonly source: SourceCapability };
  readonly voice: TestVoicePlugin;
  readonly coordinator: SessionCoordinator;
  readonly resolver: MediaResolver;
  readonly clock: PlaybackClock;
  readonly onNotification: Mock<NotificationHandler>;
} {
  const source = options.source ?? new TestSourcePlugin();
  const voice = options.voice ?? new TestVoicePlugin();
  const coordinator = options.coordinator ?? new SessionCoordinator();
  const resolver = new MediaResolver([sourceEntry(source)]);
  const clock = new PlaybackClock(new FakeMonotonicClock());
  const onNotification = vi.fn<NotificationHandler>();
  return {
    source,
    voice,
    coordinator,
    resolver,
    clock,
    onNotification,
    engine: new PlaybackEngine({
      voice: voice.voice,
      resolver,
      operations: coordinator,
      clock,
      onNotification,
    }),
  };
}

describe("PlaybackEngine", () => {
  it("owns the active subscription until finish and then rejects repeated or stale completion", async () => {
    const fixture = engineFixture();
    const song = await resolvedSong(fixture.resolver, "first");

    expect(fixture.engine.replacementPolicy).toBe("backend-atomic-replace");
    expect(fixture.engine.activeSong).toBeUndefined();

    const outcome = await fixture.engine.activate(song, connection);
    if (outcome.kind !== "activated") throw new Error("Expected playback activation");

    expect(fixture.engine.activeSong).toBe(song);
    expect(fixture.engine.isCurrent(outcome.active)).toBe(true);
    expect(outcome.active.signal.aborted).toBe(false);
    expect(fixture.clock.state).toBe("playing");

    fixture.voice.currentPlaybackNotify?.({ type: "finish" });
    expect(fixture.onNotification).toHaveBeenCalledWith(outcome.active, { type: "finish" });

    await expect(fixture.engine.finish(outcome.active)).resolves.toBe(true);
    expect(fixture.engine.activeSong).toBeUndefined();
    expect(fixture.engine.isCurrent(outcome.active)).toBe(false);
    expect(outcome.active.signal.aborted).toBe(true);
    expect(fixture.clock.state).toBe("finished");
    await expect(fixture.engine.finish(outcome.active)).resolves.toBe(false);
    expect((fixture.source as TestSourcePlugin).disposed).toEqual(["search:first"]);
  });

  it("aborts and disposes the replaced generation before accepting only current notifications", async () => {
    const fixture = engineFixture();
    const first = await resolvedSong(fixture.resolver, "first");
    const second = await resolvedSong(fixture.resolver, "second");
    const firstOutcome = await fixture.engine.activate(first, connection);
    if (firstOutcome.kind !== "activated") throw new Error("Expected first playback activation");
    const firstNotify = fixture.voice.playbackNotifies.at(-1);

    const secondOutcome = await fixture.engine.activate(second, connection);
    if (secondOutcome.kind !== "activated") throw new Error("Expected replacement playback activation");

    expect(secondOutcome.replaced).toBe(first);
    expect(firstOutcome.active.signal.aborted).toBe(true);
    expect(fixture.engine.isCurrent(firstOutcome.active)).toBe(false);
    expect(fixture.engine.isCurrent(secondOutcome.active)).toBe(true);
    expect((fixture.source as TestSourcePlugin).disposed).toEqual(["search:first"]);

    firstNotify?.({ type: "error", error: new Error("stale") });
    fixture.voice.currentPlaybackNotify?.({ type: "error", error: new Error("current") });
    expect(fixture.onNotification).toHaveBeenCalledTimes(1);
    expect(fixture.onNotification.mock.calls[0]?.[0]).toBe(secondOutcome.active);
  });

  it("returns stale and disposes the candidate when command authority ends before or after backend play", async () => {
    const beforePlayCoordinator = new SessionCoordinator();
    const beforePlayVoice = new TestVoicePlugin();
    const originalPrepare = beforePlayVoice.voice.prepare.bind(beforePlayVoice.voice);
    const beforePlay = engineFixture({ voice: beforePlayVoice, coordinator: beforePlayCoordinator });
    const beforePlayEngine = new PlaybackEngine({
      voice: {
        ...beforePlayVoice.voice,
        prepare: async request => {
          const prepared = await originalPrepare(request);
          beforePlayCoordinator.invalidate("playback");
          return prepared;
        },
      },
      resolver: beforePlay.resolver,
      operations: beforePlayCoordinator,
      clock: beforePlay.clock,
      onNotification: beforePlay.onNotification,
    });
    const first = await resolvedSong(beforePlay.resolver, "before-play");

    await expect(beforePlayEngine.activate(first, connection)).resolves.toEqual({ kind: "stale" });
    expect(beforePlayVoice.calls.some(call => call.startsWith("play:"))).toBe(false);
    expect((beforePlay.source as TestSourcePlugin).disposed).toEqual(["search:before-play"]);

    const afterPlayCoordinator = new SessionCoordinator();
    const afterPlayVoice = new TestVoicePlugin();
    const originalPlay = afterPlayVoice.voice.play.bind(afterPlayVoice.voice);
    const afterPlay = engineFixture({ voice: afterPlayVoice, coordinator: afterPlayCoordinator });
    const afterPlayEngine = new PlaybackEngine({
      voice: {
        ...afterPlayVoice.voice,
        play: request => {
          originalPlay(request);
          afterPlayCoordinator.invalidate("playback");
        },
      },
      resolver: afterPlay.resolver,
      operations: afterPlayCoordinator,
      clock: afterPlay.clock,
      onNotification: afterPlay.onNotification,
    });
    const second = await resolvedSong(afterPlay.resolver, "after-play");

    await expect(afterPlayEngine.activate(second, connection)).resolves.toEqual({ kind: "stale" });
    expect(afterPlayVoice.calls).toContain("play:test:search:after-play");
    expect((afterPlay.source as TestSourcePlugin).disposed).toEqual(["search:after-play"]);
  });

  it("aggregates backend and owned-resource cleanup failures while clearing active authority", async () => {
    const backendFailure = new Error("backend stop failed");
    const resourceFailure = new Error("lease disposal failed");
    class FailingResourceSource extends DisTubePlugin {
      override readonly id = "failing-resource";
      override readonly source: SourceCapability = {
        searchSong: query => new Song({ source: "failing", id: query }),
        getStream: () => new StreamLease({ url: "https://cdn.example/failing" }, () => Promise.reject(resourceFailure)),
      };
    }
    const voice = new TestVoicePlugin();
    const originalVoice = voice.voice;
    const source = new FailingResourceSource();
    const resolver = new MediaResolver([sourceEntry(source)]);
    const coordinator = new SessionCoordinator();
    const engine = new PlaybackEngine({
      voice: {
        ...originalVoice,
        stop: () => Promise.reject(backendFailure),
      },
      resolver,
      operations: coordinator,
      clock: new PlaybackClock(new FakeMonotonicClock()),
      onNotification: vi.fn(),
    });
    const song = await resolvedSong(resolver, "failure");
    const outcome = await engine.activate(song, connection);
    if (outcome.kind !== "activated") throw new Error("Expected playback activation");

    const cleanupError = await engine.stop(connection).catch(cause => cause);
    expect(cleanupError).toBeInstanceOf(AggregateError);
    expect(cleanupError).toMatchObject({ message: "Playback cleanup failed" });
    expect((cleanupError as AggregateError).errors[0]).toBe(backendFailure);
    expect((cleanupError as AggregateError).errors[1]).toEqual(
      new AggregateError([resourceFailure], "StreamLease cleanup failed"),
    );
    expect(engine.activeSong).toBeUndefined();
    expect(outcome.active.signal.aborted).toBe(true);
    await expect(engine.disposeActive()).resolves.toEqual([]);
  });
});

