import { describe, expect, it, vi } from "vitest";
import { SystemMonotonicClock, SystemScheduler } from "@/runtime/Scheduler";
import { DeterministicScheduler, FakeMonotonicClock } from "./DeterministicScheduler";

describe("DeterministicScheduler", () => {
  it("drains commit and publication phases independently", () => {
    const scheduler = new DeterministicScheduler();
    const calls: string[] = [];
    scheduler.schedule("publication", () => calls.push("published"));
    scheduler.schedule("commit", () => calls.push("committed"));

    expect(scheduler.drain("commit")).toBe(1);
    expect(calls).toEqual(["committed"]);
    expect(scheduler.drain("publication")).toBe(1);
    expect(calls).toEqual(["committed", "published"]);
  });

  it("advances explicit timeout and playback-time phases", () => {
    const scheduler = new DeterministicScheduler();
    const timeout = vi.fn();
    scheduler.schedule("timeout", timeout, 50);

    expect(scheduler.advanceTimeoutBy(49)).toBe(0);
    expect(timeout).not.toHaveBeenCalled();
    expect(scheduler.advanceTimeoutBy(1)).toBe(1);
    expect(timeout).toHaveBeenCalledOnce();

    scheduler.advancePlaybackTimeBy(25);
    expect(scheduler.clock.now()).toBe(75);
  });

  it("cancels a pending task exactly once", () => {
    const scheduler = new DeterministicScheduler();
    const task = vi.fn();
    const scheduled = scheduler.schedule("commit", task);
    scheduled.cancel();
    scheduled.cancel();

    expect(scheduler.drain("commit")).toBe(0);
    expect(task).not.toHaveBeenCalled();
  });
});

describe("FakeMonotonicClock", () => {
  it("rejects backwards and non-finite movement", () => {
    const clock = new FakeMonotonicClock();
    expect(() => clock.advanceBy(-1)).toThrow(RangeError);
    expect(() => clock.advanceBy(Number.NaN)).toThrow(RangeError);
  });
});

describe("system scheduling ports", () => {
  it("uses monotonic host time", () => {
    const clock = new SystemMonotonicClock();
    expect(clock.now()).toBeGreaterThanOrEqual(0);
  });

  it("runs and cancels microtask phases", async () => {
    const scheduler = new SystemScheduler();
    const executed = vi.fn();
    const cancelled = vi.fn();
    scheduler.schedule("commit", executed);
    scheduler.schedule("publication", cancelled).cancel();
    await Promise.resolve();
    expect(executed).toHaveBeenCalledOnce();
    expect(cancelled).not.toHaveBeenCalled();
  });

  it("runs and cancels explicit timeout phases", async () => {
    vi.useFakeTimers();
    const scheduler = new SystemScheduler();
    const executed = vi.fn();
    const cancelled = vi.fn();
    scheduler.schedule("timeout", executed, 10);
    scheduler.schedule("timeout", cancelled, 10).cancel();
    await vi.advanceTimersByTimeAsync(10);
    expect(executed).toHaveBeenCalledOnce();
    expect(cancelled).not.toHaveBeenCalled();
    vi.useRealTimers();
  });
});

tests/media/MediaResolver.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import { Playlist, Song } from "@";
import { MediaResolver } from "@/media/MediaResolver";
import { DisTubePlugin, type SourceCapability, StreamLease } from "@/plugin";
import type { SourceEntry } from "@/plugins/PluginGraph";

class SourcePlugin extends DisTubePlugin {
  readonly calls: string[] = [];

  constructor(
    override readonly id: string,
    override readonly source: SourceCapability,
  ) {
    super();
  }
}

function entry(plugin: SourcePlugin): SourceEntry {
  return { plugin, source: plugin.source };
}

function signal(): AbortSignal {
  return new AbortController().signal;
}

describe("MediaResolver provenance", () => {
  it("preserves per-child ownership for a mixed custom Playlist", async () => {
    const first = new SourcePlugin("first", {
      resolve: input => (input === "first" ? new Song({ source: "one", id: input }) : undefined),
    });
    const second = new SourcePlugin("second", {
      resolve: input => (input === "second" ? new Song({ source: "two", id: input }) : undefined),
    });
    const firstEntry = entry(first);
    const secondEntry = entry(second);
    const resolver = new MediaResolver([firstEntry, secondEntry]);
    const firstSong = (await resolver.resolve("first", undefined, signal())) as Song;
    const secondSong = (await resolver.resolve("second", undefined, signal())) as Song;

    const playlist = Playlist.from([firstSong, secondSong]);
    const resolved = (await resolver.resolve(playlist, undefined, signal())) as Playlist;

    expect(resolved.songs).toEqual([firstSong, secondSong]);
    expect(resolver.ownerOf(firstSong)).toBe(firstEntry);
    expect(resolver.ownerOf(secondSong)).toBe(secondEntry);
  });

  it("transfers provenance when metadata creates a new Song value", async () => {
    const source = new SourcePlugin("source", {
      resolve: () => new Song({ source: "provider", id: "track", sourceData: { opaque: true } }),
    });
    const sourceEntry = entry(source);
    const resolver = new MediaResolver<{ request: string }>([sourceEntry]);
    const metadata = { request: "request-1" };

    const song = (await resolver.resolve("track", metadata, signal())) as Song<{ request: string }>;

    expect(song.metadata).toBe(metadata);
    expect(resolver.ownerOf(song)).toBe(sourceEntry);
    expect(resolver.provenanceOf(song).mediaOrigin).toBe("provider");
  });

  it("visits each fallback source at most once across multiple attempts", async () => {
    const originalSource = new SourcePlugin("original", {});
    const passing = new SourcePlugin("passing", { searchSong: () => undefined });
    const handling = new SourcePlugin("handling", {
      searchSong: query => new Song({ source: "fallback", id: query }),
    });
    const originalEntry = entry(originalSource);
    const passingEntry = entry(passing);
    const handlingEntry = entry(handling);
    const resolver = new MediaResolver([originalEntry, passingEntry, handlingEntry]);
    const original = new Song({ source: "original", id: "original" });

    const fallback = await resolver.searchFallback("query", signal(), new Set([originalEntry]), original);
    const exhausted = await resolver.searchFallback("query", signal(), new Set([originalEntry]), original);

    expect(fallback?.source).toBe(handlingEntry);
    expect(exhausted).toBeUndefined();
    expect(resolver.provenanceOf(original).visitedSources).toEqual([originalEntry, passingEntry, handlingEntry]);
    expect(resolver.provenanceOf(original).fallbackSurrogates).toEqual([fallback?.song]);
  });

  it("separates abort from provider failure and ignores a late result", async () => {
    let release: ((song: Song) => void) | undefined;
    const source = new SourcePlugin("late", {
      resolve: () => new Promise<Song>(resolve => (release = resolve)),
    });
    const controller = new AbortController();
    const resolver = new MediaResolver([entry(source)]);
    const pending = resolver.resolve("late", undefined, controller.signal);

    controller.abort(new DOMException("cancelled", "AbortError"));
    release?.(new Song({ source: "late", id: "late" }));

    await expect(pending).rejects.toMatchObject({ name: "AbortError" });
  });

  it("stops selected-provider routing and preserves operational failure", async () => {
    const cause = new Error("provider failed");
    const later = vi.fn(() => new Song({ source: "later", id: "later" }));
    const failing = new SourcePlugin("failing", { resolve: () => Promise.reject(cause) });
    const next = new SourcePlugin("next", { resolve: later });
    const resolver = new MediaResolver([entry(failing), entry(next)]);

    await expect(resolver.resolve("track", undefined, signal())).rejects.toMatchObject({
      code: "MEDIA_RESOLUTION_FAILED",
      cause,
    });
    expect(later).not.toHaveBeenCalled();
  });

  it("preserves a fallback provider failure instead of reporting exhaustion", async () => {
    const cause = new Error("fallback failed");
    const failing = new SourcePlugin("failing", { searchSong: () => Promise.reject(cause) });
    const failingEntry = entry(failing);
    const resolver = new MediaResolver([failingEntry]);

    await expect(resolver.searchFallback("query", signal(), new Set())).rejects.toMatchObject({
      code: "MEDIA_RESOLUTION_FAILED",
      cause,
    });
  });

  it("continues related lookup after provider failure and reports failed exhaustion", async () => {
    const errors: Error[] = [];
    const failing = new SourcePlugin("failing", {
      resolve: () => new Song({ source: "failing", id: "track" }),
      getRelatedSong: () => Promise.reject(new Error("related failed")),
    });
    const passing = new SourcePlugin("passing", { getRelatedSong: () => undefined });
    const resolver = new MediaResolver([entry(failing), entry(passing)]);
    const song = (await resolver.resolve("track", undefined, signal())) as Song;

    const result = await resolver.getRelated(song, signal(), error => errors.push(error));

    expect(result).toEqual({ hadError: true });
    expect(errors).toHaveLength(1);
  });

  it("attaches caller metadata and returning-source provenance to related media", async () => {
    const metadata = { request: "related" };
    const owner = new SourcePlugin("owner", {
      resolve: () => new Song({ source: "owner", id: "track" }),
      getRelatedSong: () => new Song({ source: "owner", id: "related" }),
    });
    const ownerEntry = entry(owner);
    const resolver = new MediaResolver<{ request: string }>([ownerEntry]);
    const song = (await resolver.resolve("track", metadata, signal())) as Song<{ request: string }>;

    const result = await resolver.getRelated(song, signal(), vi.fn());

    expect(result.song?.metadata).toBe(metadata);
    expect(result.song && resolver.ownerOf(result.song)).toBe(ownerEntry);
  });

  it("transfers fallback resource ownership while retaining original Song identity", async () => {
    const originalSource = new SourcePlugin("original", {
      resolve: () => new Song({ source: "original", id: "original" }),
    });
    const fallbackSource = new SourcePlugin("fallback", {
      searchSong: () => new Song({ source: "fallback", id: "surrogate" }),
      getStream: song => new StreamLease({ owner: song.source }),
    });
    const originalEntry = entry(originalSource);
    const fallbackEntry = entry(fallbackSource);
    const resolver = new MediaResolver([originalEntry, fallbackEntry]);
    const original = (await resolver.resolve("track", undefined, signal())) as Song;
    const fallback = await resolver.searchFallback("query", signal(), new Set([originalEntry]), original);
    if (!fallback) throw new Error("Expected a fallback Song");

    resolver.associatePlayback(original, fallback.song);
    const lease = await resolver.getStream(original, signal());

    expect(original.source).toBe("original");
    expect(lease?.value).toEqual({ owner: "original" });
    expect(resolver.provenanceOf(original).resourceOwner).toBe(fallbackEntry);
  });
});

