import { describe, expect, it, vi } from "vitest";
import { SessionCoordinator } from "@/session/SessionCoordinator";

describe("SessionCoordinator", () => {
  it("prepares structural work concurrently and terminates commits in invocation order", async () => {
    const coordinator = new SessionCoordinator();
    const first = coordinator.reserveStructural();
    const second = coordinator.reserveStructural();
    const order: string[] = [];
    let releaseFirst: (() => void) | undefined;
    const firstTerminal = first.run(async () => {
      await new Promise<void>(resolve => (releaseFirst = resolve));
      order.push("first");
    });
    const secondTerminal = second.run(async () => order.push("second"));

    await Promise.resolve();
    expect(order).toEqual([]);
    releaseFirst?.();
    await Promise.all([firstTerminal, secondTerminal]);

    expect(order).toEqual(["first", "second"]);
  });

  it("releases a failed structural slot exactly once", async () => {
    const coordinator = new SessionCoordinator();
    const first = coordinator.reserveStructural();
    const second = coordinator.reserveStructural();
    const cause = new Error("failed");
    first.cancel(cause);

    await expect(first.run(async () => undefined)).rejects.toBe(cause);
    await expect(second.run(async () => "next")).resolves.toBe("next");
  });

  it("lets responsive synchronous commits progress while structural preparation is pending", async () => {
    const coordinator = new SessionCoordinator();
    const slot = coordinator.reserveStructural();
    let release: (() => void) | undefined;
    const structural = slot.run(() => new Promise<void>(resolve => (release = resolve)));

    const responsive = await coordinator.commit({ name: "volume", commit: () => 25 });

    expect(responsive.result).toBe(25);
    release?.();
    await structural;
  });

  it("rejects asynchronous work from a transactional commit callback", async () => {
    const coordinator = new SessionCoordinator();

    await expect(
      coordinator.commit({ name: "invalid", commit: () => Promise.resolve("integration I/O") }),
    ).rejects.toThrow("returned asynchronous work");
  });

  it("validates and commits in one synchronous transaction turn", async () => {
    const coordinator = new SessionCoordinator();
    const order: string[] = [];

    const record = await coordinator.commit({
      name: "validated",
      validate: () => {
        order.push("validate");
      },
      commit: () => {
        order.push("commit");
        return 42;
      },
    });

    expect(order).toEqual(["validate", "commit"]);
    expect(record.result).toBe(42);
  });

  it("makes command authority terminal when the operation completes", () => {
    const coordinator = new SessionCoordinator();
    const operation = coordinator.begin("voice");

    expect(operation.isCurrent()).toBe(true);
    operation.complete();

    expect(operation.isCurrent()).toBe(false);
    expect(operation.signal.aborted).toBe(false);
  });

  it("invalidates stale operations without affecting another coordinator", () => {
    const firstGuild = new SessionCoordinator();
    const secondGuild = new SessionCoordinator();
    const stale = firstGuild.begin("queue");
    const independent = secondGuild.begin("queue");
    const abort = vi.fn();
    stale.signal.addEventListener("abort", abort);

    firstGuild.invalidate("queue");

    expect(stale.isCurrent()).toBe(false);
    expect(abort).toHaveBeenCalledOnce();
    expect(independent.isCurrent()).toBe(true);
  });
});

