import { describe, expect, it, vi } from "vitest";
import { ResourceScope } from "@/resources/ResourceScope";
import { ResourceFault } from "../support/FaultFixtures";

describe("ResourceScope", () => {
  it("memoizes disposal before a synchronous disposer throws", async () => {
    const scope = new ResourceScope("candidate");
    const resource = new ResourceFault("lease", "sync-throw");
    scope.register("lease", resource.dispose);

    const first = scope.dispose();
    const second = scope.dispose();
    expect(second).toBe(first);
    await expect(first).resolves.toMatchObject({
      scope: "candidate",
      records: [{ name: "lease", status: "failed", error: resource.error }],
      errors: [resource.error],
    });
    expect(resource.disposeCalls).toBe(1);
  });

  it("disposes named resources in reverse ownership order and continues after failure", async () => {
    const calls: string[] = [];
    const scope = new ResourceScope("active");
    scope.register("first", () => {
      calls.push("first");
    });
    scope.register("failed", () => {
      calls.push("failed");
      throw new Error("failed");
    });
    scope.register("last", () => {
      calls.push("last");
    });

    const result = await scope.dispose();
    expect(calls).toEqual(["last", "failed", "first"]);
    expect(result.records.map(record => record.status)).toEqual(["disposed", "failed", "disposed"]);
  });

  it("transfers candidate ownership and supports child scopes", async () => {
    const disposer = vi.fn();
    const candidate = new ResourceScope("candidate");
    const child = candidate.child("stream");
    child.register("lease", disposer);
    const active = new ResourceScope("active");
    candidate.transferTo(active);

    expect(() => candidate.register("late", disposer)).toThrow("transferred");
    await expect(candidate.dispose()).resolves.toMatchObject({ records: [] });
    expect(disposer).not.toHaveBeenCalled();
    await active.dispose();
    expect(disposer).toHaveBeenCalledOnce();
  });

  it("rejects duplicate names without partially transferring", async () => {
    const sourceDispose = vi.fn();
    const targetDispose = vi.fn();
    const source = new ResourceScope("source");
    const target = new ResourceScope("target");
    source.register("same", sourceDispose);
    target.register("same", targetDispose);
    expect(() => source.transferTo(target)).toThrow("Duplicate resource");

    await source.dispose();
    await target.dispose();
    expect(sourceDispose).toHaveBeenCalledOnce();
    expect(targetDispose).toHaveBeenCalledOnce();
  });

  it("memoizes asynchronous disposal failure and repeated cleanup", async () => {
    const failure = new Error("async failure");
    const dispose = vi.fn(() => Promise.reject(failure));
    const scope = new ResourceScope("async");
    scope.register("resource", dispose);

    const first = scope.dispose();
    const second = scope.dispose();

    expect(second).toBe(first);
    await expect(first).resolves.toMatchObject({
      records: [{ name: "resource", status: "failed", error: failure }],
      errors: [failure],
    });
    expect(dispose).toHaveBeenCalledOnce();
  });
});

