import { describe, expect, it, vi } from "vitest";
import { DISTUBE_ERROR_CATALOG, DisTubeError, Playlist, Song } from "@";
import { StreamLease } from "@/plugin";

describe("v6 public values", () => {
  it("shallow-freezes Song while preserving opaque references", () => {
    const metadata = { interaction: { id: "one" } };
    const sourceData = { views: 42 };
    const song = new Song({ source: "Test", id: "song", duration: 30, metadata, sourceData });

    expect(Object.isFrozen(song)).toBe(true);
    expect(song.source).toBe("test");
    expect(song.metadata).toBe(metadata);
    expect(song.sourceData).toBe(sourceData);
    expect("member" in song).toBe(false);
    expect("requester" in song).toBe(false);
  });

  it("creates non-empty immutable playlists from existing Song references", () => {
    const firstSourceData = { provider: "first" };
    const secondSourceData = new Map([["provider", "second"]]);
    const first = new Song({ source: "first", id: "one", duration: 30, sourceData: firstSourceData });
    const second = new Song({ source: "second", id: "two", duration: 15, sourceData: secondSourceData });
    const playlist = Playlist.from([first, second], { name: "List" });

    expect(Object.isFrozen(playlist)).toBe(true);
    expect(Object.isFrozen(playlist.songs)).toBe(true);
    expect(playlist.songs).toEqual([first, second]);
    expect(playlist.songs[0]?.sourceData).toBe(firstSourceData);
    expect(playlist.songs[1]?.sourceData).toBe(secondSourceData);
    expect(() => Playlist.from([])).toThrow(DisTubeError);
    expect(() => Playlist.from([{} as Song])).toThrow(DisTubeError);
  });

  it("copies only explicitly replaced opaque values", () => {
    const metadata = { request: "old" };
    const replacement = { request: "new" };
    const sourceData = { provider: true };
    const song = new Song({ source: "test", id: "song", metadata, sourceData });
    const copy = song.withMetadata(replacement);

    expect(copy).not.toBe(song);
    expect(copy.metadata).toBe(replacement);
    expect(copy.sourceData).toBe(sourceData);
    expect(Object.isFrozen(metadata)).toBe(false);
    expect(Object.isFrozen(sourceData)).toBe(false);
  });

  it("normalizes invalid duration values without reading runtime state", () => {
    expect(new Song({ source: "test", duration: Number.NaN }).duration).toBe(0);
    expect(new Song({ source: "test", duration: Number.POSITIVE_INFINITY }).formattedDuration).toBe("00:00");
  });

  it("disposes opaque StreamLease cleanup once and preserves cleanup errors", async () => {
    const cleanup = vi.fn(async () => {});
    const lease = new StreamLease({ url: "https://example.com" }, cleanup);

    await Promise.all([lease.dispose(), lease.dispose()]);
    expect(lease.isDisposed).toBe(true);
    expect(cleanup).toHaveBeenCalledOnce();

    const failure = new Error("sync cleanup");
    const failingCleanup = vi.fn(() => {
      throw failure;
    });
    const failing = new StreamLease("value", failingCleanup);
    const first = failing.dispose();
    const second = failing.dispose();
    expect(second).toBe(first);
    await expect(first).rejects.toEqual(new AggregateError([failure], "StreamLease cleanup failed"));
    expect(failingCleanup).toHaveBeenCalledOnce();
  });

  it("exposes semantic error code, context, and cause", () => {
    const cause = new Error("provider");
    const error = new DisTubeError("PLAYBACK_FAILED", { cause, context: { song: "one" } });

    expect(error.code).toBe("PLAYBACK_FAILED");
    expect(error.errorCode).toBe("PLAYBACK_FAILED");
    expect(error.category).toBe("playback");
    expect(error.context).toEqual({ song: "one" });
    expect(error.cause).toBe(cause);
    expect(DISTUBE_ERROR_CATALOG.PLAYBACK_FAILED.cause).toBe("optional");
    expect(Object.keys(DISTUBE_ERROR_CATALOG)).toHaveLength(23);
    expect(DISTUBE_ERROR_CATALOG).not.toHaveProperty("PAUSED");
    expect(DISTUBE_ERROR_CATALOG).not.toHaveProperty("RESUMED");
    expect(DISTUBE_ERROR_CATALOG).not.toHaveProperty("FILTER_INACTIVE");
  });
});

