import { describe, expect, it, vi } from "vitest";
import { CleanupPlan } from "@/resources/CleanupPlan";
import { DeterministicScheduler } from "../support/DeterministicScheduler";

describe("CleanupPlan", () => {
  it("runs flat units in order and memoizes the terminal result", async () => {
    const scheduler = new DeterministicScheduler();
    const plan = new CleanupPlan(scheduler, 100);
    const calls: string[] = [];
    plan.add({
      name: "playback",
      run: () => {
        calls.push("playback");
      },
    });
    plan.add({
      name: "connection",
      run: async () => {
        calls.push("connection");
      },
    });

    const first = plan.run();
    const second = plan.run();
    expect(second).toBe(first);
    await expect(first).resolves.toMatchObject({ records: [{ status: "success" }, { status: "success" }] });
    expect(calls).toEqual(["playback", "connection"]);
  });

  it("records synchronous failure, asynchronous rejection, and continues", async () => {
    const plan = new CleanupPlan(new DeterministicScheduler(), 100);
    const later = vi.fn();
    plan.add({
      name: "sync",
      run: () => {
        throw new Error("sync");
      },
    });
    plan.add({ name: "async", run: () => Promise.reject(new Error("async")) });
    plan.add({ name: "later", run: later });

    const result = await plan.run();
    expect(result.records.map(record => record.status)).toEqual(["failure", "failure", "success"]);
    expect(result.error).toMatchObject({ code: "CLEANUP_FAILED" });
    expect(later).toHaveBeenCalledOnce();
  });

  it("detaches a hanging unit at its deadline and runs later units", async () => {
    const scheduler = new DeterministicScheduler();
    const plan = new CleanupPlan(scheduler, 50);
    const later = vi.fn();
    plan.add({ name: "hang", run: () => new Promise<void>(() => {}) });
    plan.add({ name: "later", run: later });
    const running = plan.run();
    await Promise.resolve();
    scheduler.advanceTimeoutBy(50);
    const result = await running;

    expect(result.records).toEqual([
      { name: "hang", status: "timeout", deadlineMs: 50 },
      { name: "later", status: "success" },
    ]);
    expect(later).toHaveBeenCalledOnce();
  });
});

