import { describe, expect, it, vi } from "vitest";
import type { QueueSnapshot, VoiceSnapshot } from "@/api/snapshots";
import {
  DisTubeEvent,
  QueueAddReason,
  QueueDeleteReason,
  QueuePlacement,
  QueueSkipBehavior,
  RepeatMode,
  VoiceChangeReason,
  VoiceDisconnectReason,
} from "@/enums";
import { EventJournal } from "@/events/EventJournal";
import type { EmptyFilterCatalog, FilterState } from "@/filters/contracts";
import type { FilterMutation } from "@/filters/FilterEngine";
import { Song } from "@/media/Song";
import { Queue } from "@/queue/Queue";
import { QueueAggregate } from "@/queue/QueueAggregate";
import { SessionCoordinator } from "@/session/SessionCoordinator";
