describe("SessionEvents", () => {
  it("maps Queue intents to revisioned records without publishing inside the commit turn", async () => {
    const scheduler = new DeterministicScheduler();
    const publish = vi.fn();
    const journal = new EventJournal<unknown, EmptyFilterCatalog>(scheduler, publish);
    const events = new SessionEvents({ guildId, journal, isActive: () => true });
    const coordinator = new SessionCoordinator();
    const aggregate = new QueueAggregate({
      guildId,
      historyLimit: 10,
      repeatMode: RepeatMode.OFF,
      autoplay: false,
      volume: 100,
      filters,
    });
    const port = new QueueEventPort(aggregate.snapshot());
    const queue = new Queue(guildId, filters, port);
    const song = new Song({ source: "test", id: "first", duration: 1 });

    const record = await coordinator.commit({
      name: "queueEvents",
      commit: () => {
        const commit = aggregate.execute({
          type: "add",
          media: song,
          reason: QueueAddReason.PLAY,
          placement: QueuePlacement.APPEND,
          replace: false,
          skipBehavior: QueueSkipBehavior.HISTORY,
        });
        port.update(commit.newSnapshot);
        events.queue(queue, commit, 7);
        return commit;
      },
    });

    expect(publish).not.toHaveBeenCalled();
    expect(
      journal
        .pending(guildId)
        .map(event => [event.event, event.aggregateRevision, event.correlation, event.generation]),
    ).toEqual([
      [DisTubeEvent.INIT_QUEUE, record.result.revision, "command", 7],
      [DisTubeEvent.ADD_SONG, record.result.revision, "command", 7],
      [DisTubeEvent.PLAY_SONG, record.result.revision, "playback", 7],
    ]);
    scheduler.drain("publication");
    expect(publish).toHaveBeenCalledTimes(3);
  });

  it("maps Queue deletion, voice transitions, and diagnostics to their correlation categories", () => {
    const scheduler = new DeterministicScheduler();
    const journal = new EventJournal<unknown, EmptyFilterCatalog>(scheduler, () => undefined);
    const events = new SessionEvents({ guildId, journal, isActive: () => true });
    const aggregate = new QueueAggregate({
      guildId,
      historyLimit: 10,
      repeatMode: RepeatMode.OFF,
      autoplay: false,
      volume: 100,
      filters,
    });
    const queuePort = new QueueEventPort(aggregate.snapshot());
    const queue = new Queue(guildId, filters, queuePort);
    const deleted = aggregate.execute({ type: "destroy", reason: QueueDeleteReason.STOPPED });
    queuePort.update(deleted.newSnapshot);
    events.queue(queue, deleted, 2);

    const voiceAggregate = new VoiceAggregate(guildId);
    const connected = voiceAggregate.execute({
      type: "connect",
      channelId: "200000000000000001",
      selfMute: false,
      selfDeaf: true,
    });
    const voicePort = new VoiceEventPort(connected.newSnapshot);
    const voice = new VoiceSession(guildId, voicePort);
    events.voiceConnect(voice, connected.newSnapshot, 3);
    const changed = voiceAggregate.execute({ type: "change", reason: VoiceChangeReason.SELF_MUTE, selfMute: true });
    voicePort.update(changed.newSnapshot);
    events.voice(voice, changed, 3);
    const disconnected = voiceAggregate.execute({ type: "disconnect", reason: VoiceDisconnectReason.LEFT });
    voicePort.update(disconnected.newSnapshot);
    events.voice(voice, disconnected, 3);
    events.error(new Error("background"), queue, undefined, 2);

    expect(journal.pending(guildId).map(event => [event.event, event.correlation, event.aggregateRevision])).toEqual([
      [DisTubeEvent.DELETE_QUEUE, "lifecycle", deleted.revision],
      [DisTubeEvent.VOICE_CONNECT, "connection", connected.newSnapshot.revision],
      [DisTubeEvent.VOICE_CHANGE, "connection", changed.newSnapshot.revision],
      [DisTubeEvent.VOICE_DISCONNECT, "lifecycle", disconnected.newSnapshot.revision],
      [DisTubeEvent.ERROR, "diagnostic", deleted.newSnapshot.revision],
    ]);
  });
});

