import { describe, expect, it, vi } from "vitest";
import { RepeatMode } from "@";
import { compileRuntimeConfiguration } from "@/runtime/RuntimeConfiguration";
import type { DisTubeOptions } from "@/types/options";
import { TestAdapter, TestVoicePlugin } from "../support";

function options(overrides: Readonly<Record<string, unknown>> = {}): DisTubeOptions<TestAdapter, TestVoicePlugin> {
  return { adapter: new TestAdapter(), voice: new TestVoicePlugin(), ...overrides } as DisTubeOptions<
    TestAdapter,
    TestVoicePlugin
  >;
}

describe("compileRuntimeConfiguration", () => {
  it("compiles defaults and deeply immutable shared values", () => {
    const custom = {
      defaults: { level: 1 },
      parameters: { level: { default: 1, min: 0, max: 2 } },
    };
    const voice = new TestVoicePlugin();
    Object.defineProperty(voice.voice, "filters", { value: { custom } });
    const validateInput = vi.fn();
    const raw = options({ voice, policies: { validateInput } });
    const configuration = compileRuntimeConfiguration(raw);
    const filters = configuration.filters as typeof configuration.filters & { readonly custom: typeof custom };

    expect(configuration.queueDefaults).toEqual({
      volume: 100,
      autoplay: false,
      repeatMode: RepeatMode.OFF,
      historyLimit: 50,
    });
    expect(configuration.voiceDefaults).toEqual({ selfDeaf: true, selfMute: false });
    expect(configuration.cleanupTimeoutMs).toBe(10_000);
    expect(configuration.policies?.validateInput).toBe(validateInput);
    expect(Object.isFrozen(configuration)).toBe(true);
    expect(Object.isFrozen(configuration.filters)).toBe(true);
    expect(Object.isFrozen(filters.custom)).toBe(true);
    expect(Object.isFrozen(filters.custom.parameters)).toBe(true);

    custom.defaults.level = 2;
    expect(filters.custom.defaults?.level).toBe(1);
  });

  it("rejects exact unknown root and nested keys with paths", () => {
    expect(() => compileRuntimeConfiguration(options({ typo: true }))).toThrowError(
      expect.objectContaining({
        code: "INVALID_OPTIONS",
        context: { path: "typo", reason: "unknownKey", value: true },
      }),
    );
    expect(() => compileRuntimeConfiguration(options({ filters: {} }))).toThrowError(
      expect.objectContaining({
        code: "INVALID_OPTIONS",
        context: { path: "filters", reason: "unknownKey", value: {} },
      }),
    );
    expect(() => compileRuntimeConfiguration(options({ queueDefaults: { volume: 10, typo: true } }))).toThrowError(
      expect.objectContaining({
        code: "INVALID_OPTIONS",
        context: { path: "queueDefaults.typo", reason: "unknownKey", value: true },
      }),
    );
  });

  it("rejects invalid defaults, policies, and cleanup limits", () => {
    expect(() => compileRuntimeConfiguration(options({ queueDefaults: { repeatMode: "invalid" } }))).toThrowError(
      expect.objectContaining({
        context: expect.objectContaining({ path: "queueDefaults.repeatMode", reason: "unknownRepeatMode" }),
      }),
    );
    expect(() => compileRuntimeConfiguration(options({ policies: { validateInput: true } }))).toThrowError(
      expect.objectContaining({
        context: expect.objectContaining({ path: "policies.validateInput", reason: "expectedFunction" }),
      }),
    );
    expect(() => compileRuntimeConfiguration(options({ cleanupTimeoutMs: 0 }))).toThrowError(
      expect.objectContaining({
        context: expect.objectContaining({ path: "cleanupTimeoutMs", reason: "expectedPositiveFiniteNumber" }),
      }),
    );
  });

  it("rejects malformed filter definitions before runtime initialization", () => {
    const voiceWith = (filters: Readonly<Record<string, unknown>>): TestVoicePlugin => {
      const voice = new TestVoicePlugin();
      Object.defineProperty(voice.voice, "filters", { value: filters });
      return voice;
    };
    expect(() =>
      compileRuntimeConfiguration(
        options({
          voice: voiceWith({ gain: { defaults: { level: 3 }, parameters: { level: { min: 0, max: 2 } } } }),
        }),
      ),
    ).toThrowError(
      expect.objectContaining({
        context: { path: "voice.voice.filters.gain.defaults.level", reason: "aboveMax", value: 3 },
      }),
    );
    expect(() =>
      compileRuntimeConfiguration(
        options({ voice: voiceWith({ gain: { parameters: { level: { validate: "yes" } } } }) }),
      ),
    ).toThrowError(
      expect.objectContaining({
        context: {
          path: "voice.voice.filters.gain.parameters.level.validate",
          reason: "expectedFunction",
          value: "yes",
        },
      }),
    );
    expect(() =>
      compileRuntimeConfiguration(
        options({ voice: voiceWith({ gain: { defaults: {}, parameters: {}, template: () => "gain" } }) }),
      ),
    ).toThrowError(
      expect.objectContaining({
        context: {
          path: "voice.voice.filters.gain.template",
          reason: "unknownKey",
          value: expect.any(Function),
        },
      }),
    );
  });
});

tests/playback/PlaybackClock.test.ts.source:
import { describe, expect, it } from "vitest";
import { PlaybackClock } from "@/playback/PlaybackClock";
import { FakeMonotonicClock } from "../support/DeterministicScheduler";

describe("PlaybackClock", () => {
  it("anchors start, seek, pause, resume, replacement, and finish", () => {
    const clock = new FakeMonotonicClock();
    const playback = new PlaybackClock(clock);
    playback.start();
    clock.advanceBy(1500);
    expect(playback.position()).toBe(1.5);
    playback.seek(10);
    clock.advanceBy(500);
    expect(playback.position()).toBe(10.5);
    playback.pause();
    clock.advanceBy(5000);
    expect(playback.position()).toBe(10.5);
    playback.resume();
    clock.advanceBy(500);
    expect(playback.position()).toBe(11);
    playback.replace(2);
    expect(playback.position()).toBe(2);
    playback.finish();
    clock.advanceBy(1000);
    expect(playback.position()).toBe(2);
  });

  it("makes destruction idempotent and terminal", () => {
    const clock = new FakeMonotonicClock();
    const playback = new PlaybackClock(clock);
    playback.start(1);
    clock.advanceBy(1000);
    playback.destroy();
    playback.destroy();
    expect(playback.position()).toBe(2);
    expect(playback.state).toBe("destroyed");
    expect(() => playback.resume()).toThrow("destroyed");
  });

  it("validates anchors and treats redundant controls as no-ops", () => {
    const playback = new PlaybackClock(new FakeMonotonicClock());
    expect(() => playback.start(-1)).toThrow(RangeError);
    playback.pause();
    playback.resume();
    playback.seek(0);
    expect(playback.position()).toBe(0);
  });
});

tests/runtime/RuntimeLifecycle.test.ts.source:
import { describe, expect, it } from "vitest";
import { RuntimeLifecycle } from "@/runtime/RuntimeLifecycle";

describe("RuntimeLifecycle", () => {
  it("preserves initialization failure and gates later readiness", async () => {
    const lifecycle = new RuntimeLifecycle();
    const cause = new Error("startup failed");
    lifecycle.start(async () => {
      throw cause;
    });

    await expect(lifecycle.ready()).rejects.toBe(cause);
    expect(lifecycle.state).toEqual({ kind: "failed", error: cause });
  });

  it("gates readiness during and after destruction with the terminal cause", async () => {
    const lifecycle = new RuntimeLifecycle();
    lifecycle.start(async () => undefined);
    await lifecycle.ready();
    lifecycle.beginDestroy();
    await expect(lifecycle.ready()).rejects.toThrow("destroying or destroyed");
    const cause = new Error("cleanup failed");
    lifecycle.completeDestroy(cause);

    await expect(lifecycle.ready()).rejects.toBe(cause);
    lifecycle.beginDestroy();
    expect(lifecycle.state).toEqual({ kind: "destroyed", error: cause });
  });

  it("rejects duplicate initialization starts", () => {
    const lifecycle = new RuntimeLifecycle();
    lifecycle.start(async () => undefined);
    expect(() => lifecycle.start(async () => undefined)).toThrow("already started");
  });
});

tests/session/shuffleArray.test.ts.source:
import { describe, expect, it } from "vitest";
import { shuffleArray } from "@/queue/shuffle";

describe("shuffleArray", () => {
  it("uses an injected random source without mutating the input", () => {
    const input = ["one", "two", "three"] as const;
    const values = [0, 0];

    const shuffled = shuffleArray(input, () => values.shift() ?? 0);

    expect(shuffled).toEqual(["two", "three", "one"]);
    expect(input).toEqual(["one", "two", "three"]);
  });

  it("can produce an unchanged permutation", () => {
    expect(shuffleArray(["one", "two", "three"], () => 0.999)).toEqual(["one", "two", "three"]);
  });
});

tests/adapters/AdapterPorts.test.ts.source:
import { describe, expect, it } from "vitest";
import { compileAdapterPorts } from "@/adapters/AdapterPorts";
import { TestAdapter, voiceChannel } from "../support";

describe("compiled adapter ports", () => {
  it("keeps identity normalization synchronous and lifecycle separate", async () => {
    const adapter = new TestAdapter();
    const ports = compileAdapterPorts(adapter);

    expect(ports.identity.resolveGuildId(voiceChannel)).toBe(voiceChannel.guildId);
    expect(ports.identity.normalize("voiceChannel", voiceChannel)).toEqual(voiceChannel);
    expect(adapter.calls).toEqual([]);

    await ports.lifecycle.validateIntents();
    await ports.lifecycle.ready();
    await ports.lifecycle.destroy();
    expect(adapter.calls).toEqual(["adapter:intents", "adapter:ready", "adapter:destroy"]);
  });

  it("reports missing focused capabilities by name", () => {
    const ports = compileAdapterPorts(new TestAdapter());
    expect(() => ports.require(["voiceAdapterCreator"])).toThrowError(
      expect.objectContaining({ code: "ADAPTER_INCOMPATIBLE", context: { capability: "voiceAdapterCreator" } }),
    );
  });
});

