import { describe, expect, it } from "vitest";
import { verifyAdapterContract, verifySourceContract, verifyVoiceContract } from "@/testing/contracts";
import { TestAdapter, TestSourcePlugin, TestVoicePlugin, voiceChannel } from "../support";

describe("public integration contract kits", () => {
  it("verifies adapter, source, and selected voice contracts through public surfaces", async () => {
    const adapter = new TestAdapter();
    const source = new TestSourcePlugin();
    const voice = new TestVoicePlugin();

    const checks = [
      ...(await verifyAdapterContract(adapter, voiceChannel.guildId)),
      ...(await verifySourceContract(source.source)),
      ...(await verifyVoiceContract(voice.voice, adapter, voiceChannel)),
    ];

    expect(checks.every(check => check.passed)).toBe(true);
  });
});
